    '改：留白只由「记住的键盘高」决定（键盘高 + 6px），不再随视口变化 → 内容末尾和键盘上沿之间的间隙是恒定的一条小缝，滑到底就停在那儿',
    '加：键盘态滑到头（最底/最顶）还要继续拉时，直接吃掉这段手势 —— 不会再被系统拽出一大片空白再弹回来',
    '加：连点标题旁版本号 5 次，弹出的自查面板现在会实时显示 键盘态/键盘高记忆/可见底边/留白/滚动/内容末尾/间隙，遇到问题截个图就能一次定位',
