// 版本号只在这里写一次，设置页和关于页都读它
const APP_VERSION = 'v9.21';
let groupMap = new Map();
const WEEK = ['周日', '周一', '周二', '周三', '周四', '周五', '周六'];

function isoOf(d) {
  const p = n => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
}
function parseISO(s) {
  const [y, m, d] = s.split('-').map(Number);
  return new Date(y, m - 1, d);
}
function todayISO() { return isoOf(new Date()); }
function addDays(s, n) {
  const d = parseISO(s);
  d.setDate(d.getDate() + n);
  return isoOf(d);
}
function esc(s) {
  return String(s).replace(/[&<>"']/g, c => (
    { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}
function round(n) { return Math.round(Number(n) || 0); }

let toastTimer = null;

/* 提醒记录弹层的界面开关
   ── 现在的状态：只有顶部小横杠（66px），没有 ×，也没有标题
   ── 用户要求「恢复叉叉」时，按 v4.41 的样子恢复：
        closeX: true, showTitle: true, titleCenter: false
      这样标题会回到左上、和 ×（距顶 0.52 个圆角半径）同一条中心线、16px。
      注意：横杠宽度（66px）和卡片玻璃质感【不要】跟着回退，保持现状。 */
const NLOG_UI = { closeX: true, grab: true, titleCenter: false, showTitle: true };   // v8.31：和设置卡一样，固定「标题 + 完成」
let bodyTrendPage = 0;     // 体重趋势第几页（0 = 最新的 7 次记录）
let trSelDate = null;      // 趋势页体重图上点选的日期
let bodySelDate = null;    // 图上点选的那一天（不点 = 最近一次）
const WATCH_NAME = "Karen's Apple Watch";
const SCALE_NAME = "米家体脂秤";

// 统一提示：✅ 已更新：<更新了什么> <日期> · <哪台设备>
function updToast(what, date, device, ms = 2600) {
  const d = date ? ' ' + String(date).slice(5) : '';
  const main = `✅ 已更新：${what}${d}${device ? ' · ' + device : ''}`;
  // 放不下时：设备名整体换到下一行，不在词中间断开
  const alt = `✅ 已更新：${what}${d}${device ? '\n' + device : ''}`;
  toast(main, ms, alt);
}

function toast(msg, ms = 2200, alt) {
  const t = $('#toast');
  t.textContent = msg;
  t.classList.add('on');
  // 精确判断这行字会不会折行：量一遍不换行时有多宽，超过可用宽度就把「·」去掉
  if (alt) {
    try {
      const probe = document.createElement('span');
      probe.textContent = msg;
      probe.style.cssText = 'position:absolute;left:-9999px;top:0;visibility:hidden;white-space:nowrap;';
      probe.style.font = getComputedStyle(t).font;
      t.appendChild(probe);
      const full = probe.getBoundingClientRect().width;
      probe.remove();
      const cs = getComputedStyle(t);
      const avail = t.clientWidth - (parseFloat(cs.paddingLeft) || 0) - (parseFloat(cs.paddingRight) || 0);
      if (full > avail + 1) t.textContent = alt;
    } catch (e) {}
  }
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => t.classList.remove('on'), ms);
}

/* ---------------- 状态 ---------------- */
const SYNC_SHORTCUT = '热量采集';
let pendingSync = false;

const S = {
  date: todayISO(),
  today: todayISO(),
  day: null,
  foods: [],
  view: 'today',
  trendDays: 30,
  trend: null,
  addMode: 'photo',
  photoData: null,
  photoAt: null,
  photoURL: null,
  batchName: null,
  photo2Data: null,
  photo2URL: null,
  openGroups: new Set(),
  items: [],
  meal: 'lunch',
};

function defaultMeal() {
  const h = new Date().getHours();
  if (h < 10) return 'breakfast';
  if (h < 15) return 'lunch';
  if (h < 21) return 'dinner';
  return 'snack';
}

/* ---------------- 加载 ---------------- */
/* 照片仓库：第一次用到时初始化（把老 localStorage 照片搬进 IndexedDB + 读进内存镜像）。
   渲染要同步拿图，所以必须在第一次 loadDay 之前跑完 —— 统一在这里等一个 promise。 */
let photoReadyPromise = null;
function photosReady() {
  if (!photoReadyPromise) photoReadyPromise = photoInit().catch(() => ({}));
  return photoReadyPromise;
}

async function loadDay() {
  try {
    await photosReady();
    const d = await api('/api/bootstrap?date=' + S.date);
    S.day = d;
    S.foods = d.foods || [];
    renderToday();
    window.__booted = true;
    if (window.__bootT) clearTimeout(window.__bootT);
  } catch (e) {
    // 读失败时别把界面留在"全是破折号"：先自己再试一次，仍失败就给一条可点重试的提示
    console.warn('loadDay', e);
    if (!window.__dayRetried) {
      window.__dayRetried = true;
      setTimeout(loadDay, 800);
      return;
    }
    toast('加载失败：' + e.message, 4000);
    if (window.__showBootRetry) window.__showBootRetry('数据没读出来');
  }
}

/* ---------------- 渲染：今日 ---------------- */
function renderToday() {
  const d = S.day;
  if (!d) return;
  // 用实时时钟兜底：如果看的是"今天"但日期已经翻篇，直接切过去
  const nowDay = todayISO();
  if (S.date === S.today && nowDay !== S.today) {
    S.today = nowDay;
    S.date = nowDay;
    loadDay();
    return;
  }

  const dt = parseISO(d.date);
  $('#dateLabel').textContent = `${dt.getMonth() + 1}月${dt.getDate()}日`;
  const isToday = d.date === S.today;
  // 日期下面那行：直接写清"这份数据是几点同步的"，不用再往下找
  const watchAt = (d.watch && d.watch.source === 'cloud' && d.watch.cloudAt) ? String(d.watch.cloudAt).slice(11, 16) : '';
  $('#dateSub').textContent = isToday
    ? (watchAt ? `今天 · ${watchAt} 更新` : '今天 · 实时')
    : (watchAt ? `${WEEK[dt.getDay()]} · ${watchAt}` : WEEK[dt.getDay()]);
  $('#nextDay').disabled = isToday;
  $('#nextDay').style.opacity = isToday ? 0.45 : 1;

  const t = d.targets;
  const intake = d.intake;
  const expFull = d.expenditure;          // 全天预估/实际
  const balFull = d.balance;

  // 今天只算“到现在为止”的消耗，历史日期用全天值
  let dayFrac = 1;
  if (d.date === S.today) {
    const start = new Date(d.date + 'T00:00:00').getTime();
    dayFrac = Math.min(1, Math.max(0, (Date.now() - start) / 86400000));
  }
  // 今天：基础代谢按时间折算，手表的活动能量是“到现在为止”的，全额计入
  const det = d.expenditure_detail || {};
  let exp;
  if (d.date === S.today) {
    if (det.active && det.resting) exp = Math.round(det.resting * dayFrac) + det.active;
    else if (det.total) exp = Math.round(det.total * dayFrac);
    else exp = Math.round(expFull * dayFrac);
  } else {
    exp = expFull;
  }
  const bal = d.date === S.today ? exp - intake : balFull;
  const left = t.kcal_budget - intake;

  // 首次使用提示
  const sb = $('#setupBanner');
  if (d.needs_setup) {
    sb.innerHTML = `<button class="setup-tip" id="goSetup">
      <span>先填身高体重，消耗才算得准</span><b>去填 →</b></button>`;
    $('#goSetup').onclick = () => switchView('me');
  } else {
    sb.innerHTML = '';
  }

  // 主环
  const pct = t.kcal_budget > 0 ? intake / t.kcal_budget : 0;
  const ring = $('#ring');
  const C = 527.8;
  const dash = String(C * (1 - Math.min(pct, 1)));
  ring.style.strokeDashoffset = dash;
  const rim = $('#ringRim');
  if (rim) rim.style.strokeDashoffset = dash;      // 边光跟着同一段弧走

  // 颜色语言：绿=还有余量、橙=接近上限、红=已经吃超（盈余）
  // 颜色随进度平滑过渡：绿 → 橙 → 红
  const mix = (a, b, t) => {
    const p = h => [parseInt(h.slice(1,3),16), parseInt(h.slice(3,5),16), parseInt(h.slice(5,7),16)];
    const A = p(a), B = p(b);
    return '#' + A.map((v, i) => Math.round(v + (B[i] - v) * t).toString(16).padStart(2, '0')).join('');
  };
  let c0, c1, c2;
  if (pct <= 0.8) {
    c0 = '#d6ff4b'; c1 = '#57ffc8'; c2 = '#d6ff4b';
  } else if (pct <= 1) {
    const t = (pct - 0.8) / 0.2;
    c0 = mix('#d6ff4b', '#ffc44b', t);
    c1 = mix('#57ffc8', '#ff9a3d', t);
    c2 = mix('#d6ff4b', '#ff7a3d', t);
  } else {
    // 吃超了：橙 → 正红（以前中间那档是玫红，发粉）
    const t = Math.min(1, (pct - 1) / 0.15);
    c0 = mix('#ffc44b', '#ff6a4a', t);
    c1 = mix('#ff9a3d', '#ff2323', t);
    c2 = mix('#ff7a3d', '#ff3b30', t);
  }
  // 让弧线有一点渐变：起点亮一点、终点暗一点（同一个色系，不换色相）
  const shade = (hex, amt) => {
    const p = h => [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)];
    const f = v => Math.max(0, Math.min(255, Math.round(amt > 0 ? v + (255 - v) * amt : v * (1 + amt))));
    return '#' + p(hex).map(v => f(v).toString(16).padStart(2, '0')).join('');
  };
  $('#ringS0').setAttribute('stop-color', shade(c0, 0.26));
  $('#ringS1').setAttribute('stop-color', c1);
  $('#ringS2').setAttribute('stop-color', shade(c2, -0.22));


  // 一圈很淡的同色光晕：让环看着像玻璃，不是贴上去的色带
  const rgba = (hex, a) => {
    const p = h => [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)];
    const [r, g, b] = p(hex);
    return `rgba(${r}, ${g}, ${b}, ${a})`;
  };
  ring.style.filter = `drop-shadow(0 0 7px ${rgba(c1, 0.18)})`;

  const hero = $('#hero');
  hero.classList.remove('surplus', 'over');
  // 圈里的数字跟着圈的中间色走（吃超时就是那档红）
  hero.style.setProperty('--hero-c', c1);

  const goalDef = Math.round(t.deficit);   // 正=缺口，负=盈余
  let sub = goalDef > 0 ? `目标缺口 ${goalDef}` : (goalDef < 0 ? `目标盈余 ${-goalDef}` : '维持体重');
  if (bal < 0) {
    hero.classList.add('surplus');
    $('#heroLbl').textContent = '热量盈余';
    $('#heroNum').textContent = Math.abs(bal);
  } else {
    $('#heroLbl').textContent = '热量缺口';
    $('#heroNum').textContent = bal;
  }
  $('#heroSub').textContent = sub;

  $('#stIntake').innerHTML = intake + ' <small>kcal</small>';
  $('#stExp').innerHTML = exp + ' <small>kcal</small>';
  const leftEl = $('#stLeft');
  const at = (d.watch && d.watch.source === 'cloud' && d.watch.cloudAt) ? String(d.watch.cloudAt).slice(11) : '';
  // 看今天、但数据已经超过 90 分钟没更新 → 标一句「偏旧」，不用等发现数字不对
  let stale = false;
  if (at && isToday) {
    const hm = at.match(/(\d{1,2}):(\d{2})/);
    if (hm) { const t0 = parseISO(d.date); t0.setHours(+hm[1], +hm[2], 0, 0); stale = (Date.now() - t0.getTime()) > 90 * 60000; }
  }
  // 有"数据偏旧"时整行（时间 + 数据偏旧）一起变橙；没有就保持原色
  $('#stExpAt').textContent = at ? (at + (stale ? ' · 数据偏旧' : '')) : '';
  $('#stExpAt').style.color = stale ? 'var(--orange)' : '';
  leftEl.innerHTML = (left >= 0 ? left : left) + ' <small>kcal</small>';
  leftEl.style.color = left < 0 ? 'var(--orange)' : '';

  // 营养素
  const pr = d.protein, cb = d.carb, ft = d.fat;
  $('#pNow').textContent = Math.round(pr);
  $('#pGoal').textContent = t.protein_g;
  $('#cNow').textContent = Math.round(cb);
  $('#cGoal').textContent = t.carb_g;
  $('#fNow').textContent = Math.round(ft);
  $('#fGoal').textContent = t.fat_g;
  const w = (v, g) => Math.min(100, g > 0 ? (v / g) * 100 : 0) + '%';
  $('#pBar').style.width = w(pr, t.protein_g);
  $('#cBar').style.width = w(cb, t.carb_g);
  $('#fBar').style.width = w(ft, t.fat_g);

  renderMeals();
  // 换过设备 / 照片只在云端时：把当天缺的小图按需拉回来（最多 4 张，拉完重画一次列表）
  try {
    const miss = [...new Set((d.logs || []).map(l => l.batch).filter(b => b && !shotUrl(b)))].slice(0, 12);
    if (miss.length) {
      Promise.all(miss.map(b => ensurePhoto(b))).then(list => {
        if (list.some(Boolean)) renderMeals();
      }).catch(() => {});
    }
  } catch (e) {}
}

/* 营养克数的显示：小于 10 保留一位小数，别把 0.3g 显示成 0 */
function g1(v) {
  const n = Number(v) || 0;
  if (Math.abs(n - Math.round(n)) < 0.05) return String(Math.round(n));   // 整数就显示整数
  return String(Math.round(n * 10) / 10);                                  // 12.5 不能被抹成 13
}

function renderMeals() {
  const d = S.day;
  const box = $('#meals');
  const shots = d.shots || {};
  // 图可能在：本机 IndexedDB 的内存镜像（shotUrl，刚补传/刚拉回来的也在这里）或快照里的 shots
  const thumbOf = l => {
    const u = (l.batch && shotUrl(l.batch)) || (l.batch && shots[l.batch]) || '';
    return u ? `<img class="mthumb" src="${u}" alt="">` : '';
  };
  const itemRow = l => `
      <div class="mitem" data-item="${l.id}">
        ${thumbOf(l)}
        <div class="n">${nameLine(l.name, `data-pen="${l.id}"`)}
          <span class="sub">${l.grams ? g1(l.grams) + 'g' : ''}${
            l.p ? ' · 蛋' + g1(l.p) + '·碳' + g1(l.c) + '·脂' + g1(l.f) : ''}<button class="pen inl" data-nutlog="${l.id}" aria-label="改营养数据">${PEN_ICON}</button></span>
        </div>
        <div class="k">${Math.round(l.kcal)}${l.source === 'photo' || l.source === 'ai' ? ' <span class="ai">AI</span>' : ''}</div>
        <span class="chev">›</span>
        <button class="del" data-del="${l.id}">×</button>
      </div>`;

  // 同一次识别出来的多条，收成一行（例如「沙县小吃」→ 展开是青菜/鸡腿/米饭）
  // 老数据没有 batch 标记，就按「同一餐 + 同一秒」归堆
  const groupsById = new Map();
  const groupRows = items => {
    const groups = [];
    const seen = new Map();
    items.forEach(l => {
      const key = l.batch || ('L' + (l.meal || '') + '|' + (l.ts || ''));
      if (!seen.has(key)) {
        const g = { key, name: l.batchName || '', logs: [] };
        seen.set(key, g);
        groups.push(g);
        groupsById.set(key, g);
      }
      seen.get(key).logs.push(l);
    });
    return groups.map(g => {
      if (g.logs.length < 2) return itemRow(g.logs[0]);
      const open = S.openGroups.has(g.key);
      const kcal = Math.round(g.logs.reduce((a, b) => a + (b.kcal || 0), 0));
      const p = g.logs.reduce((a, b) => a + (b.p || 0), 0);
      const c = g.logs.reduce((a, b) => a + (b.c || 0), 0);
      const f = g.logs.reduce((a, b) => a + (b.f || 0), 0);
      return `
      <div class="mitem ghead" data-group="${esc(g.key)}">
        ${thumbOf(g.logs[0])}
        <div class="n">${nameLine(g.name || '未命名', `data-pen-g="${esc(g.key)}"`)}
          <span class="sub">${g.logs.length} 项 · 蛋${Math.round(p)}·碳${Math.round(c)}·脂${Math.round(f)}</span>
        </div>
        <div class="k">${kcal}</div>
        <span class="chev">›</span>
        <button class="del" data-gdel-g="${esc(g.key)}">×</button>
      </div>`;
    }).join('');
  };

  box.innerHTML = MEALS.map(m => {
    const items = d.logs.filter(l => (l.meal || 'other') === m.k);
    const kcal = items.reduce((a, b) => a + (b.kcal || 0), 0);
    const rows = groupRows(items);
    return `
      <div class="meal ${items.length ? 'has' : ''}">
        <div class="hd">
          <span class="dot"></span>
          <span class="nm">${m.n}</span>
          <span class="kc">${items.length ? Math.round(kcal) + ' 千卡' : ''}</span>
          <button class="add" data-add="${m.k}">＋</button>
        </div>
        ${items.length ? `<div class="items">${rows}</div>`
                       : `<div class="empty">还没记录</div>`}
      </div>`;
  }).join('');

  groupMap = groupsById;
  $$('[data-group]', box).forEach(b => b.onclick = () => openGroup(b.dataset.group));
  $$('[data-item]', box).forEach(b => b.onclick = ev => {
    if (ev.target.closest('[data-del]') || ev.target.closest('[data-pen]') || ev.target.closest('[data-gdel-g]')) return;
    openDetail([d.logs.find(l => String(l.id) === b.dataset.item)].filter(Boolean), false);
  });

  // 名字边上的小铅笔：改这一条的名字（识别错了也能自己改回来）
  $$('[data-nutlog]', box).forEach(b => b.onclick = ev => {
    ev.stopPropagation();
    openNutEditLog(b.dataset.nutlog);
  });
  $$('[data-pen]', box).forEach(b => b.onclick = async ev => {
    ev.stopPropagation(); ev.preventDefault();
    const l = d.logs.find(x => String(x.id) === b.dataset.pen);
    if (!l) return;
    const name = await askName('这个食物叫什么？', l.name || '');
    if (name === null) return;
    const v = name;
    if (!v) return;
    const sameName = v === l.name;            // 改成同一个名字 = 再查一次营养（重试入口）
    try {
      if (!sameName) await api('/api/logs/rename', { ids: [l.id], name: v, item: true });
      await loadDay();
      if (S.view === 'trends') loadTrends();
      // 改名立刻生效；营养异步换成本新食物的（查不到就原样留着 + 提示）
      renutrifyLogs([l.id], v, sameName,
        sameName ? `重新查「${v}」的营养…` : `已改名：${v} · 正在查营养…`);
    } catch (e) { toast(e.message); }
  });
  $$('[data-pen-g]', box).forEach(b => b.onclick = async ev => {
    ev.stopPropagation(); ev.preventDefault();
    const g = groupsById.get(b.dataset.penG);
    if (!g) return;
    const name = await askName('这份叫什么？（比如：沙县小吃）', g.name || '');
    if (name === null) return;
    const v = name;
    if (!v || v === g.name) return;
    try {
      // 整组改名只是给这一组起个标签，**不动营养**（一组里可能是 5 种不同的食物）
      await api('/api/logs/rename', { ids: g.logs.map(l => l.id), name: v, item: false });
      await loadDay();
      toast('已改名：' + v, 1800);
    } catch (e) { toast(e.message); }
  });

  // 整组那一行的 × ：删掉这一组的所有条目
  $$('[data-gdel-g]', box).forEach(b => b.onclick = async ev => {
    ev.stopPropagation();
    const g = groupsById.get(b.dataset.gdelG);
    if (!g) return;
    try {
      for (const l of g.logs) await api('/api/logs/' + l.id, null, 'DELETE');
      await loadDay();
      if (S.view === 'trends') loadTrends();
      toast('已删除这一组', 1600);
    } catch (e) { toast(e.message); }
  });

  $$('[data-del]', box).forEach(b => b.onclick = async ev => {
    ev.stopPropagation();
    try {
      await api('/api/logs/' + b.dataset.del, null, 'DELETE');
      await loadDay();
      if (S.view === 'trends') loadTrends();
    } catch (e) { toast(e.message); }
  });

  $$('[data-add]', box).forEach(b => b.onclick = () => {
    openAdd(b.dataset.add);
  });
}

/* ---------------- 弹层叠放顺序 ---------------- */
/* 记录卡片 / 营养编辑 / 提醒记录 可能同时开着：谁最后打开谁在最上面，
   所以打开时统一往上抬一层（按打开顺序叠，不写死 z-index） */
let sheetZ = 60;
function raiseSheet(id) {
  const el = typeof id === 'string' ? $(id) : id;
  if (!el) return;
  el.style.zIndex = String(++sheetZ);
}

/* ---------------- 记录弹层 ---------------- */

/* 搜索框固定在卡片上：位置就放在它原来的地方（面板顶部），
   并把滚动内容的上边距补成它原来占的高度 —— 位置一点不挪，只是不跟着滚 */
function placeSearchInput() {
  const sheet = $('#addSheet');
  const input = $('#searchInput');
  const pane = $('#pane-search');
  if (!sheet || !input || !pane || pane.hidden) return;
  // v8.99：面板 position:relative，搜索框的 top 由 CSS 给（和三格条上方那道缝同宽）；
  // 这里只把它的高度记成变量，让滚动区自己算「开场时从搜索框下面开始」。
  pane.style.setProperty('--si-h', Math.round(input.offsetHeight) + 'px');
  // 上内边距 = 搜索框高度 + 13（三格条那道缝）；滚动区就紧接在它下面开始
  pane.style.paddingTop = Math.round(input.offsetHeight + 13) + 'px';
}

function syncAddTabsH() {
  const t = $('#addTabs');
  if (!t || !t.offsetHeight) return;
  document.documentElement.style.setProperty('--addtabs-h', t.offsetHeight + 'px');
}

function openAdd(meal) {
  S.items = [];
  S.meal = meal || defaultMeal();
  S.batchName = null;
  $('#batchName').value = '';
  resetPhotoUI();
  restoreDraft();
  $('#photoHint').value = '';
  $('#resultArea').hidden = true;
  $('#addFoot').hidden = true;
  $('#searchInput').value = '';
  const ta = $('#textInput'); if (ta) ta.value = '';   // v9.07 描述板块已移除
  $('#searchList').innerHTML = '';
  $('#searchList').hidden = false;
  $('#addTabs').hidden = false;
  $('#searchInput').value = '';
  setAddMode('photo');
  renderMealPick();
  renderRecent();

  closeOtherCards('add');                    // 三张卡同时只允许开一张
  raiseSheet('#addSheet');                   // 刚打开的弹层放到最上面
  document.body.classList.add('add-open');   // 用和提醒记录一样的浅遮罩，玻璃才透得出来
  initAddTabsLens();
  // 打开卡片：滑块直接落在「拍照」上（不从上一次停的那格滑过来），而且一出现就是实色
  if (window.__addTabsLens) window.__addTabsLens.sync(true, true);
  setTimeout(() => { if (window.__addTabsLens) window.__addTabsLens.sync(); }, 60);
  // 打开后量一次「空闲静态高度」（首帧还没量过时卡片会先按 62dvh 显示，量完立刻贴回内容高度）
  setTimeout(() => { try { measureAddStaticH(); } catch (e) {} }, 80);
  setTimeout(() => { try { measureAddStaticH(); } catch (e) {} }, 420);
  $('#addMask').classList.add('on');
  $('#addSheet').classList.add('on');
  // 三格条的真实高度（搜索框要粘在它下面），等卡片显示后再量
  requestAnimationFrame(() => { try { syncAddTabsH(); placeSearchInput(); } catch (e) {} });
  setTimeout(() => { try { syncAddTabsH(); placeSearchInput(); } catch (e) {} }, 90);
}
function closeAdd() {
  document.body.classList.remove('add-open');
  $('#addMask').classList.remove('on');
  const sh = $('#addSheet');
  // 下滑关闭时脚本写过 transform，这里必须清掉，否则下次打开会停在半路
  sh.classList.remove('dragging');
  sh.style.transform = '';
  sh.style.opacity = '';
  sh.classList.remove('on');
}

/* 记录卡片里那三个选项（拍照/搜索/描述）、趋势页 7/30/90、目标模式三格：
   全部沿用 Dock 那颗玻璃滑块（.dock-lens / initDockLens）的做法 —— 同一套结构、同一组时间。
   - 外层 .seg-lens 只负责"位置"（translate，.62s 过冲曲线）
   - 内层 .lens-body 只负责"按压压扁"（scale，.24s）
   分两层是因为：位置和缩放在同一个 transform 上时，按下去那一下会把还没走完的滑动打断 → 看着就是"跳"。
   还有一条和 Dock 一致：按下就认这一格（target），松手**绝不**先弹回旧格再滑过来。 */
const segLensMem = {};   // 记住每一条滑块最后停在哪，DOM 被重建时能接着落位，不会"跳一下"
function initSegLens(wrap) {
  if (!wrap || wrap.dataset.lens) return;
  wrap.dataset.lens = '1';
  const key = wrap.id || wrap.className || 'seg';
  const lens = document.createElement('span');
  lens.className = 'seg-lens';
  const body = document.createElement('span');
  body.className = 'lens-body';
  lens.appendChild(body);
  wrap.prepend(lens);

  // 用布局坐标（offset*）而不是 getBoundingClientRect：
  // 卡片弹出时有个 scale(.98) 的过渡，用 rect 量出来的尺寸会小 2%，滑块就会偏小、看着不居中
  const geoOf = el => {
    const w = el.offsetWidth, h = el.offsetHeight;
    if (!w || !h) return null;
    let x = 0, y = 0, n = el;
    while (n && n !== wrap) { x += n.offsetLeft; y += n.offsetTop; n = n.offsetParent; }
    return { x: Math.round(x) + 1, y: Math.round(y) + 1, w: w - 2, h: h - 2 };
  };
  // 尺寸只在第一次（或格子尺寸明显变了）时写一次；平时只改 transform，
  // 这样动画过程中不需要重新排版，iOS 上才不会抖
  let cellW = 0, cellH = 0;
  const apply = (g) => {
    if (Math.abs(g.w - cellW) > 2 || Math.abs(g.h - cellH) > 2) {
      cellW = g.w; cellH = g.h;
      lens.style.width = g.w + 'px';
      lens.style.height = g.h + 'px';
    }
    lens.style.transform = 'translate3d(' + g.x + 'px,' + g.y + 'px,0)';
    lens.classList.add('on');
  };

  let primed = false;      // 有没有过一次"不带动画"的落位（防止第一次显示时从左上角滑下来）
  const jump = el => {                 // 不播动画，直接落位（首次出现 / 整块被重建后接上老位置）
    const g = el && geoOf(el);
    if (!g) return false;
    lens.classList.add('noanim');
    apply(g);
    void lens.offsetWidth;
    lens.classList.remove('noanim');
    segLensMem[key] = g;
    primed = true;
    return true;
  };
  // remember=false 用在"按住"的时候：那只是预览位置，不能当成最终落点记下来，
  // 否则重画时新滑块会直接从按住的位置出现，看不到滑过去的过程
  const place = (el, remember = true) => {
    const g = el && geoOf(el);
    if (!g) return;
    if (remember) segLensMem[key] = g;
    apply(g);
  };
  // 这条滑块之前停在别处（DOM 刚被重建）→ 先瞬移到老位置，再滑过去
  const mem = segLensMem[key];
  if (mem) {
    lens.classList.add('noanim');
    apply(mem);
    void lens.offsetWidth;
    lens.classList.remove('noanim');
    primed = true;
  }

  // 「玻璃 → 实色」和 Dock 同一组数：按住 0.25 秒淡回玻璃（跟手），
  // 停下后等 520ms，再用 2.2 秒慢慢渗成实色
  let glassUntil = 0;                  // 正在"玻璃→实色"过渡中，到这个时刻为止
  const settle = (delay, instant) => {
    if (instant) {
      // 注意：这里**绝不能**先 clearTimeout(__settleT) —— 那会把"松手后加 settled"的定时器清掉，
      // 结果就是按完一直停在玻璃状态
      if (Date.now() < glassUntil) return;                 // 正在淡入 → 让它走完，不插队
      clearTimeout(lens.__settleT);
      clearTimeout(lens.__fadeT);
      lens.classList.remove('fadein', 'fadeout');
      lens.classList.add('settled');                       // 不过渡：直接就是实色
      return;
    }
    clearTimeout(lens.__settleT);
    // 关键：上一轮"摘掉 fadein"的定时器必须作废。
    // 否则它会在这一轮淡入走到一半时把 fadein 摘掉 → 过渡立刻消失 → 1 帧跳到全实色
    // （表现就是"多按几次以后，颜色又啪一下变成实色"，v7.59 查到的真因）
    clearTimeout(lens.__fadeT);
    // 有意的操作：先关掉实色（fadeout 的快节奏），再等 delay 后用 fadein 慢慢亮回来
    lens.classList.remove('settled');
    glassUntil = Date.now() + delay + 2400;
    lens.__settleT = setTimeout(() => {
      lens.classList.add('fadein');
      void lens.offsetWidth;                               // 先让 2.2s 的过渡生效，再改 opacity
      lens.classList.add('settled');
      lens.__fadeT = setTimeout(() => lens.classList.remove('fadein'), 2600);
    }, delay);
  };

  let target = null;                   // 滑块现在认哪一格（按下就认，不跟着 class 回弹）
  let pressedEl = null;

  // 切页 / 重画 / 首次定位：直接落位 + 直接实色，不播动画
  // hard=true：连"从上次停的那格滑过来"都不要（打开记录卡片时用，滑块要一出现就在「拍照」上）
  const sync = (instant, hard) => {
    if (pressedEl) return;             // 手指还按着 → 以手指为准
    lens.classList.remove('press');
    const on = wrap.querySelector('button.on');   // 这里以"选中"为准：重开卡片/切页时不能被上次按下的那格带跑
    if (!on) return;
    target = on;
    if (!primed || hard) { if (!jump(on)) return; } else place(on);
    if (instant !== false) settle(0, true);
  };
  window.__addTabsLens = { sync };     // 记录卡片打开后补一次定位（其它几条也用同一个入口同步）
  wrap.__lensSync = sync;

  // 同一帧内多次触发只做一次，避免连点/重绘把滑块来回拽
  let raf = 0;
  const syncSoon = () => {
    if (raf) return;
    raf = requestAnimationFrame(() => { raf = 0; sync(); });
  };

  wrap.addEventListener('pointerdown', ev => {
    const b = ev.target.closest('button');
    if (!b) return;
    pressedEl = b;
    target = b;                        // 按下去就认这一格，松手不会弹回原来那格
    lens.classList.add('fadeout');     // 按住/滑动中是玻璃（0.25 秒，跟手）
    lens.classList.remove('settled', 'fadein');
    clearTimeout(lens.__fadeoutT);     // 连点时上一轮的"摘 fadeout"不能提前取消这一轮的过渡
    lens.__fadeoutT = setTimeout(() => lens.classList.remove('fadeout'), 320);
    place(b, false);                   // 按下去就直接滑到手指这一格（不记账）
    lens.classList.add('press');       // 压扁只动内层，不打断还没走完的滑动
  }, { passive: true });

  // 松手时不要立刻弹回原来的格子 —— 那样会"过去又回来"晃一下（就是之前那个"跳"）。
  // 等点击结果落地（或在 900ms 后确认没生效）才决定要不要回位。
  const settleUp = () => {
    const el = pressedEl;
    pressedEl = null;
    if (!el) return;          // 没按在这一排上 → 什么都不做（否则点页面任何地方都会闪一下实色）
    lens.classList.remove('press');
    settle(520);              // 和 Dock 同一个延迟（Dock 是 settle(520)）；
                              // 必须在这里排上，否则紧接着的 sync 会把它直接拍成实色
    setTimeout(() => {        // 10ms：先让 click 把 .on 切过去，这一步才不会有位移
      if (pressedEl) return;
      place(target || el, false);
    }, 10);
    setTimeout(() => {
      if (!wrap.isConnected) return;              // 整块已经被重画，新滑块自己会接上
      const on = wrap.querySelector('button.on');
      if (on && on !== target) { target = on; place(on); settle(520); }   // 按了但没切过去 → 回位
    }, 900);
  };
  window.addEventListener('pointerup', settleUp, { passive: true });
  window.addEventListener('pointercancel', settleUp, { passive: true });

  // 只要哪一格变成选中就跟着走（不依赖各页自己的点击处理）
  const mo = new MutationObserver(syncSoon);
  wrap.querySelectorAll('button').forEach(b => mo.observe(b, { attributes: true, attributeFilter: ['class'] }));

  requestAnimationFrame(() => requestAnimationFrame(() => sync()));
  window.addEventListener('resize', () => setTimeout(sync, 120));
}
function initAddTabsLens() {
  initSegLens($('#addTabs'));
  const w = $('#addTabs');
  // 从这里挂全局入口：initSegLens 已经初始化过时不会再赋值，直接指过来才不会指到别的那条
  if (w && w.__lensSync) window.__addTabsLens = { sync: w.__lensSync };
}
function initTrendSegLens() { initSegLens($('#trendSeg')); }

let addMode = 'photo';
/* 记录区（识别结果 + 合计 + 记到哪一餐 + 记入按钮）只在「拍照」页显示。
   描述页/搜索页只负责输入，不要把结果挂在那两页下面 —— 用户明确要求过 */
/* v9.08 用户口径：
   · 空闲（没照片、没食品）时卡片高度定死，且「拍照 / 搜索」完全一致；
   · 加了照片或食品后按内容长高，多了就在卡内滚。
   实现：卡片本身 height:auto，下限用 --add-static-h —— 这个值在“拍照页空闲”时量一次。 */
/* v9.15：按列宽算出「照片格」的高度（宽 : 高 = 1 : 1.3），写成 --slot-h。
   不在 CSS 里用 aspect-ratio —— iOS Safari 在网格里算出来的高度有偏差，
   会让「从相册选」按钮溢出盒子、和下面的「已添加」叠在一起。 */
function syncSlotH() {
  const pane = $('#pane-photo');
  if (!pane) return;
  const box = pane.querySelector('.drop.photobox');
  if (!box) return;
  const w = box.clientWidth;
  if (!w) return;
  const inner = w - 24 - 12;            // 左右 padding 12*2 + 两列间距 12
  const slotH = Math.round((inner / 2) * 1.3);
  if (slotH > 40) document.documentElement.style.setProperty('--slot-h', slotH + 'px');
}

function measureAddStaticH() {
  const s = $('#addSheet'), pane = $('#pane-photo');
  if (!s || !pane || pane.hidden) return;
  if (S.photoData || S.photo2Data || (S.items || []).length) return;   // 只在空闲态量
  if (!s.classList.contains('on')) return;                             // 只在卡片打开时量
  try { syncSlotH(); } catch (e) {}
  const pb = pane.querySelector('.drop.photobox');
  if (!pb) return;
  // 不再「临时摘掉下限再量整张卡」—— 那套在真机上量到过动画中的高度，把 --add-static-h 写大，
  // 之后每次都撑出一大块空白。现在直接用内容算：
  //   卡片顶 → 照片大框底，再加上内容区底部内边距 = 空闲时卡片应该有的高度
  const sr = s.getBoundingClientRect(), pr = pb.getBoundingClientRect();
  const body = s.querySelector('.sh-body');
  const z = (pane.offsetHeight ? (pane.getBoundingClientRect().height / pane.offsetHeight) : 1) || 1;
  const padB = (parseFloat(getComputedStyle(body).paddingBottom) || 0) * z;
  const h = Math.round(pr.bottom - sr.top + padB);
  if (h > 120) document.documentElement.style.setProperty('--add-static-h', h + 'px');
}
function syncAddSheetFit() {
  const s = $('#addSheet');
  if (!s) return;
  const busy = !!(S.photoData || S.photo2Data || (S.items || []).length);
  s.classList.toggle('fitted', busy);
  // 空闲时量一次静态高度（切回拍照页 / 清空之后）
  if (!busy) { try { measureAddStaticH(); } catch (e) {} }
}

function syncResultVisibility() {
  try { syncAddSheetFit(); } catch (e) {}
  const on = addMode === 'photo';
  const area = $('#resultArea'), foot = $('#addFoot');
  if (area) area.hidden = !on || !(S.items || []).length;
  if (foot) foot.hidden = !on || !(S.items || []).length;
}

function setAddMode(m) {
  requestAnimationFrame(() => { try { syncAddTabsH(); placeSearchInput(); } catch (e) {} });
  S.addMode = m;
  addMode = m;
  $$('#addTabs button').forEach(b => b.classList.toggle('on', b.dataset.m === m));
  syncResultVisibility();
  ['photo', 'search'].forEach(k => {
    const el = $('#pane-' + k);
    if (el) el.hidden = k !== m;
  });
  if (m === 'search') {
    $('#searchList').hidden = false;              // 回到搜索就一定能继续挑
    runSearch($('#searchInput').value || '');
    // 每次进来都回到列表最上面（相当于重新开始挑）
    const sb = document.querySelector('#addSheet .sh-body');
    if (sb) sb.scrollTop = 0;
  }
  if (window.__addTabsLens) requestAnimationFrame(() => window.__addTabsLens.sync());
}

/* 「描述」框中间那层示例文字：框里有字就隐藏，空着就显示 */
function syncTextPh() {
  const ta = $('#textInput'), ph = $('#textPh');
  if (!ta || !ph) return;
  ph.hidden = !!String(ta.value || '').trim();
}

function renderMealPick() {
  $$('#mealPick .chip').forEach(c => c.classList.toggle('on', c.dataset.meal === S.meal));
}

function renderRecent() {
  const box = $('#recentChips');
  const seen = [];
  (S.day?.logs || []).forEach(l => {
    if (!seen.includes(l.name)) seen.push(l.name);
  });
  const picks = seen.slice(0, 6);
  if (picks.length < 4) {
    ['鸡蛋', '米饭', '牛奶(全脂)', '鸡胸肉(生)', '香蕉'].forEach(n => {
      if (!picks.includes(n)) picks.push(n);
    });
  }
  box.innerHTML = picks.slice(0, 7).map(n =>
    `<button class="chip" data-quick="${esc(n)}">${esc(n)}</button>`).join('');
  // v8.80 修：以前只按「名字一字不差」在食物库里找，找不到就什么都不发生（点「麦片生」没反应，
  // 因为库里叫「燕麦片(干)」）。现在先做宽容匹配（忽略空格/标点、忽略括号里的备注），
  // 仍然找不到就把这个名字填进搜索框、把搜索结果直接列出来让他挑 —— 点任何一颗常用词都一定有反馈。
  $$('[data-quick]', box).forEach(b => b.onclick = () => {
    const q = b.dataset.quick;
    const f = S.foods.find(x => x.name === q)
      || S.foods.find(x => normName(x.name) === normName(q))
      || S.foods.find(x => normBare(x.name) === normBare(q));
    if (f) { pushFood(f); return; }
    const inp = $('#searchInput');
    if (inp) inp.value = q;
    $('#searchList').hidden = false;
    runSearch(q);
  });
}

/* ---- 拍照 ---- */
async function compress(file, max = 1280, q = 0.82) {
  const bmp = await new Promise((res, rej) => {
    if (window.createImageBitmap) {
      createImageBitmap(file).then(res).catch(rej);
    } else {
      const img = new Image();
      img.onload = () => res(img);
      img.onerror = rej;
      img.src = URL.createObjectURL(file);
    }
  });
  const scale = Math.min(1, max / Math.max(bmp.width, bmp.height));
  const c = document.createElement('canvas');
  c.width = Math.round(bmp.width * scale);
  c.height = Math.round(bmp.height * scale);
  c.getContext('2d').drawImage(bmp, 0, 0, c.width, c.height);
  return c.toDataURL('image/jpeg', q);
}

async function handlePhoto(file) {
  if (!file) return;
  try {
    if (S.photoURL) URL.revokeObjectURL(S.photoURL);
    S.photoURL = URL.createObjectURL(file);
    $('#photoPreview').src = S.photoURL;
    $('#photoPreview').hidden = false;
    $('#photoDel').hidden = false;
    $('#emptyA').hidden = true;
    S.photoData = await compress(file);
    S.photoAt = Date.now();
    $('#photoActions').hidden = false;
    try { syncAddSheetFit(); } catch (e) {}
    saveDraft();
  } catch (e) {
    toast('图片读取失败');
  }
}

/* 一组按钮：先填 ① 食物照片，再填 ② 营养成分表 */
async function handlePick(file) {
  if (!file) return;
  if (!S.photoData) return handlePhoto(file);
  if (!S.photo2Data) return handlePhoto2(file);
  toast('两张都拍好了。点照片上的 × 可以换一张', 3000);
}

async function handlePhoto2(file) {
  if (!file) return;
  try {
    if (S.photo2URL) URL.revokeObjectURL(S.photo2URL);
    S.photo2URL = URL.createObjectURL(file);
    $('#pv2').src = S.photo2URL;
    $('#pv2').hidden = false;
    $('#del2').hidden = false;
    $('#emptyB').hidden = true;
    S.photo2Data = await compress(file, 1024, 0.8);
    try { syncAddSheetFit(); } catch (e) {}
    saveDraft();
  } catch (e) {
    toast('图片读取失败');
  }
}

/* ---------------- 拍照草稿：关掉卡片 / 退出 App 也不丢 ---------------- */
const DRAFT_KEY = 'calorie-ledger-draft';
function readDraft() {
  try {
    const raw = localStorage.getItem(DRAFT_KEY);
    if (!raw) return null;
    const d = JSON.parse(raw);
    if (!d || !d.at || Date.now() - d.at > 24 * 3600e3) { localStorage.removeItem(DRAFT_KEY); return null; }
    return d;
  } catch (e) { return null; }
}
function saveDraft() {
  const d = { photo: S.photoData || null, photo2: S.photo2Data || null, at: Date.now() };
  try {
    if (!d.photo && !d.photo2) localStorage.removeItem(DRAFT_KEY);
    else localStorage.setItem(DRAFT_KEY, JSON.stringify(d));
  } catch (e) { /* 存不下就算了 */ }
}
function clearDraft() {
  try { localStorage.removeItem(DRAFT_KEY); } catch (e) {}
}
/* 把草稿里的照片放回界面 */
function restoreDraft() {
  const d = readDraft();
  if (!d) return;
  if (d.photo) {
    S.photoData = d.photo;
    $('#photoPreview').src = d.photo;
    $('#photoPreview').hidden = false;
    $('#photoDel').hidden = false;
    $('#emptyA').hidden = true;
  }
  if (d.photo2) {
    S.photo2Data = d.photo2;
    $('#pv2').src = d.photo2;
    $('#pv2').hidden = false;
    $('#del2').hidden = false;
    $('#emptyB').hidden = true;
  }
  if (d.photo || d.photo2) $('#photoActions').hidden = false;
  try { syncAddSheetFit(); } catch (e) {}
}

/* 把拍照区恢复成「还没选图」的样子 */
function resetPhotoUI() {
  if (S.photoURL) { URL.revokeObjectURL(S.photoURL); S.photoURL = null; }
  const pv = $('#photoPreview');
  pv.removeAttribute('src');
  pv.hidden = true;
  $('#photoDel').hidden = true;
  $('#emptyA').hidden = false;
  S.photoData = null;
  S.photoAt = null;
  $('#photoDrop').hidden = false;
  $('#pane-photo').classList.remove('done');
  $('#photoActions').hidden = true;
  if (S.photo2URL) { URL.revokeObjectURL(S.photo2URL); S.photo2URL = null; }
  S.photo2Data = null;
  $('#pv2').removeAttribute('src');
  $('#pv2').hidden = true;
  $('#del2').hidden = true;
  $('#emptyB').hidden = false;
  try { syncAddSheetFit(); } catch (e) {}
}

async function runPhoto() {
  const main = S.photoData || S.photo2Data;
  if (!main) return toast('先拍一张照片');
  const btn = $('#photoGo');
  const old = btn.innerHTML;
  btn.disabled = true;
  btn.innerHTML = '<span class="spinner"></span> 识别中…';
  try {
    const grams = Number(($('#photoGrams') || {}).value) || 0;
    const dishName = (($('#photoName') || {}).value || '').trim();
    let hint = $('#photoHint').value.trim();
    if (dishName) hint = '用户说这是：' + dishName + '（请按这个食材估算，不要换品种）' + (hint ? '；' + hint : '');
    let modeHint;
    if (S.photoData && S.photo2Data) {
      modeHint = '第一张图是实际吃的食物本体，第二张图是包装上的营养成分表。'
        + '请按第二张的标签读每 100 克的能量/蛋白质/碳水/脂肪（不要用外观估算这几项），'
        + '再按第一张估算实际吃掉了多少克；两两相乘得到总量。';
    } else if (S.photoData) {
      modeHint = '这张图是食物本体：按外观和常见餐具尺寸估算实际吃掉的重量。';
    } else {
      modeHint = '这张图是包装上的营养成分表：每 100 克数值只按标签读数；name 用产品名。';
    }
    hint = hint ? modeHint + '；' + hint : modeHint;
    if (grams > 0) hint = hint + `；我实际吃了 ${grams} 克`;
    // 有食物图就用它当主图；只拍了成分表就反过来
    const hasFood = !!S.photoData;
    const r = await api('/api/ai/food', {
      image: hasFood ? S.photoData : S.photo2Data,
      image2: hasFood ? (S.photo2Data || null) : null,
      hint,
    });
    /* v9.21 用户口径：既拍照、又从搜索加了食物时，两边都要留下、一起统计。
       以前这里直接 `S.items = 识别结果`，会把搜索里已经加进来的全冲掉。
       现在：搜索加的（_src !== 'photo'）原样保留，识别出来的接在后面。 */
    const fromPhoto = r.items.map(x => applyKnownFood({ ...x, _src: 'photo' }));
    const kept = (S.items || []).filter(it => it && it._src !== 'photo');
    const photoBase = kept.length;                 // 识别结果从这一位开始
    S.items = kept.concat(fromPhoto);
    // 读表读串了（碳水/脂肪串行、数字多一位）→ App 自己用营养表那张照片重读一次，
    // 不让用户去核对数字（用户明确要求：你自己读出来的数，你自己得认）。
    // 只在"当前显示的就是这次读出来的数"时才自检/重读：要是历史里你手改过的值赢了，绝不许覆盖。
    if (fromPhoto.length === 1 && r.items.length === 1) {
      const one = S.items[photoBase], src = r.items[0];
      const fromThisRead = one.kcal_per_100g === src.kcal_per_100g
        && one.protein_per_100g === src.protein_per_100g
        && one.carb_per_100g === src.carb_per_100g
        && one.fat_per_100g === src.fat_per_100g;
      if (fromThisRead && (src._suspect || !nutSane(one.kcal_per_100g, one.protein_per_100g, one.carb_per_100g, one.fat_per_100g))) {
        const re = await rereadLabelNutrition();
        if (re && S.items[photoBase] === one) {
          one.kcal_per_100g = re.kcal_per_100g;
          one.protein_per_100g = re.protein_per_100g;
          one.carb_per_100g = re.carb_per_100g;
          one.fat_per_100g = re.fat_per_100g;
          delete one._suspect;
        } else if (S.items[photoBase] === one) {
          setTimeout(() => toast('这张营养成分表没读准，重拍一张更清楚的会更准', 5200), 400);
        }
      }
    }
    // 填了克数就以它为准（包装营养表通常只有一条）
    if (grams > 0 && fromPhoto.length === 1) S.items[photoBase].grams = grams;
    // 识别完就把大图收起，结果区（左小图 + 右数值）直接露出来
    $('#photoDrop').hidden = true;
    $('#photoActions').hidden = true;
    $('#pane-photo').classList.add('done');
    S.batchName = r.dish || '';
    $('#batchName').value = S.batchName;
    showResult(r.dish ? '识别：' + r.dish : '识别结果', r.note);
    // 认出来但没给克数的条目：再让 AI 按食物名估一次（不用你手动点）
    fillMissingGrams();
  } catch (e) {
    toast(e.message, 5000);
  } finally {
    btn.disabled = false;
    btn.innerHTML = old;
  }
}

/* 结果里有"没有克数"的条目：逐条用食物名问 AI 一份多少克，补上 */
async function fillMissingGrams() {
  const idxs = (S.items || []).map((it, i) => (Number(it.grams) > 0 ? -1 : i)).filter(i => i >= 0);
  if (!idxs.length) return;
  for (const i of idxs) {
    const it = S.items[i];
    const name = String(it && it.name || '').trim();
    if (!name) continue;
    try {
      const r = await api('/api/ai/text', { text: `「${name}」一份（一人份 / 一份 / 一碗，按最常见的一份）通常多少克？只估克数` });
      const g = Number(r && r.items && r.items[0] && r.items[0].grams) || 0;
      if (g > 0 && S.items[i] === it) {
        it.grams = Math.round(g);
        renderResult();
      }
    } catch (e) { /* 估不出来就留着让用户点「AI 估克数」 */ }
  }
}

/* 存一张小图（约 10~20KB），之后点开这一组还能看到当时拍的 */
/* 缩略图：只留"首页/详情那个 40 多像素的小图"够用的分辨率 —— 160×160 居中裁方形。
   用户明确「不会点开看大图，能认出是什么就行」，所以原来 320px 非方形（约 20KB）改成
   160px 方形（约 5KB），同一块空间能放 4 倍照片。送 AI 识别用的那张大图不走这里。 */
async function makeThumb(dataUrl, side = 160, q = 0.5) {
  const img = await new Promise((res, rej) => {
    const i = new Image();
    i.onload = () => res(i);
    i.onerror = rej;
    i.src = dataUrl;
  });
  const s = Math.min(img.width, img.height);          // 居中裁成正方形（首页也是按方形显示的）
  const sx = (img.width - s) / 2, sy = (img.height - s) / 2;
  const c = document.createElement('canvas');
  c.width = side; c.height = side;
  c.getContext('2d').drawImage(img, sx, sy, s, s, 0, 0, side, side);
  return c.toDataURL('image/jpeg', q);
}

/* ---- 文字 ---- */
async function runText() {
  const taEl = $('#textInput');                       // v9.07 描述板块已移除，这里防空
  const text = taEl ? taEl.value.trim() : '';
  if (!text) return toast('先描述一下吃了什么');
  const btn = $('#textGo');
  const old = btn.innerHTML;
  btn.disabled = true;
  btn.innerHTML = '<span class="spinner"></span> 估算中…';
  try {
    const r = await api('/api/ai/text', { text });
    // 累加：描述好几次的结果要叠加（第一次鸡蛋 + 第二次鸡蛋 = 两个鸡蛋）
    const prevN = (S.items || []).length;
    S.items = (S.items || []).concat(r.items.map(x => applyKnownFood({ ...x, _src: 'ai' })));
    if (!prevN) S.batchName = r.dish || '';
    $('#batchName').value = S.batchName || '';
    showResult((prevN ? '已累加：' : '估算：') + (r.dish || ''), r.note);
    // 和"搜索选中"一样的处理：算完直接切到左边的「拍照」，成分表在那边看/改，
    // 描述这边不留结果（描述页只负责输入）
    const sb = document.querySelector('#addSheet .sh-body');
    if (sb) sb.scrollTop = 0;
    setAddMode('photo');
  } catch (e) {
    toast(e.message, 5000);
  } finally {
    btn.disabled = false;
    btn.innerHTML = old;
  }
}

/* ---- 搜索 ---- */

/* 记过的食物 = 一份永久名单（Store.foodHist）：记一次就永久保存，只有用户点 × 才删。
   早期版本是"从日志里反推"，日志被删/被清就消失了，所以换成独立名单。 */
function rememberFoods(items) {
  const st = Store.load();
  if (!Array.isArray(st.foodHist)) st.foodHist = [];
  const dels = new Set(st.foodHistDel || []);
  (items || []).forEach(it => {
    const name = String(it.name || '').trim();
    const g = Number(it.grams) || 0;
    if (!name || !g) return;
    // 注意：草稿里的 *_per_100g 已经是"每 100 克"了，**不能再乘 100/g**（那会把数据放大几十倍）
    const rr = (v, digits) => +(Number(v || 0)).toFixed(digits);
    const rec = {
      n: name,
      k: Math.round(rr(it.kcal_per_100g, 0)),
      p: rr(it.protein_per_100g, 1),
      c: rr(it.carb_per_100g, 1),
      f: rr(it.fat_per_100g, 1),
      g,                                  // 上次用的克数，下次默认带出来
      cat: it.cat || '以前记过',
      at: Date.now(),
    };
    // 记住这个食物这次用的克数（下次添加/编辑都用它，不再推荐别的数字）
    st.settings = st.settings || {};
    st.settings.food_grams = Object.assign({}, st.settings.food_grams || {}, { [name]: +Number(g).toFixed(1) });
    const i = st.foodHist.findIndex(x => x.n === name);
    if (i >= 0) st.foodHist[i] = Object.assign({}, st.foodHist[i], rec);
    else st.foodHist.push(rec);
    dels.delete(name);                    // 手动记一次 = 重新加回名单
  });
  if (dels.size) st.foodHistDel = [...dels];
  Store.save();
}

/* 记住某个食物这次填的克数（下次添加同名的食物就用这个数） */
function rememberGrams(name, grams) {
  const g = Number(grams);
  if (!name || !(g > 0)) return;
  const st = Store.load();
  st.settings = st.settings || {};
  st.settings.food_grams = Object.assign({}, st.settings.food_grams || {}, { [String(name)]: +g.toFixed(1) });
  Store.save();
}

/* 记忆：你手改过的营养，按"每 100 克"记进这个食物（src:'user'，以后一律以它为准）。
   顺手记下"改过几次"和"上次 AI 给的是多少"——这两个只在后台用，不显示。
   次数多了就能看出 AI 对这类食物是偏高还是偏低（以后可以用它纠偏）。 */
function rememberNut(name, per, aiPer) {
  const n = String(name || '').trim();
  if (!n || !per) return;
  const k = Number(per.k) || 0, p = Number(per.p) || 0, c = Number(per.c) || 0, f = Number(per.f) || 0;
  if (!nutSane(k, p, c, f)) return;                 // 手填的也过一遍，别把错的记成标准
  const st = Store.load();
  if (!Array.isArray(st.foodHist)) st.foodHist = [];
  const i = st.foodHist.findIndex(x => x.n === n);
  const old = i >= 0 ? st.foodHist[i] : null;
  const rec = Object.assign({}, old, {
    n,
    k: Math.round(k), p: +p.toFixed(1), c: +c.toFixed(1), f: +f.toFixed(1),
    src: 'user',
    cnt: ((old && Number(old.cnt)) || 0) + 1,        // 改过几次
    at: Date.now(),
  });
  if (!(rec.g > 0) && old && old.g) rec.g = old.g;    // 克数记忆不归这里管，别动
  if (!rec.cat) rec.cat = '你改过';
  if (aiPer) {
    rec.ai = {
      k: Math.round(Number(aiPer.k) || 0),
      p: +(Number(aiPer.p) || 0).toFixed(1),
      c: +(Number(aiPer.c) || 0).toFixed(1),
      f: +(Number(aiPer.f) || 0).toFixed(1),
    };
  }
  if (i >= 0) st.foodHist[i] = rec; else st.foodHist.push(rec);
  st.foodHistDel = (st.foodHistDel || []).filter(x => x !== n);   // 手改过 = 重新加回名单
  Store.save();
}

function forgetFood(name) {
  const st = Store.load();
  st.foodHist = (st.foodHist || []).filter(x => x.n !== name);
  st.foodHistDel = Array.from(new Set([...(st.foodHistDel || []), name]));
  Store.save();
}

/* 记过的食物（按最近一次用的时间倒序） */
function historyFoods() {
  if (!window.__histFixed) { window.__histFixed = 1; try { sanitizeFoodHist(); } catch (e) {} }
  const st = Store.load();
  if (!Array.isArray(st.foodHist)) st.foodHist = [];
  // 一次性把老日志里的食物补进名单（补过就不再补，删掉的不会自己回来）
  if (!st.settings.histBackfilled) {
    const has = new Set(st.foodHist.map(x => x.n));
    (st.logs || []).forEach(l => {
      const g = Number(l.grams) || 0;
      const name = String(l.name || '').trim();
      if (!g || !name || has.has(name)) return;
      has.add(name);
      st.foodHist.push({
        n: name,
        k: Math.round((Number(l.kcal) || 0) * 100 / g),
        p: +(((Number(l.p) || 0) * 100) / g).toFixed(1),
        c: +(((Number(l.c) || 0) * 100) / g).toFixed(1),
        f: +(((Number(l.f) || 0) * 100) / g).toFixed(1),
        g, cat: '以前记过', at: Number(l.ts) || 0,
      });
    });
    st.settings.histBackfilled = 1;
    Store.save({ silent: true });
  }
  const dels = new Set(st.foodHistDel || []);
  return st.foodHist
    .filter(x => !dels.has(x.n))
    .sort((a, b) => (b.at || 0) - (a.at || 0))
    .map(x => ({ name: x.n, kcal: x.k, p: x.p, c: x.c, f: x.f, grams: x.g, cat: x.cat || '以前记过' }));
}

/* 有结果在下面时先把搜索列表收起来（选完直接看到记录区）；结果清空后再放出来 */
function syncSearchList() {
  const box = $('#searchList');
  if (!box) return;
  box.hidden = (S.items || []).length > 0;
}

/* 搜索页：本地历史 / 食物库 / AI 以前估过的缓存里，有没有「一字不差就是这个食物」的 */
function exactFoodHit(q) {
  const k = normName(q);
  if (!k) return false;
  if (historyFoods().some(f => normName(f.name) === k)) return true;
  if ((S.foods || []).some(f => normName(f.name) === k || (f.alias || []).some(a => normName(a) === k))) return true;
  return !!(Store.load().nutCache || []).some(x => normName(x.n) === k || normName(x.canon) === k);
}

/* AI 以前估过的那份（nutCache 里存的就是「每 100 克」四项）：
   命中就直接当一条搜索结果显示出来 —— 同一个词不重复花钱问 AI */
function nutCacheFood(q) {
  const k = normName(q);
  if (!k) return null;
  const cache = (Store.load().nutCache || []).slice().reverse();
  const one = cache.find(x => normName(x.n) === k || normName(x.canon) === k);
  if (!one) return null;
  return { name: one.canon || one.n, kcal: one.k, p: one.p, c: one.c, f: one.f, cat: '网上估值' };
}

/* 列表末尾那一行「在网上找」：点了才真的去问 AI（不做成边打字边请求，否则每敲一个字都花钱） */
function netFindRow(q) {
  const name = esc(String(q || '').trim().slice(0, 20));
  return `
    <div class="netfind" id="netFindRow">
      <div>
        <div>在网上找「${name}」</div>
        <div class="cat">本地没有 · 让 AI 按同类食物估一份（每 100 克）</div>
      </div>
      <div class="kc">找 ↗</div>
    </div>`;
}

function runSearch(q) {
  const box = $('#searchList');
  const key = q.trim().toLowerCase();
  const hist = historyFoods();

  // 放宽匹配：整词没命中就按"两个字的片段"再找一次（"威化饼干" → 威化 / 化饼 / 饼干）
  const bits = key.length > 2 ? [...new Set([key, ...Array.from({ length: key.length - 1 }, (_, i) => key.slice(i, i + 2))])] : [key];
  const hit = (s2) => bits.some(b => String(s2 || '').toLowerCase().includes(b));

  let list;
  if (!key) {
    list = hist.slice(0, 12).map(f => ({ f, h: true }));
  } else {
    const h = hist.filter(f => hit(f.name)).map(f => ({ f, h: true }));
    const db = S.foods
      .filter(f => hit(f.name) ||
        (f.alias || []).some(a => hit(a)))
      .filter(f => !h.some(x => x.f.name === f.name))
      .slice(0, 20)
      .map(f => ({ f, h: false }));
    list = h.concat(db);
    // AI 以前估过这个食物：排最前面单独一项（同一个词不重复花钱问）；本地一条都没有时它就是唯一结果
    const ai = nutCacheFood(q);
    if (ai) list.unshift({ f: ai, h: false, ai: true });
  }

  // 本地没有「一字不差就是这个食物」时，列表末尾放一行「在网上找」
  const netRow = (key && !exactFoodHit(q)) ? netFindRow(q) : '';

  if (!list.length && !netRow) {
    box.innerHTML = '';
    return;
  }

  box.innerHTML = list.map((x, i) => `
    <div class="sitem" data-i="${i}">
      <div>
        <div>${esc(x.f.name)}${x.h ? ' <span style="font-size:9px;color:var(--lime)">记过</span>' : ''}${x.ai ? ' <span class="aiTag">AI 估</span>' : ''}</div>
        <div class="cat">${esc(x.f.cat || '')} · 蛋白 ${x.f.p}g / 碳水 ${x.f.c}g / 脂肪 ${x.f.f}g</div>
      </div>
      <div class="kc">${x.f.kcal}<br><span style="font-size:9px">/100g</span></div>
      ${x.h ? `<button class="hdel" data-del="${esc(x.f.name)}" aria-label="从历史里删除">
        <svg viewBox="0 0 12 12" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><path d="M3 3l6 6M9 3l-6 6"/></svg>
      </button>` : ''}
    </div>`).join('') + netRow;

  // 「在网上找」：点了才请求（AI 估出来的值进 nutCache，下次同一个词直接出、不再花钱）
  const netBtn = $('#netFindRow', box);
  if (netBtn) netBtn.onclick = async () => {
    if (netBtn.dataset.busy) return;
    netBtn.dataset.busy = '1';
    netBtn.classList.add('busy');
    const kc = netBtn.querySelector('.kc');
    if (kc) kc.textContent = '正在找…';
    let r = null;
    try { r = await lookupNutrition(q.trim()); } catch (e) { r = { found: false, why: 'net' }; }
    delete netBtn.dataset.busy;
    if (!r || !r.found) {
      netBtn.classList.remove('busy');
      if (kc) kc.textContent = '没找成';
      toast(`「${q.trim()}」${NET_WHY[(r && r.why) || ''] || NUT_WHY[(r && r.why) || 'unknown'] || NUT_WHY.unknown}`, 4200);
      return;
    }
    runSearch($('#searchInput').value || '');
    const name = r.name || q.trim();
    toast(`AI 估：${name} 每 100 克 ${Math.round(r.per.k)} 千卡 · 点那条加进来`, 4000);
  };

  // × 只从这个历史名单里删（不影响已经记过的账），点它不会顺手把食物加进去
  $$('.hdel', box).forEach(b => b.onclick = ev => {
    ev.stopPropagation();
    const n = b.dataset.del;
    forgetFood(n);
    toast(`已从历史里删除「${n}」`, 2000);
    runSearch($('#searchInput').value || '');
  });

  $$('.sitem', box).forEach(el => el.onclick = () => {
    const one = list[Number(el.dataset.i)];
    pushFood(one.ai ? Object.assign({}, one.f, { _src: 'ai' }) : one.f);
    // 选中后：搜索这边清空回初始状态（清空搜索词、列表滚回顶部），
    // 然后把界面切到左边的「拍照」—— 记录区在那边，加进来的都列在那里
    $('#searchInput').value = '';
    $('#searchInput').blur();
    $('#searchList').hidden = false;
    runSearch('');
    const sb = document.querySelector('#addSheet .sh-body');
    if (sb) sb.scrollTop = 0;
    setAddMode('photo');
  });
}

function pushFood(f) {
  // 上次这个食物记了多少克，这次就用多少克（不再用它自带的推荐值）
  const remembered = (setting('food_grams', {}) || {})[f.name];
  const def = Number(remembered) || Number(f.grams) || 0;   // 没有记忆就空着，由用户填
  // 改过的参数优先：以 foodHist 里最后一次的值为准
  const known = (Store.load().foodHist || []).find(x => x.n === String(f.name || '').trim());
  if (known) f = Object.assign({}, f, { kcal: known.k, p: known.p, c: known.c, f: known.f });
  S.items.push({
    name: f.name,
    grams: def,
    kcal_per_100g: f.kcal,
    protein_per_100g: f.p,
    carb_per_100g: f.c,
    fat_per_100g: f.f,
    confidence: 1,
    _src: f._src || 'db',
    _units: f.units || [],
  });
  showResult('已添加', '');
}

/* ---- 结果编辑 ---- */
function showResult(title, note) {
  $('#resultArea').hidden = S.items.length === 0;
  $('#resultTitle').textContent = title || '识别结果';
  $('#resultNote').textContent = note || '';
  $('#addFoot').hidden = S.items.length === 0;
  renderResult();
  requestAnimationFrame(() => {
    const ra = $('#resultArea');
    if (!ra.hidden) ra.scrollIntoView({ block: 'start', behavior: 'smooth' });
  });
}

function renderResult() {
  syncSearchList();
  syncResultVisibility();
  const box = $('#resultItems');
  let shot = '';
  // 拍的是什么就显示什么：拍实物 →「食物照片」，拍营养成分表 →「营养成分表照片」；
  // 两样都拍了就两行都列出来，各自配各自的图
  if (S.photoData || S.photo2Data) {
    const two = !!(S.photoData && S.photo2Data);
    const shotThumb = (src, cap) => `<span class="sthumb"><img src="${src}" alt=""><i>${cap}</i></span>`;
    const thumbs = [
      S.photoData ? shotThumb(S.photoData, '食物') : '',
      S.photo2Data ? shotThumb(S.photo2Data, '营养表') : '',
    ].join('');
    const title = two ? '食物照片 + 营养成分表' : (S.photo2Data ? '营养成分表照片' : '食物照片');
    const sub = two ? `识别出 ${S.items.length} 项 · 克数可改`
                    : (S.photo2Data ? '按标签每 100 克换算' : `识别出 ${S.items.length} 项 · 克数可改`);
    shot = `<div class="shotrow">
      <div class="sthumbs">${thumbs}</div>
      <div class="sinfo">
        <b>${title}</b>
        <span>${sub}</span>
      </div>
    </div>`;
  }
  $('#shotBox').innerHTML = shot;
  // 多项才需要给这一餐起名（识别到的菜名会自动填进来）
  $('#nameWrap').hidden = S.items.length < 2;
  box.innerHTML = S.items.map((it, i) => {
    const kcal = it.kcal_per_100g * it.grams / 100;
    const units = (it._units || []).filter(u => u.g !== 100).slice(0, 3);
    const chips = units.map(u =>
      `<button data-u="${i}" data-g="${u.g}">${u.unit}</button>`).join('');
    const low = it.confidence != null && it.confidence < 0.55;
    return `
      <div class="ritem" data-low="${low ? 1 : 0}" data-row="${i}">
        <button class="del" data-rm="${i}" aria-label="删掉这一项">×</button>
        <div class="top">
          <span class="nm">${nameLine(it.name, `data-ren="${i}"`)}</span>
        </div>
        <div class="meta"><span class="mtxt">每 100g ${Math.round(it.kcal_per_100g)} 千卡 · 蛋 ${it.protein_per_100g}/碳 ${it.carb_per_100g}/脂 ${it.fat_per_100g}${low ? ' · 不太确定' : ''}</span><button class="pen" data-nut="${i}" aria-label="改营养数据">${PEN_ICON}</button></div>
        <div class="gr">
          <input type="number" inputmode="decimal" value="${it.grams || ''}" placeholder="克" data-g="${i}">
          ${it.grams ? '' : `<button class="aig" data-aig="${i}">AI 估克数</button>`}
          <span class="u">克</span>
          <div class="chips">${chips}</div>
          <span class="kc">${it.grams ? Math.round(kcal) : '—'}</span>
        </div>
      </div>`;
  }).join('');

  const total = S.items.reduce((a, b) => a + b.kcal_per_100g * (Number(b.grams) || 0) / 100, 0);
  $('#resultTotal').textContent = Math.round(total);
  $('#addFoot').hidden = S.items.length === 0;
  $('#resultArea').hidden = S.items.length === 0;

  // 删掉某一项；如果都删光了，上面那两张照片也跟着清掉
  $$('[data-rm]', box).forEach(b => b.onclick = ev => {
    ev.stopPropagation();
    S.items.splice(Number(b.dataset.rm), 1);
    if (!S.items.length) resetPhotoUI();
    renderResult();
  });
  $$('[data-ren]', box).forEach(b => b.onclick = async ev => {
    ev.stopPropagation();
    const it = S.items[Number(b.dataset.ren)];
    if (!it) return;
    const name = await askName('这个食物叫什么？', it.name || '');
    if (name === null) return;
    const v = name;
    if (!v) return;
    it.name = v;
    renderResult();
    // 还没记入，改了只影响这一项：把营养换成新食物的（克数不动）；同名再确认一次 = 重查
    renutrifyDraftItem(it);
  });
  $$('[data-nut]', box).forEach(b => b.onclick = ev => {
    ev.stopPropagation();
    openNutEdit(Number(b.dataset.nut));
  });
  $$('[data-aig]', box).forEach(b => b.onclick = async ev => {
    ev.stopPropagation();
    const it = S.items[Number(b.dataset.aig)];
    if (!it) return;
    const name = String(it.name || '').trim();
    if (!name) return toast('先填这个食物叫什么', 2400);
    b.disabled = true;
    const oldTxt = b.textContent;
    b.textContent = 'AI 估…';
    try {
      const r = await api('/api/ai/text', { text: `「${name}」一份（一人份 / 一份 / 一碗，按最常见的一份）通常多少克？只估克数` });
      const g = Number(r && r.items && r.items[0] && r.items[0].grams) || 0;
      if (!(g > 0)) throw new Error('没估出来');
      it.grams = Math.round(g);
      delete it._units;
      renderResult();
      toast(`AI 估「${name}」一份约 ${it.grams} 克，不对就直接改`, 3200);
    } catch (e) {
      b.disabled = false;
      b.textContent = oldTxt;
      toast('AI 没估出来，克数手动填一下', 3000);
    }
  });
  $$('[data-u]', box).forEach(b => b.onclick = () => {
    S.items[Number(b.dataset.u)].grams = Number(b.dataset.g);
    renderResult();
  });
  $$('input[data-g]', box).forEach(inp => {
    inp.oninput = () => {
      S.items[Number(inp.dataset.g)].grams = Number(inp.value) || 0;
      rememberGrams(S.items[Number(inp.dataset.g)].name, inp.value);
      const kc = S.items[Number(inp.dataset.g)];
      const el = inp.closest('.ritem').querySelector('.kc');
      el.textContent = Math.round(kc.kcal_per_100g * kc.grams / 100);
      const total = S.items.reduce((a, b) => a + b.kcal_per_100g * b.grams / 100, 0);
      $('#resultTotal').textContent = Math.round(total);
    };
  });
}

/* ---------------- 改某一项的营养数据 ----------------
   场景：包装上写的是「每份 12.5 克 · 60 千卡」，早先被当成「每 100 克」记了。
   这里按"参考量多少克 + 那份的营养"来填，保存时换算成每 100 克。 */
let nutEditIdx = -1;
let nutLogId = null;        // 非空 = 正在编辑"已经记过的一条"
function openNutEdit(i, fake) {
  const it = fake || S.items[i];
  if (!it) return;
  nutEditIdx = fake ? -1 : i;
  if (!fake) nutLogId = null;
  // 四个数字都预填「每 100 克」（照抄包装上那一行），参考量 = 你实际吃了多少克
  const g = Number(it.grams) || 0;
  setNutUnit('kJ', false);                        // 默认按千焦（包装上绝大多数写的是千焦）
  const k100 = Number(it.kcal_per_100g) || 0;
  $('#nutRef').value = g ? +g.toFixed(1) : '';     // 没填过克数就留空，不默认 100
  $('#nutKcal').value = k100 ? (nutUnit === 'kJ' ? Math.round(k100 * KJ_PER_KCAL) : Math.round(k100)) : '';
  $('#nutP').value = k100 ? +((Number(it.protein_per_100g) || 0).toFixed(1)) : '';
  $('#nutC').value = k100 ? +((Number(it.carb_per_100g) || 0).toFixed(1)) : '';
  $('#nutF').value = k100 ? +((Number(it.fat_per_100g) || 0).toFixed(1)) : '';
  nutNameTyped = false;
  const nq0 = $('#nutNameQ'); if (nq0) nq0.value = it.name || '';
  const sug0 = $('#nutSug'); if (sug0) { sug0.hidden = true; sug0.innerHTML = ''; }
  let base = {
    k: Number(it.kcal_per_100g) || 0, p: Number(it.protein_per_100g) || 0,
    c: Number(it.carb_per_100g) || 0, f: Number(it.fat_per_100g) || 0,
  };
  // 已经记坏的数据（三大项加起来比 100g 还多）：别拿它当基准，改用历史/食物库里的正确值
  let fixedFrom = '';
  if (!nutSane(base.k, base.p, base.c, base.f)) {
    const known = nutKnownFood(it.name);
    if (known && nutSane(known.kcal, known.p, known.c, known.f)) {
      base = { k: Number(known.kcal) || 0, p: Number(known.p) || 0, c: Number(known.c) || 0, f: Number(known.f) || 0 };
      fixedFrom = known.from;
    }
  }
  nutBase = base;
  nutDirty = { k: false, p: false, c: false, f: false };
  if (fixedFrom) {
    $('#nutKcal').value = nutUnit === 'kJ' ? Math.round(base.k * KJ_PER_KCAL) : Math.round(base.k);
    $('#nutP').value = +(base.p).toFixed(1);
    $('#nutC').value = +(base.c).toFixed(1);
    $('#nutF').value = +(base.f).toFixed(1);
    setTimeout(() => toast(`这条原来的营养数据对不上（三大项超过 100 克），已按${fixedFrom}里的正确值改好，保存前请核对`, 4200), 350);
  }
  paintNutPreview();
  // 位置：弹在记录卡片的垂直正中间（等它显示出来量到真实高度后再定位，误差 0）
  const sh = $('#nutSheet');
  sh.style.top = '';
  sh.style.bottom = '';
  // 遮罩和面板一起往上抬两级：遮罩在面板下一层，但要在"别的卡片的遮罩"之上，
  // 否则点外面时第一下命中别人的遮罩（先暗一次）、第二下才关这个面板
  const nm = $('#nutMask');
  if (nm) nm.style.zIndex = String(++sheetZ);
  sh.style.zIndex = String(++sheetZ);
  // 同样：先落位（关过渡）→ 再显示，避免"先出现在底部再跳到中间"
  sh.classList.add('noanim');
  {
    // 量两次：第一次排好版，第二次拿到"预览行换行之后"的真实高度
    // 用 offsetHeight（不受 transform: scale 影响），否则会算小、卡片往下溢出屏幕
    const place = () => {
      const bigEl = $('#addSheet');
      const bigOpen = bigEl && bigEl.classList.contains('on');
      // 从记录卡片里打开 → 对齐那张卡片；从"今天吃了什么"直接打开（卡片没开）→ 对齐屏幕
      const centerY = bigOpen
        ? bigEl.getBoundingClientRect().top + bigEl.getBoundingClientRect().height / 2
        : window.innerHeight / 2;
      const h = sh.offsetHeight || 0;
      const top = Math.max(8, Math.min(centerY - h / 2, window.innerHeight - h - 8));
      sh.style.top = Math.round(top) + 'px';
      sh.style.bottom = 'auto';
    };
    place();
    paintNutPreview();
    void sh.offsetHeight;
    place();
  }
  sh.classList.remove('noanim');
  $('#nutMask').classList.add('on');
  sh.classList.add('on');
  setTimeout(() => $('#nutRef').focus(), 260);
}
/* 从"今天吃了什么"或某一组明细里点那个「…」：改一条已记录的账 */
function openNutEditLog(id) {
  const l = (Store.load().logs || []).find(x => x.id === Number(id));
  if (!l) return;
  const g = Number(l.grams) || 0;
  const k = g ? (Number(l.kcal) || 0) * 100 / g : 0;
  nutLogId = l.id;
  openNutEdit(-1, {
    name: l.name,
    grams: g,
    kcal_per_100g: k,
    protein_per_100g: g ? (Number(l.p) || 0) * 100 / g : 0,
    carb_per_100g: g ? (Number(l.c) || 0) * 100 / g : 0,
    fat_per_100g: g ? (Number(l.f) || 0) * 100 / g : 0,
  });
}

function closeNutEdit() {
  $('#nutMask').classList.remove('on');
  const sh = $('#nutSheet');
  // 和 closeAdd 一样：下滑关闭时脚本写过 transform / opacity，这里必须当场清掉，
  // 否则下次打开会停在半路 —— 这就是"营养卡片下滑卡住"的真正原因
  sh.classList.remove('dragging');
  sh.style.transform = '';
  sh.style.opacity = '';
  sh.classList.remove('on');
  setTimeout(() => { sh.style.top = ''; sh.style.bottom = ''; }, 420);
  nutEditIdx = -1;
}
let nutUnit = 'kcal';
let nutBase = { k: 0, p: 0, c: 0, f: 0 };   // 上面那格记住"每 100 克"的原始值
let nutNameTyped = false;                    // 名字是"自己打的"还是"点了候选带出来的"（只有自己打的才算改名）
let nutDirty = { k: false, p: false, c: false, f: false };   // 用户手改过的格子，改克数时不被覆盖
const KJ_PER_KCAL = 4.184;
function setNutUnit(u, convert) {
  const inp = $('#nutKcal');
  const v = Number(inp.value) || 0;
  if (convert && v > 0) {
    inp.value = u === 'kJ' ? Math.round(v * KJ_PER_KCAL) : Math.round(v / KJ_PER_KCAL);
  }
  nutUnit = u;
  // 切换单位时把已经显示的数值按新单位写回基准（基准永远是「每 100 克」）
  if (convert) {
    const kEl2 = $('#nutKcal');
    const shown = Number(kEl2 && kEl2.value) || 0;
    if (shown > 0) nutBase = Object.assign({}, nutBase, { k: u === 'kJ' ? shown / KJ_PER_KCAL : shown });
  }
  const seg = $('#nutUnitTog');
  if (seg) seg.querySelectorAll('span').forEach(sp => sp.classList.toggle('on', sp.dataset.u === (u === 'kJ' ? 'kj' : 'kcal')));
  if (inp) inp.placeholder = u === 'kJ' ? '8904' : '2128';
}

/* 边填边算：让用户当场看到「这一份 = 每 100 克多少」 */
/* 这组"每 100 克"数据哪里讲不通：返回一句具体的说明，讲得通就返回 ''。
   以前只说"对不上"，用户不知道是三大项超了还是热量差了，所以拆开说。 */
function nutWhy(kcal, p, c, f) {
  const mass = (Number(p) || 0) + (Number(c) || 0) + (Number(f) || 0);
  if (mass > 105) return `蛋白+碳水+脂肪 加起来 ${mass.toFixed(1)} 克，比 100 克还多 —— 这三格填的是每 100 克的数，请照包装核对`;
  const k = Number(kcal) || 0;
  if (k <= 0) return '';                              // 没热量就不判
  const calc = 4 * (Number(p) || 0) + 4 * (Number(c) || 0) + 9 * (Number(f) || 0);
  const diff = Math.abs(calc - k);
  if (diff <= Math.max(70, k * 0.4)) return '';       // 允许 40% 误差（膳食纤维/糖醇等）
  return `热量 ${Math.round(k)} 千卡，和 蛋白/碳水/脂肪 算出来的 ${Math.round(calc)} 千卡差 ${Math.round(diff)} 千卡 —— 四格都要填「每 100 克」，请照包装核对`;
}
/* 这组"每 100 克"数据是否讲得通（内部用） */
function nutSane(kcal, p, c, f) {
  return !nutWhy(kcal, p, c, f);
}

/* 营养表那一行被读串了（例子：碳水读成 77.7、脂肪读成 59.4）→ 用你拍的**营养表那张照片**重读一次。
   只在"数字明显不成立"时才多花这一次调用；重读还是不对就返回 null，由调用方决定怎么提示。
   这一条是用户明确提出来的：「你自己读出来的数，你自己得认」。 */
async function rereadLabelNutrition() {
  const labelImg = S.photo2Data || S.photoData;
  if (!labelImg) return null;
  let r = null;
  try {
    r = await api('/api/ai/food', {
      image: labelImg,
      hint: '这张图只是包装上的营养成分表，不要按外观估算。请**整张表逐行照抄到 label_rows**（每行 name / value / unit / nrv），'
        + '再按标签填 label 与四个 *_per_100g。注意事项：①「脂肪」和「碳水化合物」两行绝对不许互换；'
        + '②数字位数必须和标签完全一致（标签写 7.7 就不能写成 77.7，也不能多打一位）；'
        + '③每行只取一个数，不许把 NRV% 那一列、或别行的数字混进来；④能量照标签原样（千焦就给千焦数）。'
        + 'items 只返回一条，grams 填 100。',
    });
  } catch (e) { return null; }
  const it = r && r.items && r.items[0];
  if (!it) return null;
  if (it._suspect) return null;                       // 重读自己都判不过（NRV% 对不上）→ 当作没读成
  if (!nutSane(it.kcal_per_100g, it.protein_per_100g, it.carb_per_100g, it.fat_per_100g)) return null;
  return it;
}

/* 死规则：某个食物的营养参数一旦被改过，以后一律以"最后一次改的"为准。
   这里把一条待记录的食物按 foodHist 里的值覆盖（有记录才覆盖）。 */
function applyKnownFood(it) {
  if (!it) return it;
  const known = (Store.load().foodHist || []).find(x => x.n === String(it.name || '').trim());
  if (!known) return it;
  it.kcal_per_100g = Number(known.k);
  it.protein_per_100g = Number(known.p);
  it.carb_per_100g = Number(known.c);
  it.fat_per_100g = Number(known.f);
  it._fromHist = true;
  return it;
}

/* 找这个食物在"历史/食物库"里的可信数据（用来纠正已经记坏的那条） */
function nutKnownFood(name) {
  const key = String(name || '').trim();
  if (!key) return null;
  const all = []
    .concat(historyFoods().map(f => ({ ...f, from: '历史' })))
    .concat((S.foods || []).map(f => ({ name: f.name, kcal: f.kcal, p: f.p, c: f.c, f: f.f, from: '食物库' })));
  return all.find(x => x.name === key) || null;
}

/* ---------------- 改名 → 营养跟着换（v7.60） ----------------
   用户定的规则：
   - 只换"每 100 克"那四项；**克数一个字都不动**
   - 四项要么全换、要么全不换（查不到/数据不合理 → 原样留着，只提示原因）
   - 组名（batchName）只是标签，不触发
   - 改成同一个名字 = 再查一次（这就是重试入口）；但你手改过的那条不许被覆盖 */
const NUT_WHY = {
  'no-key': '没填 API Key，营养没动（设置 → 我的 → AI）',
  'no-net': '没网或请求失败，营养没动',
  'net': '没网或请求失败，营养没动',
  'ai-miss': 'AI 没认出这个食物，营养没动',
  'bad-data': 'AI 给的数对不上，没敢用，营养没动',
  'empty': '没有名字，营养没动',
  'unknown': '营养没查成，还是原来的数',
};

/* 搜索页「在网上找」失败时的说法：同一个原因，搜索这边不是"营养没动"，而是"没估出来" */
const NET_WHY = {
  'no-key': '没填 API Key，没法网上估（设置 → 我的 → AI）',
  'no-net': '没网或请求失败，估不了',
  'net': '没网或请求失败，估不了',
  'ai-miss': 'AI 没认出这个食物，换个说法或用「描述」',
  'bad-data': 'AI 给的数对不上，没敢用',
};

/* 已记录的一条（或几条）：查新名字的每 100 克，乘它自己的克数写回去 */
async function renutrifyLogs(ids, name, sameName, startMsg) {
  if (!ids || !ids.length) return null;
  if (startMsg) toast(startMsg, 2000);
  let r = null;
  try { r = await api('/api/logs/renutrify', { ids, name, sameName: !!sameName }); }
  catch (e) { r = { found: false, why: 'net' }; }
  await loadDay();
  if (S.view === 'trends') { try { loadTrends(); } catch (e) {} }
  if (!r || !r.found) {
    toast(`「${name}」${NUT_WHY[(r && r.why) || 'unknown'] || NUT_WHY.unknown}`, 4800);
    return r;
  }
  if (!(r.touched || []).length) {
    toast(r.skippedManual
      ? `「${name}」这条是你手改过的，没覆盖`
      : `「${name}」没有克数，营养没法换算，原样留着`, 4200);
    return r;
  }
  const t = r.touched[0];
  const shortMsg = `已按「${r.canon || name}」更新：${Math.round(r.per.k)} 千卡/100g`;
  toast(`${shortMsg} · 这条 ${t.grams} 克 = ${Math.round(t.kcal)} 千卡`, 3400, shortMsg);
  return r;
}

/* 还没记入的草稿行：只改这一项的"每 100 克"，克数不动 */
async function renutrifyDraftItem(it) {
  const name = String((it && it.name) || '').trim();
  if (!name) return;
  toast(`「${name}」正在查营养…`, 1600);
  let r = null;
  try { r = await api('/api/food/nutrition', { name }); }
  catch (e) { r = { found: false, why: 'net' }; }
  if (!r || !r.found) {
    toast(`「${name}」${NUT_WHY[(r && r.why) || 'unknown'] || NUT_WHY.unknown}`, 4800);
    return;
  }
  it.kcal_per_100g = r.per.k;
  it.protein_per_100g = r.per.p;
  it.carb_per_100g = r.per.c;
  it.fat_per_100g = r.per.f;
  it.nutSrc = r.src === 'ai' ? 'ai' : r.src === 'db' ? 'db' : 'user';
  renderResult();
  toast(`已按「${r.canon || name}」更新：${Math.round(r.per.k)} 千卡/100g`, 3000);
}

/* 历史里如果有被算坏的数据（三大项合计 > 100 克）：
   不删掉（删了这个食物就从搜索里消失了），而是尽量修回来：
   ① 用同名的记账反推 → ② 把当初多乘的 100/克数 除掉 → ③ 用食物库的数据 */
function repairHistEntry(f) {
  if (nutSane(f.k, f.p, f.c, f.f)) return f;
  const logs = (Store.load().logs || []).filter(l => l.name === f.n && Number(l.grams) > 0);
  for (const l of logs) {
    const sc = 100 / Number(l.grams);
    const cand = { k: Number(l.kcal) * sc, p: Number(l.p) * sc, c: Number(l.c) * sc, f: Number(l.f) * sc };
    if (nutSane(cand.k, cand.p, cand.c, cand.f)) {
      return Object.assign({}, f, { k: Math.round(cand.k), p: +cand.p.toFixed(1), c: +cand.c.toFixed(1), f: +cand.f.toFixed(1) });
    }
  }
  const g = Number(f.g) || 0;
  if (g > 0) {
    const sc = g / 100;                       // 当初是乘了 100/g，这里除回来
    const cand = { k: f.k * sc, p: f.p * sc, c: f.c * sc, f: f.f * sc };
    if (nutSane(cand.k, cand.p, cand.c, cand.f)) {
      return Object.assign({}, f, { k: Math.round(cand.k), p: +cand.p.toFixed(1), c: +cand.c.toFixed(1), f: +cand.f.toFixed(1) });
    }
  }
  const db = (S.foods || []).find(x => x.name === f.n);
  if (db && nutSane(db.kcal, db.p, db.c, db.f)) {
    return Object.assign({}, f, { k: Math.round(db.kcal), p: +Number(db.p).toFixed(1), c: +Number(db.c).toFixed(1), f: +Number(db.f).toFixed(1) });
  }
  return f;                                   // 实在救不了，原样留着（至少还能找到这个食物）
}

/* 历史里少了、但确实记过的食物（比如被旧版本误删）：从记账里补回来 */
function refillHistFromLogs() {
  const st = Store.load();
  if (!Array.isArray(st.foodHist)) st.foodHist = [];
  const has = new Set(st.foodHist.map(f => f.n));
  const dels = new Set(st.foodHistDel || []);
  let added = 0;
  (st.logs || []).forEach(l => {
    const name = String(l.name || '').trim();
    const g = Number(l.grams) || 0;
    if (!name || !g || has.has(name) || dels.has(name)) return;
    const sc = 100 / g;
    let cand = { k: Math.round((Number(l.kcal) || 0) * sc), p: +((Number(l.p) || 0) * sc).toFixed(1),
                 c: +((Number(l.c) || 0) * sc).toFixed(1), f: +((Number(l.f) || 0) * sc).toFixed(1) };
    // 那条账本身记得不准（三大项超过 100 克）：按比例压到 100 克以内再用，
    // 这样这个食物至少还在列表里，用户可以点「…」按包装改一次
    const mass = cand.p + cand.c + cand.f;
    if (mass > 100) {
      const k2 = 100 / mass;
      cand = { k: cand.k, p: +(cand.p * k2).toFixed(1), c: +(cand.c * k2).toFixed(1), f: +(cand.f * k2).toFixed(1) };
    }
    // 不再因"数据看着不对"跳过：食物消失比数字不准严重
    has.add(name);
    st.foodHist.push({ n: name, k: cand.k, p: cand.p, c: cand.c, f: cand.f, g, cat: '以前记过', at: Number(l.ts) || 0 });
    added++;
  });
  if (added) Store.save({ silent: true });
}

function sanitizeFoodHist() {
  refillHistFromLogs();
  const st = Store.load();
  if (!Array.isArray(st.foodHist) || !st.foodHist.length) return;
  let changed = false;
  st.foodHist = st.foodHist.map(f => {
    const fixed = repairHistEntry(f);
    if (fixed !== f) changed = true;
    return fixed;
  });
  if (changed) Store.save({ silent: true });
}

/* 面板里按食物名找库/历史，找到就把「每 100 克」的营养填进来（用户只知道克数、不知道千焦时用） */
function nutFindFoods(q) {
  const key = String(q || '').trim();
  if (!key) return [];
  const norm = (x) => String(x || '').toLowerCase();
  const k = norm(key);
  const hist = historyFoods().filter(f => norm(f.name).includes(k))
    .map(f => ({ name: f.name, kcal: f.kcal, p: f.p, c: f.c, f: f.f, from: '历史' }));
  const fromDb = (S.foods || []).filter(f => norm(f.name).includes(k) ||
      (f.alias || []).some(a => norm(a).includes(k)))
    .map(f => ({ name: f.name, kcal: f.kcal, p: f.p, c: f.c, f: f.f, from: '食物库' }));
  const seen = new Set();
  return hist.concat(fromDb).filter(f => (seen.has(f.name) ? false : (seen.add(f.name), true))).slice(0, 6);
}

function applyNutFood(f) {
  const k = Number(f.kcal) || 0;
  $('#nutKcal').value = Math.round(nutUnit === 'kJ' ? k * KJ_PER_KCAL : k);
  $('#nutP').value = +((Number(f.p) || 0).toFixed(1));
  $('#nutC').value = +((Number(f.c) || 0).toFixed(1));
  $('#nutF').value = +((Number(f.f) || 0).toFixed(1));
  // 换了个食物 → 新的每 100 克就是"基准"。不更新 nutBase 的话，
  // 之后一改参考量/克数，四个格子会按**旧食物**的值重算，看着像"刚填好又变回去了"
  nutBase = { k, p: Number(f.p) || 0, c: Number(f.c) || 0, f: Number(f.f) || 0 };
  nutDirty = { k: false, p: false, c: false, f: false };
  const sug = $('#nutSug');
  if (sug) { sug.hidden = true; sug.innerHTML = ''; }
  const q = $('#nutNameQ');
  if (q) q.value = f.name;
  paintNutPreview();
}

function paintNutPreview() {
  const box = $('#nutPreview');
  if (!box) return;                       // 这行已经删掉，函数留着不影响
  const ref = Number($('#nutRef').value) || 0;
  const raw = $('#nutKcal').value.trim();
  const kcal = raw === '' ? NaN : Number(raw);
  if (!(ref > 0) || !isFinite(kcal)) { box.textContent = '填了克数和热量，这里会显示换算结果'; return; }
  const per100kcal = nutUnit === 'kJ' ? kcal / KJ_PER_KCAL : kcal;
  const portion = per100kcal * ref / 100;
  const unit = nutUnit === 'kJ' ? '千焦' : '千卡';
  box.innerHTML = `包装每 100 克 = <b>${Math.round(kcal)} ${unit}</b>　→　你吃的 ${+ref.toFixed(1)} 克 = <b>${Math.round(portion)} 千卡</b>`;
}

/* 营养面板里：本地库/历史一条都没命中时，后台自动问一次 AI 并把四个格子填好。
   零按钮：你只管输名字，数字自己出来；失败就说一句原因。
   只在你还没手动填过数字时才会自动填（nutDirty 全 false），不会覆盖你正在输的值。 */
async function nutAutoFill(q) {
  const name = String(q || '').trim();
  if (!name) return;
  let r = null;
  try { r = await api('/api/food/nutrition', { name }); }
  catch (e) { r = { found: false, why: 'net' }; }
  if (!r || !r.found) {
    toast(`「${name}」${NUT_WHY[(r && r.why) || 'unknown'] || NUT_WHY.unknown}`, 4200);
    return;
  }
  // 这期间你又改了名字或数字 → 不填了
  const box = $('#nutNameQ');
  if (!box || box.value.trim() !== name) return;
  if (nutDirty.k || nutDirty.p || nutDirty.c || nutDirty.f) return;
  applyNutFood({ name: r.canon || name, kcal: r.per.k, p: r.per.p, c: r.per.c, f: r.per.f });
  toast(`已按「${r.canon || name}」填好：${Math.round(r.per.k)} 千卡/100g（保存前请核对）`, 3600);
}

async function saveNutEdit() {
  // 两种目标：草稿里的一项（S.items）或已经记过的一条（nutLogId）
  const logTarget = nutLogId ? (Store.load().logs || []).find(x => x.id === nutLogId) : null;
  const it = logTarget ? { name: logTarget.name } : S.items[nutEditIdx];
  if (!it) return closeNutEdit();
  const ref = Number($('#nutRef').value);
  if (!(ref > 0)) return toast('先填你吃了多少克', 2600);

  // 面板顶部那一格名字：改了就等于"把这一条改成另一个食物"——
  // 名字要改、营养也要跟着换成新食物的（不然就是"巧克力 + 西瓜的营养"）
  const nameBox = String(($('#nutNameQ') && $('#nutNameQ').value) || '').trim().slice(0, 20);
  const newName = nameBox || it.name;
  const renamed = !!nameBox && nameBox !== it.name && nutNameTyped;
  const dirtyAny = nutDirty.k || nutDirty.p || nutDirty.c || nutDirty.f;
  let keepNote = '';
  if (renamed) {
    if (!dirtyAny) {
      // 你没手动改数字 → 以新名字的营养为准（本地库/记忆/AI 缓存都不花钱）
      let r = null;
      try { r = await api('/api/food/nutrition', { name: newName }); } catch (e) { r = { found: false, why: 'net' }; }
      if (r && r.found) {
        $('#nutKcal').value = Math.round(nutUnit === 'kJ' ? r.per.k * KJ_PER_KCAL : r.per.k);
        $('#nutP').value = +(r.per.p).toFixed(1);
        $('#nutC').value = +(r.per.c).toFixed(1);
        $('#nutF').value = +(r.per.f).toFixed(1);
      } else {
        keepNote = `（「${newName}」的营养没查到，数字还是原来那个；要手动改就改完再保存）`;
      }
    }
  }

  // 注意：kcalRaw 必须在"改名换营养"之后才读，否则读到的是上一个食物的热量
  const kcalRaw = $('#nutKcal').value.trim();
  if (kcalRaw === '' || !(Number(kcalRaw) >= 0)) return toast('热量必须填（千卡）', 2600);
  it.grams = +ref.toFixed(1);                     // 参考量就是"这一份吃多少克"，写回克数
  rememberGrams(newName, ref);                     // 记住这个食物的克数，下次直接用
  const num = (sel) => { const v = $(sel).value.trim(); return v === '' ? 0 : Number(v) || 0; };
  let kc100 = nutUnit === 'kJ' ? (Number(kcalRaw) / KJ_PER_KCAL) : Number(kcalRaw);   // 千焦先换成千卡（四个数都是"每 100 克"）
  let p100 = num('#nutP'), c100 = num('#nutC'), f100 = num('#nutF');
  let why = nutWhy(kc100, p100, c100, f100);
  // 数字是 App 自己读出来的、却不合格 → 它得自己负责：用手上那张营养表照片重读一次，把格子改对再存
  if (why && (S.photo2Data || S.photoData) && !(nutDirty.k || nutDirty.p || nutDirty.c || nutDirty.f)) {
    const re = await rereadLabelNutrition();
    if (re) {
      kc100 = re.kcal_per_100g; p100 = re.protein_per_100g; c100 = re.carb_per_100g; f100 = re.fat_per_100g;
      const put = (sel, v) => { const el = $(sel); if (el) el.value = v; };
      put('#nutKcal', nutUnit === 'kJ' ? Math.round(kc100 * KJ_PER_KCAL) : Math.round(kc100));
      put('#nutP', +p100.toFixed(1));
      put('#nutC', +c100.toFixed(1));
      put('#nutF', +f100.toFixed(1));
      why = nutWhy(kc100, p100, c100, f100);
      if (!why) toast(`刚才那行数字读串了，已按照片重读改正：每 100 克 ${Math.round(kc100)} 千卡 · 蛋 ${p100} / 碳 ${c100} / 脂 ${f100}`, 5200);
    }
    if (why) why += '（已按你的营养表照片自动重读过一次，还是对不上 —— 多半是照片没拍清）';
  }
  if (why) { toast(why, 5200); return; }
  it.kcal_per_100g = +kc100.toFixed(1);
  it.protein_per_100g = +p100.toFixed(1);
  it.carb_per_100g = +c100.toFixed(1);
  it.fat_per_100g = +f100.toFixed(1);
  const share = ref / 100;                        // 每 100 克 → 这一份（记录里存的是实际吃掉的）
  const idx = nutEditIdx;
  // 改的是"已经记过的一条"：直接改那条记录，然后重算当天
  if (nutLogId) {
    const d = Store.load();
    const l = (d.logs || []).find(x => x.id === nutLogId);
    if (l) {
      const prevG = Number(l.grams) || 0;
      // 这一条原来是 AI 给的才算"AI 说多少"（用来记偏差）
      const prevAi = (l.nutSrc === 'ai' && prevG > 0) ? {
        k: (Number(l.kcal) || 0) * 100 / prevG,
        p: (Number(l.p) || 0) * 100 / prevG,
        c: (Number(l.c) || 0) * 100 / prevG,
        f: (Number(l.f) || 0) * 100 / prevG,
      } : null;
      l.grams = +ref.toFixed(1);
      rememberGrams(newName, ref);
      l.kcal = Math.round(kc100 * share * 10) / 10;      // 记录里存的是"这一份"实际吃掉的
      l.p = +(p100 * share).toFixed(1);
      l.c = +(c100 * share).toFixed(1);
      l.f = +(f100 * share).toFixed(1);
      l.nutSrc = 'user';                 // 手改过的：以后同名重试、AI 都不许覆盖
      if (renamed) l.name = newName;     // 面板里改了名字 = 这一条改成另一个食物（整组的标签不动）
      Store.save();
      // 记进"这个食物"的记忆（每 100 克）——次数越多越可信，下次同名直接用
      rememberNut(newName, {
        k: it.kcal_per_100g, p: it.protein_per_100g, c: it.carb_per_100g, f: it.fat_per_100g,
      }, prevAi);
    }
    const wasGroup = S.detailIsGroup, ids = (S.detailIds || []).slice(), tname = S.detailName;
    closeNutEdit();
    closeGroup();
    toast(`已更新：${newName} ${l ? l.grams : ref} 克 · ${Math.round(kc100 * share)} 千卡${keepNote}`, keepNote ? 5200 : 2600);
    loadDay().then(() => {
      if (wasGroup || ids.length) {
        const fresh = (Store.load().logs || []).filter(x => ids.includes(x.id));
        if (fresh.length) openDetail(fresh, wasGroup, tname);
      }
    });
    return;
  }
  if (renamed) it.name = newName;                 // 草稿：面板里改的名字就是这一行的新名字
  closeNutEdit();
  renderResult();                                 // 热量、合计当场重算
  // 双保险：外面那一项的克数框 / 每 100 克那行 / 热量，全部直接写成新值
  // （哪怕重绘时序出问题，用户也能立刻看到变化）
  const row = document.querySelector(`#resultItems .ritem[data-row="${idx}"]`)
           || document.querySelectorAll('#resultItems .ritem')[idx];
  if (row) {
    const gi = row.querySelector('input[data-g]');
    if (gi) gi.value = it.grams;
    const mt = row.querySelector('.meta .mtxt');
    if (mt) mt.textContent = `每 100g ${Math.round(it.kcal_per_100g)} 千卡 · 蛋 ${it.protein_per_100g}/碳 ${it.carb_per_100g}/脂 ${it.fat_per_100g}`;
    const kc = row.querySelector('.kc');
    if (kc) kc.textContent = Math.round(it.kcal_per_100g * it.grams / 100);
  }
  const tot = document.querySelector('#resultTotal');
  if (tot) tot.textContent = Math.round(S.items.reduce((a, b) => a + b.kcal_per_100g * b.grams / 100, 0));
  toast(`已更新：这一份 ${it.grams} 克 · ${Math.round(it.kcal_per_100g * it.grams / 100)} 千卡`, 2600);
}

async function saveItems() {
  const items = S.items.filter(i => Number(i.grams) > 0);
  if (!items.length) {
    const inp = document.querySelector('#resultItems input[data-g]');
    if (inp) inp.focus();
    return toast('先填克数（每项吃了多少克）再记入', 3000);
  }
  if (items.length < S.items.length) {
    const inp = document.querySelector(`#resultItems input[data-g="${S.items.findIndex(i => !(Number(i.grams) > 0))}"]`);
    if (inp) inp.focus();
    return toast('还有一项没填克数，先填上再记入', 3000);
  }
  const dishName = ($('#batchName').value || '').trim().slice(0, 20);
  if (items.length > 1 && !dishName) {
    $('#batchName').focus();
    return toast('先给这一餐起个名字，比如「沙县小吃」', 3000);
  }
  const btn = $('#saveItems');
  btn.disabled = true;
  btn.textContent = '保存中…';
  try {
    const batch = 'b' + Date.now();
    let shot = '';
    const thumbSrc = S.photoData || S.photo2Data;
    if (batch && thumbSrc) {
      try { shot = await makeThumb(thumbSrc); } catch (e) { /* 图存不下就算了 */ }
    }
    await api('/api/logs', {
      date: S.date,
      meal: S.meal,
      items,
      source: items[0]._src || 'manual',
      // 一次识别出来的多项合成一组，列表里只占一行
      batch,
      batchName: items.length > 1 ? dishName : '',
      shot,
    });
    rememberFoods(items);                 // 记过的食物永久留档（搜索里能找到，× 才删）
    closeAdd();
    S.batchName = null;
    clearDraft();
    toast(`已记入${MEAL_NAME[S.meal]} · ${Math.round(items.reduce((a, b) => a + b.kcal_per_100g * b.grams / 100, 0))} 千卡`);
    await loadDay();
    if (S.view === 'trends') loadTrends();
  } catch (e) {
    toast(e.message, 4000);
  } finally {
    btn.disabled = false;
    btn.textContent = '记入';
  }
}


/* ---------------- 一组记录的详情卡片 ---------------- */
function openGroup(key) {
  const g = groupMap.get(key);
  if (!g) return;
  openDetail(g.logs, true, g.name || '未命名');
}

/* logs：这一组（或这一条）记录；isGroup：多条才显示「N 项」和小计 */
function openDetail(logs, isGroup, title) {
  if (!logs || !logs.length) return;
  const sum = k => Math.round(logs.reduce((a, b) => a + (b[k] || 0), 0));
  const kcal = Math.round(logs.reduce((a, b) => a + (b.kcal || 0), 0));
  const batchKey = logs[0].batch || '';
  let shot = (S.day && S.day.shots && S.day.shots[batchKey]) || shotUrl(batchKey) || '';
  $('#grpNameTxt').textContent = title || logs[0].name;
  $('#grpMeta').textContent = isGroup
    ? `${logs.length} 项 · 蛋${sum('p')} / 碳${sum('c')} / 脂${sum('f')}`
    : `${Math.round(logs[0].grams)}g`;
  const tip = $('#grpNoShot');
  const applyShot = (u) => {
    const el = $('#grpShot'); if (!el) return;
    if (u) { el.src = u; el.hidden = false; if (tip) tip.hidden = true; return; }
    el.removeAttribute('src'); el.hidden = true;
    // 拍照记的却没有图 → 说清楚（早期版本只存数据 / 或云端裁掉过）
    if (tip) tip.hidden = !logs.some(l => l.source === 'photo');
  };
  applyShot(shot);
  // 本机没有这张（换过设备 / 被裁过）→ 从云端那个单独的图片文件拉回来，拉到就当场补上
  if (!shot && batchKey) {
    ensurePhoto(batchKey).then(u => {
      if (!u) return;
      shot = u;
      applyShot(u);
    }).catch(() => {});
  }
  $('#grpItems').innerHTML = logs.map(l => `
    <div class="gitem">
      <div class="n">${esc(l.name)}<span class="sub">${g1(l.grams)}g · 蛋${g1(l.p)}·碳${g1(l.c)}·脂${g1(l.f)}<button class="pen inl" data-nutlog="${l.id}" aria-label="改营养数据">${PEN_ICON}</button></span></div>
      <div class="k">${Math.round(l.kcal)}</div>
      <button class="del" data-gdel="${l.id}">×</button>
    </div>`).join('');
  $('#grpTotal').textContent = kcal;
  S.detailIds = logs.map(l => l.id);
  S.detailIsGroup = !!isGroup;
  S.detailName = title || logs[0].name;
  $$('[data-nutlog]', $('#grpItems')).forEach(b => b.onclick = ev => {
    ev.stopPropagation();
    openNutEditLog(b.dataset.nutlog);
  });
  $$('[data-gdel]', $('#grpItems')).forEach(b => b.onclick = async ev => {
    ev.stopPropagation();
    try {
      await api('/api/logs/' + b.dataset.gdel, null, 'DELETE');
      closeGroup();
      await loadDay();
    } catch (e) { toast(e.message); }
  });
  $('#grpMask').classList.add('on');
  $('#grpSheet').classList.add('on');
}
function closeGroup() {
  $('#grpMask').classList.remove('on');
  $('#grpSheet').classList.remove('on');
}

/* ---------------- 系统自带的弹框 + 我们自己的磨砂背景 ----------------
   输入框/确认框/提示框都保持 iOS 原生样式（不另画卡片）；只是在弹出来之前，
   先把页面糊一层（和详情卡 / 营养卡后面同一套：#rnMask 20% 黑 + blur 5，并且让开顶栏），
   框关掉后立刻收掉。必须等两帧再调原生方法，否则系统框先出来、背景还是原样。 */
function frostedSystemCall(fn) {
  const mask = $('#rnMask');
  if (!mask) return Promise.resolve(fn());
  return new Promise(resolve => {
    mask.style.transition = 'none';          // 系统框是瞬间出来的，遮罩也要瞬间到位
    mask.classList.add('on');
    requestAnimationFrame(() => requestAnimationFrame(() => {
      let r;
      try { r = fn(); } catch (e) { r = undefined; }
      mask.classList.remove('on');
      setTimeout(() => { mask.style.transition = ''; }, 300);
      resolve(r);
    }));
  });
}
/* 改名：App 自己的小输入卡（居中、两个按钮），背景和「营养编辑」用的是同一层遮罩。
   不再用系统 prompt：iOS 会给自己那层压暗，盖住顶栏、盖不住状态栏，背景永远对不上基准。
   取消返回 null。 */
let rnRes = null;
function askName(title, value) {
  const card = $('#rnSheet'), mask = $('#rnMask'), inp = $('#rnInput');
  if (!card || !mask || !inp) return Promise.resolve(prompt(title || '改名字', value || ''));
  if (rnRes) { const r = rnRes; rnRes = null; r(null); }   // 连点两下不会把上一次的 Promise 挂住
  return new Promise(resolve => {
    rnRes = resolve;
    // 小卡里不再显示标题那行字（用户要求去掉），这里保持兼容：有元素才写
    const lb = $('#rnLabel');
    if (lb) lb.textContent = title || '改名字';
    inp.value = value || '';
    mask.classList.add('on');
    card.classList.add('on');
    setTimeout(() => {
      try { inp.focus(); const n = inp.value.length; inp.setSelectionRange(n, n); } catch (e) {}
    }, 180);
  });
}
function closeRename(v) {
  const card = $('#rnSheet'), mask = $('#rnMask'), inp = $('#rnInput');
  if (inp) inp.blur();
  if (card) card.classList.remove('on');
  if (mask) mask.classList.remove('on');
  const r = rnRes; rnRes = null;
  if (r) r(v);
}
function wireRename() {
  const save = $('#rnSave'), cancel = $('#rnCancel'), mask = $('#rnMask'), inp = $('#rnInput');
  if (!save || !inp) return;
  const val = () => String(inp.value || '').trim().slice(0, 20);
  save.onclick = () => { const v = val(); if (!v) { toast('名字不能空着'); return; } closeRename(v); };
  cancel.onclick = () => closeRename(null);
  mask.onclick = () => closeRename(null);
  inp.addEventListener('keydown', e => { if (e.key === 'Enter') { e.preventDefault(); save.click(); } });
}
/* 系统确认框 / 提示框，同样带磨砂背景 */
const confirmFrosted = msg => frostedSystemCall(() => confirm(msg));
const alertFrosted = msg => frostedSystemCall(() => alert(msg));
async function renameGroup() {
  if (!S.detailIds) return;
  const isItem = !S.detailIsGroup;
  const name = await askName(
    isItem ? '这个食物叫什么？' : '这份叫什么？（比如：沙县小吃）',
    S.detailName || ''
  );
  if (name === null) return;
  const v = name;
  if (!v) return;
  const sameName = v === S.detailName;
  const ids = (S.detailIds || []).slice();
  try {
    if (!sameName) await api('/api/logs/rename', { ids, name: v, item: isItem });
    closeGroup();
    await loadDay();
    // 整组改名 = 只是标签，不动营养；单条改名才联动
    if (isItem) {
      renutrifyLogs(ids, v, sameName,
        sameName ? `重新查「${v}」的营养…` : `已改名：${v} · 正在查营养…`);
    }
  } catch (e) { toast(e.message); }
}

/* ---------------- 趋势 ---------------- */
async function loadTrends() {
  try {
    const t = await api('/api/trends?days=' + S.trendDays);
    S.trend = t;
    renderTrends();
  } catch (e) {
    toast(e.message);
  }
}

function wireTrendChart() {
  const wrap = document.querySelector('#trWrap');
  if (!wrap) return;
  wrap.querySelectorAll('circle[data-d]').forEach(c => {
    c.style.cursor = 'pointer';
    c.onclick = () => { trSelDate = c.getAttribute('data-d'); renderTrends(); };
  });
}

function renderTrends() {
  const t = S.trend;
  const box = $('#trendBody');
  if (!t) { box.innerHTML = '<div class="empty-state">加载中…</div>'; return; }

  const real = t.real_tdee;
  let realCard = '';
  // 下一档还差几天（门槛和 api.js 的 computeRealTdee 一致）
  const tierTip = (r) => {
    const span = Number(r.span_days) || 0;
    const cov = Number(r.coverage) || 0;
    const table = { 偏低: { name: '中等', span: 7, cov: 50 }, 中等: { name: '较高', span: 21, cov: 70 } };
    const next = table[r.confidence];
    if (!next) return '';
    const nm = `<b style="color:var(--lime)">${next.name}</b>`;
    // 「中等」整段不许拆行（以前会出现「中"在这行、等」掉到下一行）
    const target = `<span style="white-space:nowrap">「${nm}」</span>`;
    const d = Math.max(0, next.span - span);
    if (d > 0) return `再称 ${d} 天就能到${target}`;
    // 天数够了但覆盖率不够 → 主句说人话，数字另起一行小字，不再塞一长串括号
    return `这几天把饮食记上就能到${target}
      <br><span style="color:var(--muted);font-size:12px;font-weight:400">饮食覆盖 ${cov}% → 需要 ${next.cov}%</span>`;
  };
  if (real) {
    const conf = real.confidence;
    const confColor = conf === '较高' ? 'var(--lime)' : conf === '中等' ? 'var(--orange)' : 'var(--muted)';
    realCard = `
      <div class="card">
        <h3>实测每日消耗 <span class="tag" style="color:${confColor};background:rgba(255,255,255,.06)">置信度 ${conf}</span></h3>
        <div class="kpi"><b>${real.tdee}</b><span>千卡 / 天</span></div>
        <div class="hint">
          用你 ${real.span_days} 天的体重变化反推出来的真实消耗。<br>
          体重 ${real.slope_kg_per_week > 0 ? '增加' : '减少'} ${Math.abs(real.slope_kg_per_week)} kg/周，
          期间平均摄入 ${real.avg_intake} 千卡（覆盖 ${real.coverage}% 的天数）。<br>
          <span style="display:inline-block;margin-top:4px;color:var(--text);font-size:13.5px;font-weight:600">累计 ${real.weigh_count || 1} 天${tierTip(real) ? `<br>${tierTip(real)}` : ''}</span>
        </div>
        <div class="grid2" style="margin-top:14px">
          <div class="mini"><div class="k">目标缺口</div><div class="v">${S.day?.targets.deficit ?? '—'}<small>千卡</small></div></div>
          <div class="mini"><div class="k">相对误差</div><div class="v">${
            S.day ? Math.round(Math.abs(real.tdee - S.day.expenditure) / real.tdee * 100) : '—'}<small>%</small></div></div>
        </div>
        <div style="font-size:11px;color:var(--muted2);margin-top:10px;line-height:1.6">
          这个数字才是不说谎的那个。它把所有估算误差（拍照、克重、手表）全吃掉了。
        </div>
      </div>`;
  } else {
    // 说不清"还差几天"都是废话：直接说清卡在哪一步（数据由 api 的 real_missing 给）
    const miss = t.real_missing || {};
    // 说人话：缺称重就只提称重（体脂秤会自动写进来，这个按钮只是兜底），缺饮食就提记几餐
    const lack = miss.type === 'intake'
      ? `这几天只记了 ${miss.logged} 天饮食，再记 ${Math.max(1, miss.need || 1)} 天就能算出你每天烧多少千卡`
      : `再称一次体重（隔两三天称一次就行），就能算出你每天烧多少千卡`;
    const lackBtn = miss.type === 'intake' ? '记一餐' : '记录体重';
    realCard = `
      <div class="card">
        <h3>实测每日消耗</h3>
        <div class="hint" style="margin-top:0">
          ${lack}。补齐之后就能反推出来。<br>
          <span style="color:var(--muted2);font-size:11px">原理：7700 千卡 ≈ 1kg 脂肪。体重掉的速率，就是你的真实缺口。</span><br>
          <span style="display:inline-block;margin-top:4px;color:var(--text);font-size:13.5px;font-weight:600">累计 ${Number(miss.type === 'intake' ? miss.weigh_days : miss.have) || 0} 天</span>
        </div>
        <button class="btn sm" id="goWeight" style="margin-top:14px">${lackBtn}</button>
      </div>`;
  }

  // 体重图
  const weights = t.weights || [];
  const lastW = weights.length ? weights[weights.length - 1] : null;
  const selW = trSelDate ? weights.find(x => x.date === trSelDate) : null;
  // 没点过任何点 → 默认当成点了最新的那个点，两行文字和点过时一模一样（不会出现空的「体重 kg」）
  const shownW = selW || lastW;
  const wKgs = weights.map(x => x.kg);
  const wMaxTxt = wKgs.length ? Math.max(...wKgs).toFixed(1) : '—';
  const wMinTxt = wKgs.length ? Math.min(...wKgs).toFixed(1) : '—';
  let wChart = '';
  if (weights.length >= 2) {
    wChart = `<div class="card wchart">
      <h3>体重趋势</h3>
      <div class="wminmax"><span>最高 ${wMaxTxt}</span><span>最低 ${wMinTxt}</span></div>
      <div class="chartwrap" id="trWrap">${lineChart(weights, t.start, t.end, shownW ? shownW.date : null, { range: false })}</div>
      <div class="legend wlegend">
        ${shownW
          ? `<span class="onsel"><i style="background:#6bff9a"></i>${shownW.date.slice(5)} · ${shownW.kg} kg</span>`
          : `<span><i style="background:var(--blue)"></i>体重 kg</span>`}
        <span style="margin-left:auto">${weights.length} 次记录</span>
      </div>
      ${(() => {
        const body = (S.trend && S.trend.body) || {};
        const datesB = Object.keys(body).sort();
        const latestB = datesB.length ? datesB[datesB.length - 1] : null;
        // 图上点了哪天，体脂秤那行就跟哪天走；那天没有体脂秤记录就退回最新一条
        const pickD = (trSelDate && body[trSelDate]) ? trSelDate : latestB;
        const b = pickD ? body[pickD] : null;
        if (!b || (!b.bf && !b.bmi)) return '';
        const bits = [];
        if (b.bf) bits.push('体脂率 ' + b.bf + '%');
        if (b.bmi) bits.push('BMI ' + b.bmi);
        // 上面那行已经有日期和体重时，这行就不重复写日期，只留数值
        const needDate = !shownW || pickD !== shownW.date;
        return `<div class="hint wbody">${needDate ? pickD.slice(5) + ' · ' : ''}${bits.join(' · ')}</div>`;
      })()}
    </div>`;
  } else {
    wChart = `<div class="card">
      <h3>体重趋势</h3>
      <div class="empty-state" style="padding:16px 0">至少记录 2 次体重才能画图<br>
      <button class="btn sm" id="goWeight2" style="max-width:180px;margin:14px auto 0">记录体重</button></div>
    </div>`;
  }

  // 平衡柱状图
  const bars = t.series.map(s => ({
    date: s.date,
    v: s.balance,
    intake: s.intake,
  }));
  const hasSurplus = bars.some(b => b.v != null && b.v < 0);
  const maxAbs = Math.max(300, ...bars.map(b => Math.abs(b.v || 0)));
  const barHtml = bars.map(b => {
    if (b.v == null) return `<div class="barcol"></div>`;
    if (!hasSurplus) {
      // 全是缺口时，从底部往上长，不浪费一半空间
      const h = b.v / maxAbs * 100;
      return `<div class="barcol" title="${b.date} 缺口 ${b.v}">
        <i style="height:${Math.max(1.5, h)}%;bottom:0;background:var(--lime);opacity:.85"></i>
      </div>`;
    }
    const h = Math.abs(b.v) / maxAbs * 50;
    const up = b.v > 0;
    return `<div class="barcol" title="${b.date} ${b.v}">
      <i style="height:${Math.max(1.5, h)}%;${up ? 'bottom:50%' : 'top:50%'};background:${up ? 'var(--lime)' : 'var(--orange)'};opacity:.85"></i>
    </div>`;
  }).join('');

  const topBox = $('#trendTop');
  if (topBox) topBox.innerHTML = realCard;   // 状态卡（实测消耗）不受 7/30/90 影响，单独放上面
  box.innerHTML = `
    ${t.logged_days === 0 ? `
    <div class="card">
      <h3>每日热量平衡</h3>
      <div class="empty-state" style="padding:26px 0">
        还没有数据<br>
        <span style="font-size:11.5px">去「今日」记第一笔，这里就会说话</span>
      </div>
    </div>` : `
    <div class="card">
      <h3>每日热量平衡 <span class="tag" id="avgTag">${t.avg_balance != null ? (t.avg_balance >= 0 ? '平均缺口 ' + t.avg_balance : '平均盈余 ' + Math.abs(t.avg_balance)) : '暂无数据'}</span></h3>
      <div class="barchart ${hasSurplus ? '' : 'bottom'}">${barHtml}</div>
      <div class="legend">
        <span><i style="background:var(--lime)"></i>缺口</span>
        <span><i style="background:var(--orange)"></i>盈余</span>
        <span style="margin-left:auto">${t.logged_days} / ${t.days} 天有记录</span>
      </div>
    </div>`}
    ${wChart}
    <div class="card">
      <h3>区间统计</h3>
      <div class="grid2">
        <div class="mini"><div class="k">平均摄入</div><div class="v">${t.avg_intake || '—'}<small>千卡</small></div></div>
        <div class="mini"><div class="k">平均消耗</div><div class="v">${t.avg_expenditure || '—'}<small>千卡</small></div></div>
        <div class="mini"><div class="k">记录天数</div><div class="v">${t.logged_days}<small>/ ${t.days}</small></div></div>
        <div class="mini"><div class="k">体重变化</div><div class="v">${
          weights.length >= 2
            ? ((weights[weights.length - 1].kg - weights[0].kg) >= 0 ? '+' : '') +
              (weights[weights.length - 1].kg - weights[0].kg).toFixed(1) + '<small>kg</small>'
            : '—'}</div></div>
      </div>
    </div>`;

  const gw = $('#goWeight') || $('#goWeight2');
  if (gw) {
    // 缺的是饮食记录就开到「记一餐」，缺的是体重就开体重弹层
    const needFood = gw.textContent.trim() !== '记录今天的体重' && gw.textContent.trim() !== '记录体重';
    gw.onclick = () => (needFood ? openAdd() : openWeight());
  }
  wireTrendChart();
}

function lineChart(points, start, end, selDate, opts = {}) {
  const showRange = opts.range !== false;   // 趋势页把「最高/最低」放到卡片标题右边，就不在图上重复画
  const W = 320, H = 130, pl = 4, pr = 4, pt = 12, pb = 22;
  const xs = points.map(p => +parseISO(p.date));
  const ys = points.map(p => p.kg);
  let min = Math.min(...ys), max = Math.max(...ys);
  if (max - min < 1.2) { const m = (max + min) / 2; min = m - 0.6; max = m + 0.6; }
  const padY = (max - min) * 0.18;
  min -= padY; max += padY;
  // 横轴按传入的 start/end 铺满（这样 7 天窗口里只有 2 个点也不会挤在边上）
  const sd = parseISO(start), ed = parseISO(end);
  const x0 = Number.isFinite(sd) ? sd : Math.min(...xs);
  const x1 = Number.isFinite(ed) ? ed : Math.max(...xs);
  const X = v => pl + (W - pl - pr) * (x1 === x0 ? 0.5 : (v - x0) / (x1 - x0));
  const Y = v => pt + (H - pt - pb) * (1 - (v - min) / (max - min));

  const path = points.map((p, i) => `${i ? 'L' : 'M'}${X(xs[i]).toFixed(1)},${Y(p.kg).toFixed(1)}`).join(' ');
  const area = `${path} L${X(xs[xs.length - 1]).toFixed(1)},${H - pb} L${X(xs[0]).toFixed(1)},${H - pb} Z`;
  const dots = points.map((p, i) => {
    const last = i === points.length - 1;
    const sel = selDate && p.date === selDate;
    const r = sel ? 5.5 : (last ? 4.5 : 4);
    const fill = sel ? '#6bff9a' : (last ? '#d6ff4b' : '#6ea8ff');
    return `<circle data-d="${p.date}" cx="${X(xs[i]).toFixed(1)}" cy="${Y(p.kg).toFixed(1)}" r="${r}" fill="${fill}" stroke="#15181b" stroke-width="1.5" style="pointer-events:all"/>`;
  }).join('');
  // 选中点：一条竖线从图顶到点的位置
  let vline = '';
  if (selDate) {
    const si = points.findIndex(p => p.date === selDate);
    if (si >= 0) {
      const vx = X(xs[si]).toFixed(1), vy = Y(points[si].kg).toFixed(1);
      vline = `<line x1="${vx}" y1="${pt}" x2="${vx}" y2="${H - pb}" stroke="rgba(214,255,75,.55)" stroke-width="1" stroke-dasharray="3 3"/>`;
    }
  }

  const first = points[0], last = points[points.length - 1];
  return `<svg class="chart" viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMidYMid meet">
    <defs><linearGradient id="wg" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0%" stop-color="#6ea8ff" stop-opacity=".22"/>
      <stop offset="100%" stop-color="#6ea8ff" stop-opacity="0"/>
    </linearGradient></defs>
    <path d="${area}" fill="url(#wg)"/>
    ${vline}
    <path d="${path}" fill="none" stroke="#6ea8ff" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/>
    ${dots}
    <text x="${pl}" y="${H - 6}" style="font-size:9px">${first.date.slice(5)}</text>
    <text x="${W - pr}" y="${H - 6}" text-anchor="end" style="font-size:9px">${last.date.slice(5)}</text>
    ${showRange ? `<text x="${W - pr}" y="11" text-anchor="end" style="font-size:9px;fill:var(--muted);stroke:#15181b;stroke-width:2.6;paint-order:stroke">最高 ${Math.max(...ys).toFixed(1)}</text>
    <text x="${W - pr}" y="22" text-anchor="end" style="font-size:9px;fill:var(--muted);stroke:#15181b;stroke-width:2.6;paint-order:stroke">最低 ${Math.min(...ys).toFixed(1)}</text>` : ''}
  </svg>`;
}

/* ---------------- 主题 ---------------- */
// 目标模式：只决定「蛋白质系数 + 脂肪占比」，不动用户设的缺口/盈余
// 目标模式：蛋白质系数 + 脂肪占比 + 建议缺口（正=缺口，负=盈余）
const DIET_MODES = {
  cut:      { n: '减脂', p: 2.0, fat: 0.25, deficit: 300,  tip: '缺口 300 · 蛋白 2.0' },
  maintain: { n: '维持', p: 1.6, fat: 0.28, deficit: 0,    tip: '不缺口 · 蛋白 1.6' },
  bulk:     { n: '增肌', p: 1.8, fat: 0.25, deficit: -250, tip: '盈余 250 · 蛋白 1.8' },
};
const THEMES = { lime: '#d6ff4b', blue: '#6ea8ff', orange: '#ff9f45' };

// 目标模式下面那行「建议」：只写具体数值，不重复模式名（上面的卡牌已经说清了）
function modeHintHTML(k) {
  const mm = DIET_MODES[k] || DIET_MODES.maintain;
  const d = Number(mm.deficit) || 0;
  const head = d > 0 ? '建议缺口 <b>' + d + ' 千卡 / 天</b>'
             : d < 0 ? '建议盈余 <b>' + (-d) + ' 千卡 / 天</b>'
             : '建议<b>不设缺口</b>（收支平衡）';
  const tail = d > 0 ? '，即比消耗少吃 ' + d + ' 千卡'
             : d < 0 ? '，即比消耗多吃 ' + (-d) + ' 千卡' : '';
  return head + tail + '；蛋白 <b>' + mm.p.toFixed(1) + ' g/kg</b>、脂肪约 <b>' + Math.round(mm.fat * 100) + '%</b> 热量';
}

// 缺口/盈余合理性提示：只提醒，绝不改用户填的数
function deficitAdvice(exp, deficit, bmr) {
  const d = Number(deficit) || 0;
  const e = Number(exp) || 0;
  const abs = Math.abs(d);
  if (!e) return null;
  const pct = Math.round(abs / e * 100);
  const safe = Math.round(Math.min(e * 0.25, 500));
  if (d > 0) {                                    // 缺口
    if (d >= e) return { lv: 'hard', t: `缺口 ${d} 已超过当天消耗 ${e}，每日可吃会变成 0。建议不超过 ${safe}（消耗的 25%）。` };
    if (bmr && e - d < bmr * 0.75) return { lv: 'hard', t: `每日可吃只剩 ${e - d}，已低于基础代谢 ${bmr} 的 75%，长期会掉肌肉、代谢变慢。建议缺口不超过 ${safe}。` };
    if (abs > 500 || pct > 25) return { lv: 'warn', t: `缺口偏大（占消耗 ${pct}%，约 ${(abs * 7 / 7700).toFixed(2)} kg/周）。一般建议不超过 ${safe}（25%），减得稳、不易反弹。` };
    return null;
  }
  if (d < 0) {                                    // 盈余
    if (abs > 700) return { lv: 'hard', t: `盈余 ${abs} 偏大，多出的热量更容易变成脂肪。增肌一般建议 200–300。` };
    if (abs > 400) return { lv: 'warn', t: `盈余 ${abs}（约 ${(abs * 7 / 7700).toFixed(2)} kg/周），多数人 200–300 已经够用。` };
    return null;
  }
  return null;
}
// 每个主题的[主光色, 副光色]，背景光晕和点阵跟着变
const GLOWS = {
  lime: ['#d6ff4b', '#46ffc4'],
  blue: ['#6ea8ff', '#8be3ff'],
  orange: ['#ff9f45', '#ffd08a'],
};
const rgbOf = hex => {
  const h = hex.replace('#', '');
  return [parseInt(h.slice(0,2),16), parseInt(h.slice(2,4),16), parseInt(h.slice(4,6),16)].join(', ');
};
const THEME_NAMES = { lime: '荧光绿', blue: '海水蓝', orange: '活力橙' };
function applyTheme(name) {
  const c = THEMES[name] || THEMES.lime;
  const g = GLOWS[name] || GLOWS.lime;
  const root = document.documentElement.style;
  root.setProperty('--lime', c);
  root.setProperty('--glow-rgb', rgbOf(g[0]));
  root.setProperty('--glow2-rgb', rgbOf(g[1]));
}


/* 左边缘往右滑 = 返回（关卡片 / 关弹层 / 退出我的子页） */
function goBack() {
  const on = id => { const el = $(id); return el && el.classList.contains('on'); };
  if (setCardOn()) { if (mePage) setBackToRoot(); else closeSetCard(); return; }   // 设置卡：先回首页，再关卡
  if (on('#grpSheet')) return closeGroup();
  if (on('#addSheet')) return closeAdd();
  if (on('#helpSheet')) return closeHelp();
  if (on('#weightSheet')) return closeWeight();
  if (mePage) {
    const v = $('#view-me');
    if (v) v.classList.add('slideout');
    setTimeout(() => {
      if (v) v.classList.remove('slideout');
      backToSetCard();          // 子页返回 → 回到设置卡
    }, 170);
  }
}

