/* ---------------- 通知 ---------------- */
const NOTIFY_ITEMS = {
  watch:  { t: '手表数据更新了' },
  goal:   { t: '今天吃超了' },
  day:    { t: '今天还没记录' },
  weight: { t: '早上提醒上秤' },
  fail:   { t: '同步失败' },
  daily:  { t: '每天 22:00 小结' },
};
function notifyCfg() {
  const v = setting('notify_flags', null);
  const def = { watch: true, goal: true, day: true, weight: true, fail: true, daily: true };
  if (!v || typeof v !== 'object') return def;
  const out = Object.assign({}, def);
  Object.keys(def).forEach(k => { if (typeof v[k] === 'boolean') out[k] = v[k]; });
  return out;
}
const PUSH_VAPID_PUBLIC = 'BPNsn4aHy2PzwVg0f5jUWtuKuNmhIpAeIl-yicP74Wzyas8pv4eY-x36YhKP7XuxK6v0ktNWjm6Tkb2Aitbxrz8';   // 推送公钥（私钥在仓库 Secrets，由 GitHub Actions 发）
const PUSH_SUBS_PATH = 'push-subs.json';
const GH_REPO = 'karenwang0013/calorie-ledger';
let pushOn = false;
const pushWanted = () => setting('push_wanted', false) === true;
let pushErr = '';

const pushSupported = () => ('serviceWorker' in navigator) && ('PushManager' in window) && ('Notification' in window);
const b64uToBytes = (b64) => {
  const pad = b64 + '='.repeat((4 - b64.length % 4) % 4);
  const raw = atob(pad.replace(/-/g, '+').replace(/_/g, '/'));
  return Uint8Array.from(raw, c => c.charCodeAt(0));
};

/* 订阅存进仓库的 push-subs.json（用自动同步那个 Token） */
async function saveSubToRepo(sub, remove) {
  const token = (typeof cloudToken === 'function' && cloudToken()) || '';
  if (!token) throw new Error('先在「数据备份 → 自动同步」里填好 Token');
  const payload = sub.toJSON ? sub.toJSON() : { endpoint: sub.endpoint };
  const api = 'https://api.github.com/repos/' + GH_REPO + '/contents/' + PUSH_SUBS_PATH;
  const h = { Authorization: 'Bearer ' + token, Accept: 'application/vnd.github+json' };
  let list = [], sha = null;
  const r = await fetch(api, { headers: h, cache: 'no-store' });
  if (r.ok) {
    const j = await r.json();
    sha = j.sha;
    try { list = JSON.parse(decodeURIComponent(escape(atob((j.content || '').replace(/\n/g, ''))))) || []; } catch (e) { list = []; }
  } else if (r.status !== 404) {
    throw new Error('读不到订阅文件（HTTP ' + r.status + '）');
  }
  list = (Array.isArray(list) ? list : []).filter(x => x && x.endpoint && x.endpoint !== payload.endpoint);
  if (!remove) list.push(payload);
  const body = {
    message: remove ? '推送：移除一台设备' : '推送：登记一台设备',
    content: btoa(unescape(encodeURIComponent(JSON.stringify(list, null, 2)))),
  };
  if (sha) body.sha = sha;
  const w = await fetch(api, { method: 'PUT', headers: Object.assign({}, h, { 'content-type': 'application/json' }), body: JSON.stringify(body) });
  if (!w.ok) throw new Error('订阅没存上（HTTP ' + w.status + '）');
}

async function refreshPushState() {
  pushOn = false;
  if (!pushSupported()) return;
  try {
    const reg = await navigator.serviceWorker.ready;
    let sub = await reg.pushManager.getSubscription();
    // 权限已允许、但还没订阅 → 打开 App 自动补订阅，不需要再点什么
    if (!sub && pushWanted() && Notification.permission === 'granted') {
      sub = await reg.pushManager.subscribe({ userVisibleOnly: true, applicationServerKey: b64uToBytes(PUSH_VAPID_PUBLIC) });
    }
    pushOn = !!sub;
    // 有订阅就顺手再登记一次（幂等）：换过服务、丢过文件都能自愈
    if (sub) await saveSubToRepo(sub, false);
  } catch (e) {
    pushOn = false;
    pushErr = (e && (e.name ? e.name + ': ' : '') + (e.message || e)) || '订阅失败';
  }
}

/* 把六个开关的状态写进仓库的 push-config.json，推送时按它决定发不发 */
async function syncPushConfig() {
  const token = (typeof cloudToken === 'function' && cloudToken()) || '';
  if (!token) return;
  const api = 'https://api.github.com/repos/' + GH_REPO + '/contents/push-config.json';
  const h = { Authorization: 'Bearer ' + token, Accept: 'application/vnd.github+json' };
  try {
    let sha = null;
    const r = await fetch(api, { headers: h, cache: 'no-store' });
    if (r.ok) { const j = await r.json(); sha = j.sha; }
    const body = {
      message: '推送：更新通知开关',
      content: btoa(unescape(encodeURIComponent(JSON.stringify({
        flags: notifyCfg(),
        inapp: setting('notify_inapp', true) !== false,
        updatedAt: new Date().toISOString(),
      }, null, 2)))),
    };
    if (sha) body.sha = sha;
    await fetch(api, { method: 'PUT', headers: Object.assign({}, h, { 'content-type': 'application/json' }), body: JSON.stringify(body) });
  } catch (e) {}
}

async function enablePush() {
  if (!pushSupported()) { toast('这台设备不支持网页推送', 3600); return false; }
  const standalone = window.navigator.standalone === true || window.matchMedia('(display-mode: standalone)').matches;
  if (!standalone) { toast('请从主屏幕的「热量账本」图标打开，再来开这个', 5200); return false; }
  // 请求权限必须在手势当下（不能先 await 网络）
  let perm = Notification.permission;
  if (perm !== 'granted') perm = await Notification.requestPermission();
  if (perm !== 'granted') {
    toast(perm === 'denied'
      ? '系统里拒绝了通知：去 设置 → 通知 → 热量账本 → 允许通知'
      : '没拿到通知权限，再点一次开关试试', 5600);
    return false;
  }
  try {
    const reg = await navigator.serviceWorker.ready;
    let sub = await reg.pushManager.getSubscription();
    if (!sub) sub = await reg.pushManager.subscribe({ userVisibleOnly: true, applicationServerKey: b64uToBytes(PUSH_VAPID_PUBLIC) });
    await saveSubToRepo(sub, false);
    pushOn = true;
    syncPushConfig();
    pushErr = '';
    toast('锁屏通知已开启', 2600);
    return true;
  } catch (e) {
    pushErr = (e && (e.name ? e.name + ': ' : '') + (e.message || e)) || '开启失败';
    toast('开启失败：' + pushErr, 5200);
    return false;
  }
}

async function disablePush() {
  try {
    const reg = await navigator.serviceWorker.ready;
    const sub = await reg.pushManager.getSubscription();
    if (sub) {
      try { await saveSubToRepo(sub, true); } catch (e) {}
      await sub.unsubscribe();
    }
    pushOn = false;
    toast('已关闭锁屏通知', 2200);
  } catch (e) { toast('关闭失败：' + (e.message || e), 3600); }
}

// 打开 App / 拉到数据后跑一次：每条一天只提醒一次，显示一条就停
/* 数据文件走 Gitee（国内直连稳定），网页仍在 GitHub Pages。
   注意：必须用 API 读，raw 链接会 302 到 raw.giteeusercontent.com，那个域名没有 CORS 头，浏览器会拒绝。 */
const GITEE_API = 'https://gitee.com/api/v5/repos/karen228/calorie-ledger-data/contents';
let freshAt = { health: 0, body: 0 };
let bodyVer = 0;   // v8.21：身体数据每写进本机一次就 +1，定时轮询靠它判断要不要重画页面
let _giteeLightAt = 0;   // v8.23：镜像都读不到时，回退问 Gitee 的最低间隔（省额度）
let lastHealthFrom = '';   // 最近一次热量数据是从哪一路读到的（镜像/GitHub/Gitee），排查用   // 上次直接读 Gitee 源的时间（5 分钟内不重复读）
const _gtCache = {};
let giteeBlockedUntil = 0;
async function giteeGetText(path, force) {
  const now = Date.now();
  // 被限流后 10 分钟内不再请求，直接用缓存（没有缓存就抛错，但不刷屏）
  if (now < giteeBlockedUntil) {
    const c = _gtCache[path];
    if (c) return c.txt;
    throw new Error('HTTP 403（限流冷却中）');
  }
  const hit = _gtCache[path];
  if (!force && hit && now - hit.at < 900000) return hit.txt;   // 15 分钟内复用（Gitee 每小时只有 60 次额度，省给快捷指令）
  let r = null, err = null;
  for (let i = 0; i < 2; i++) {
    try {
      const tk = (typeof setting === 'function' ? (setting('gitee_token', '') || '') : '').trim();
      const url = GITEE_API + '/' + path + '?t=' + now + (tk ? '&access_token=' + encodeURIComponent(tk) : '');
      r = await fetchT(url, { cache: 'no-store' }, 4000);
      if (r.ok) break;
      // 4xx 不重试（重试也没用，还会加重限流）
      if (r.status === 403 || r.status === 429) {
        giteeBlockedUntil = Date.now() + 10 * 60 * 1000;   // 冷却 10 分钟
        throw new Error('HTTP ' + r.status);
      }
      if (r.status >= 400 && r.status < 500) throw new Error('HTTP ' + r.status);
      err = new Error('HTTP ' + r.status);
    } catch (e) { err = e; }
    r = null;
    await new Promise(res => setTimeout(res, 700));
  }
  if (!r) throw err || new Error('Load failed');
  const j = await r.json();
  const b64 = String(j && j.content || '').replace(/\s/g, '');
  if (!b64) throw new Error('内容为空');
  const txt = decodeURIComponent(escape(atob(b64)));
  _gtCache[path] = { at: now, txt };
  return txt;
}
function notifyLogGet() {
  const d = Store.load();
  return Array.isArray(d.notifyLog) ? d.notifyLog : [];
}

function logNotify(kind, title, body, ok = true) {
  const d = Store.load();
  const list = Array.isArray(d.notifyLog) ? d.notifyLog : (d.notifyLog = []);
  const today = todayISO();
  // 同一类同一天只记一条
  if (list.some(x => x.k === kind && String(x.d) === today)) return false;
  list.push({ ts: Date.now(), d: today, k: kind, t: title, b: body, ok: ok !== false });
  if (list.length > 60) list.splice(0, list.length - 60);
  Store.save({ silent: true });
  return true;
}
/* 把浏览器的英文报错翻译成人话，并给一个错误码（方便截图排查） */
function friendlyErr(m) {
  const t = String(m || '');
  if (/Load failed|Failed to fetch|NetworkError|offline|The Internet connection appears to be offline/i.test(t)) {
    return 'E01 连不上云端 · 已自动重试，不影响本机记录（稍后自己会再同步）';
  }
  if (/AbortError|timeout|超时/i.test(t)) return 'E02 云端响应超时 · 网络太慢';
  if (/401|Bad credentials|Requires authentication|access_token/i.test(t)) return 'E03 令牌无效或没填 · 去 设置 → 数据同步 填 Gitee 令牌';
  if (/403|429/.test(t)) return 'E04 被 Gitee 限流 · 等几分钟再点「数据同步」（缓存还在，不影响看数据）';
  if (/404/.test(t)) return 'E05 云端文件不存在 · 可能被删了';
  if (/409|422/.test(t)) return 'E06 云端版本冲突 · 稍后会自动重试';
  if (/403|rate limit|limit exceeded|限流/i.test(t)) return 'E07 Gitee 限流（读太频繁）· 会自动重试，不影响本机记录';
  if (/JSON|Unexpected token|parse/i.test(t)) return 'E07 数据格式不对 · 文件内容被改坏了';
  if (/quota|storage|space/i.test(t)) return 'E08 手机存储写不进去了 · 先导出备份';
  if (/E10/.test(t)) return t;   // 数值异常，原样显示
  return 'E99 ' + (t || '未知错误');
}

/* 错误提醒的「宽限期」：短时间内的失败不打扰，连续失败/持续太久才记一条 */
const ERR_GRACE = { minFails: 3, windowMs: 150000 };
function logError(kind, title, body) {
  try {
    const key = 'errc_' + kind;
    let st = {};
    try { st = JSON.parse(localStorage.getItem(key) || '{}') || {}; } catch (e) { st = {}; }
    const now = Date.now();
    if (!st.first || now - st.first > ERR_GRACE.windowMs) st = { first: now, n: 0 };
    st.n = (st.n || 0) + 1;
    localStorage.setItem(key, JSON.stringify(st));
    if (st.n < ERR_GRACE.minFails) return false;   // 还在宽限期，先不打扰
  } catch (e) {}
  return logNotify(kind, title, friendlyErr(body), false);
}
/* 成功之后：清掉这个类别的错误计数，并把之前记的错误提醒删掉 */
function clearErr(kind) {
  try { localStorage.removeItem('errc_' + kind); } catch (e) {}
  try {
    const d = Store.load();
    if (!Array.isArray(d.notifyLog)) return;
    const before = d.notifyLog.length;
    d.notifyLog = d.notifyLog.filter(x => !(x.k === kind && x.ok === false));
    if (d.notifyLog.length !== before) Store.save({ silent: true });
  } catch (e) {}
}

function renderNotifyDot() {
  const dot = $('#notifyDot');
  if (!dot) return;
  const seen = Number(localStorage.getItem('notify_seen_ts') || 0);
  const unread = notifyLogGet().filter(x => Number(x.ts) > seen);
  if (!unread.length) { dot.hidden = true; dot.className = 'dot'; return; }
  const bad = unread.filter(x => x.ok === false).length;
  const good = unread.length - bad;
  // 全成功=绿，成功+失败=橙，全失败=红
  const kind = bad === 0 ? 'ok' : (good === 0 ? 'bad' : 'mix');
  dot.hidden = false;
  dot.className = 'dot ' + kind;
}
function nlogOn() {
  const s = $('#nlogSheet');
  return !!(s && s.classList.contains('on'));
}
function openNotifyLog() {
  closeOtherCards('nlog');   // 三张卡同时只允许开一张
  ensureSetCardH(); // 和设置卡同高（这时设置卡是关着的，量的就是标准尺寸）
  // 第一次打开且没有记录时，放两条「示例」，让用户看清卡片长什么样（清空即消失）
  let all = notifyLogGet();
  if (!all.length && !localStorage.getItem('notify_demo_seeded')) {
    const d = Store.load();
    d.notifyLog = [
      { ts: Date.now() - 3600 * 1000, d: todayISO(), k: 'demo-weight', t: '该称体重了', b: '上次记是 3 天前，今晚站上秤称一次吧' },
      { ts: Date.now() - 26 * 3600 * 1000, d: todayISO(), k: 'demo-goal', t: '今天已超出目标', b: '超出 120 千卡 · 今天可吃 1207 千卡' },
    ];
    Store.save({ silent: true });
    localStorage.setItem('notify_demo_seeded', '1');
    all = d.notifyLog;
  }
  const list = all.slice().sort((a, b) => b.ts - a.ts);
  const box = $('#nlogList');
  // 和设置卡同一套行式布局：荧光绿 Material 图标 + 标题 + 小字说明 + 右侧时间
  const isoOf = (ts) => {
    const t = new Date(ts), p2 = n => String(n).padStart(2, '0');
    return t.getFullYear() + '-' + p2(t.getMonth() + 1) + '-' + p2(t.getDate());
  };
  const labelOf = (ts) => {
    const iso = isoOf(ts), t = new Date(ts), p2 = n => String(n).padStart(2, '0');
    return iso === todayISO() ? p2(t.getHours()) + ':' + p2(t.getMinutes()) : iso.slice(5);
  };
  const slotOf = (k, ok) => {
    if (ok === false) return 'nlog.fail';
    const s = String(k || '');
    if (s.includes('body') || s.includes('weight')) return 'nlog.weight';
    if (s.includes('goal')) return 'nlog.goal';
    if (s.includes('watch')) return 'nlog.watch';
    if (s.includes('day')) return 'nlog.day';
    return 'nlog.day';
  };
  const iconOf = (k, ok) => {
    if (ok === false) return 'danger';         // 失败那条：橙色 report（用户在选图页选定的）
    const s = String(k || '');
    if (s.includes('body') || s.includes('weight')) return 'monitor';   // 体重秤
    if (s.includes('goal')) return 'fire';                              // 超出目标：火
    if (s.includes('watch')) return 'watchM';                           // 手表
    if (s.includes('day')) return 'sticky';                               // 还没记录：便签
    return 'bellAct';
  };
  const rowOf = x => `
    <div class="setrow">
      <span class="ico"${x.ok === false ? ' style="color:var(--orange)"' : ''}><svg viewBox="0 -960 960 960" aria-hidden="true"><path d="${iconPath(slotOf(x.k, x.ok)) || SET_ICONS[iconOf(x.k, x.ok)]}"/></svg></span>
      <span><div class="ttl">${esc(x.t || '提醒')}</div>${x.b ? `<div class="sub">${esc(x.b)}</div>` : ''}</span>
      <span class="when">${labelOf(x.ts)}</span>
    </div>`;
  if (box) {
    if (list.length) {
      const today = list.filter(x => isoOf(x.ts) === todayISO());
      const older = list.filter(x => isoOf(x.ts) !== todayISO());
      box.innerHTML = [['今天', today], ['更早', older]]
        .filter(g => g[1].length)
        .map(([label, arr]) => `<div class="setlabel">${label}</div><div class="setrows">${arr.map(rowOf).join('')}</div>`)
        .join('');
    } else {
      box.innerHTML = `<div class="setrows"><div id="nlogEmpty">还没有提醒记录<span>称重、超出目标、今天没记录这类提醒，都会记在这里</span></div></div>`;
    }
  }
  const cnt = $('#nlogCount');
  if (cnt) cnt.textContent = '共 ' + list.length + ' 条';
  // 尺寸和设置卡一致（同一张卡，内容多了在卡里滚）
  const nlogH = ensureSetCardH();
  localStorage.setItem('notify_seen_ts', String(Date.now()));
  renderNotifyDot();
  const mask = $('#nlogMask'), sheet = $('#nlogSheet');
  if (sheet) {
    sheet.classList.toggle('hide-x', !NLOG_UI.closeX);
    sheet.classList.toggle('hide-grab', !NLOG_UI.grab);
    sheet.classList.toggle('title-center', !!NLOG_UI.titleCenter);
    sheet.classList.toggle('hide-title', !NLOG_UI.showTitle);
  }
  document.body.classList.add('nlog-open');
  if (sheet && nlogH) sheet.style.height = nlogH + 'px';
  raiseSheet(sheet);                         // 最后打开的放在最上面
  // 位置：恢复原来的底部位置（居中会和 Dock 栏重叠）
  if (sheet) { sheet.style.top = ''; sheet.style.bottom = ''; }
  if (mask) mask.classList.add('on');
  if (sheet) sheet.classList.add('on');
}
function closeNotifyLog() {
  document.body.classList.remove('nlog-open');
  const mask = $('#nlogMask'), sheet = $('#nlogSheet');
  if (sheet) { sheet.classList.remove('dragging'); sheet.style.transform = ''; sheet.style.opacity = ''; sheet.style.height = ''; }
  if (mask) mask.classList.remove('on');
  if (sheet) sheet.classList.remove('on');
  // 临时定位（top/bottom）也要清掉，否则下次的"关闭位置"会落在屏幕里
  if (sheet) setTimeout(() => { sheet.style.top = ''; sheet.style.bottom = ''; }, 420);
}

/* 提醒记录：手指下滑关闭（列表在顶部时生效），松手回弹或关闭 */
function wireSheetDrag(sheet, list, closeFn) {
  if (!sheet || sheet.dataset.dragWired) return;
  sheet.dataset.dragWired = '1';
  let y0 = 0, x0 = 0, dy = 0, dragging = false, armed = false, horiz = false;
  sheet.addEventListener('touchstart', (e) => {
    if (!sheet.classList.contains('on')) return;
    y0 = e.touches[0].clientY; x0 = e.touches[0].clientX; dy = 0; dragging = false; horiz = false;
    armed = !list || list.scrollTop <= 0;
  }, { passive: true });
  sheet.addEventListener('touchmove', (e) => {
    if (!armed || !sheet.classList.contains('on')) return;
    // 横向成分更大 = 在滑图表 / 翻页，不归这个手势管（否则会把卡拖着走甚至关掉）
    if (!dragging) {
      const dx0 = Math.abs(e.touches[0].clientX - x0);
      const dy0 = Math.abs(e.touches[0].clientY - y0);
      if (dx0 > 12 && dx0 > dy0) { horiz = true; armed = false; return; }
    }
    if (horiz) return;
    const d = e.touches[0].clientY - y0;
    if (d <= 0) {
      if (!dragging) return;
      dy = 0;
      sheet.style.transform = '';
      sheet.style.opacity = '';
      return;
    }
    dy = d;
    if (dy > 4) {
      dragging = true;
      sheet.classList.add('dragging');
      sheet.style.transform = 'translateY(' + dy + 'px)';
      sheet.style.opacity = String(Math.max(0.82, 1 - dy / 1600));
      e.preventDefault();
    }
  }, { passive: false });
  const end = () => {
    if (!dragging) { dy = 0; return; }
    dragging = false;
    sheet.classList.remove('dragging');
    if (dy > 96) {
      closeFn();                      // 走 CSS 的滑出动画
      // 一定把拖拽时写进去的行内样式清掉：不清的话下次打开会停在半路，
      // 手指被系统打断（touchcancel）时更是直接"卡住 / 像死机"
      setTimeout(() => { sheet.style.transform = ''; sheet.style.opacity = ''; }, 420);
    } else {
      sheet.style.transform = '';
      sheet.style.opacity = '';
    }
    dy = 0;
  };
  sheet.addEventListener('touchend', end);
  sheet.addEventListener('touchcancel', end);   // 系统打断也要复位，否则会卡在拖到一半的位置
  sheet.addEventListener('touchcancel', end);
}
function wireNotifyDrag() { wireSheetDrag($('#nlogSheet'), $('#nlogList'), closeNotifyLog); }
function wireSetDrag() { wireSheetDrag($('#setSheet'), $('#setBody'), closeSetCard); }
/* 记录卡片：同一套下滑关闭（内容滚到顶才生效，别和内部滚动打架） */
function wireAddDrag() {
  /* 记录卡不再用「下拉关闭」：那个手势会把整张卡（连三格条）跟着手指往下拖，
     用户要求拍照/搜索/描述这一条完全固定 → 只能点卡外或按系统返回关闭。
     提醒记录卡的下拉关闭仍然保留（wireNotifyDrag）。 */
}

function runNotifyChecks() {
  if (setting('notify_inapp', true) === false) return false;   // 总开关关掉就全部静音
  const d = S.day;
  if (!d || !S.date || S.date !== S.today) return false;
  const cfg = notifyCfg();
  let seen = {};
  try { seen = JSON.parse(localStorage.getItem('notify_seen') || '{}') || {}; } catch (e) { seen = {}; }
  const hit = (k) => { if (!cfg[k] || seen[k] === S.today) return false; seen[k] = S.today; localStorage.setItem('notify_seen', JSON.stringify(seen)); return true; };
  const t = d.targets || {};
  const intake = d.intake || 0;
  const left = Math.round((t.kcal_budget || 0) - intake);
  const exp = Math.round(d.expenditure || 0);

  if (d.watch && d.watch.source === 'cloud' && hit('watch')) {
    logNotify('watch', '手表数据已更新', `消耗 ${exp} 千卡 · 还可以吃 ${left} 千卡`);
    return true;
  }
  if (intake > 0 && left < 0 && hit('goal')) {
    logNotify('goal', '今天已超出目标', `超出 ${Math.abs(left)} 千卡`);
    return true;
  }
  if (new Date().getHours() >= 20 && !((d.logs || []).length) && hit('day')) {
    logNotify('day', '今天还没记录', '别忘了记一笔');
    return true;
  }
  if (hit('weight')) {
    const st0 = Store.load();
    const ws = st0.weights || {};
    const dates = Object.keys(ws).sort();
    const last = dates[dates.length - 1];
    const days = last ? Math.floor((Date.now() - new Date(last + 'T00:00:00').getTime()) / 86400000) : 999;
    // 反推真实消耗需要「连续称重 + 连续记饮食」：数据不够就每天提醒（连称几天），够了就每周一次
    let nW = 0, nL = 0;
    for (let i = 0; i < 10; i++) {
      const dd = addDays(todayISO(), -i);
      if (ws[dd] != null) nW++;
      if ((st0.logs || []).some(l => l.date === dd)) nL++;
    }
    const needW = Math.max(0, 4 - nW), needL = Math.max(0, 2 - nL);
    const sprint = needW > 0 || needL > 0;
    const gap = sprint ? 1 : 7;
    const weighedToday = ws[todayISO()] != null;
    if (!weighedToday && days >= gap) {
      const tip = sprint
        ? (needW > 0 ? `再连续称 ${needW} 天，就能反推真实消耗` : `再记 ${needL} 天饮食，就能反推真实消耗`)
        : `上次是 ${days} 天前，一周一次保持曲线`;
      logNotify('weight', '该称体重了', tip);
      return true;
    }
    delete seen.weight; localStorage.setItem('notify_seen', JSON.stringify(seen));   // 没到期就不占用今天的名额
  }
  return false;
}

function pushNote() {
  if (!pushSupported()) return '这台设备不支持网页推送（要从主屏幕图标打开）';
  const perm = (typeof Notification !== 'undefined') ? Notification.permission : 'unknown';
  const permTxt = perm === 'granted' ? '已允许' : perm === 'denied' ? '被拒绝' : '还没允许';
  if (pushOn) return `已订阅 · 通知权限${permTxt} · 锁屏、App 关闭时也能收到`;
  if (pushWanted() && pushErr) return `⚠️ 没登记上：${pushErr}`;
  if (pushWanted()) return `已打开，正在登记…（通知权限：${permTxt}）下次打开 App 会自动重试`;
  return `网页自己要有一台推送服务才能锁屏提醒；点右侧开关开始（当前权限：${permTxt}）`;
}


/* ---------------- 图标：icons.js 提供库与默认值（入口在「个性化」页里） ---------------- */
function iconOverride(){ try { return JSON.parse(localStorage.getItem('icon_override') || '{}'); } catch(e) { return {}; } }
function iconName(slot){
  const ov = iconOverride()[slot];
  const def = (window.ICON_DEFAULT || {})[slot];
  return (ov && (window.ICON_LIB || {})[ov]) ? ov : def;
}
function iconPath(slot){
  const n = iconName(slot);
  return (window.ICON_LIB || {})[n] || '';
}

/* 图标选择卡：v8.80 起并入「个性化」页（不再单独占设置首页一行） */
function iconPickerCard() {
  const ov = iconOverride();
  return `<div class="card">
      <h3>图标</h3>
      <div class="hint" style="margin:0 0 10px">点一下立刻替换；排在第一格的是你正在用的那个，想回出厂那套就点「默认」。</div>
      <button class="btn ghost sm" id="icReset" style="margin-bottom:12px">恢复全部默认</button>
      ${(window.ICON_SLOTS || []).map(s => {
        /* v8.88 用户口径：第一格永远是「当前正在用的那个」——选了别的图标，它排到第一位，
           「默认」退到第二位；没改过时第一位就是「默认」。其余候选保持原来的顺序。
           点名：以前是「默认」死死钉在第一格，选了别的以后第一格还是默认，看着像没生效。 */
        const curName = ov[s.k] || '';
        const lib = window.ICON_LIB || {};
        /* 「默认」这一格永远是**出厂图案**，不能跟着当前选择变 —— 否则选了别的以后，
           默认那格画的是你选的图案，看着像两个一样的按钮（用户 2026-10-25 报的就是这个）。 */
        const defName = (window.ICON_DEFAULT || {})[s.k] || '';
        const all = [{ n: '', label: '默认', d: lib[defName] || '' }]
          .concat((s.opts || []).map(n => ({ n, label: n, d: lib[n] || '' })));
        const ordered = all.filter(o => o.n === curName).concat(all.filter(o => o.n !== curName));
        return `<div class="icrow">
          <div class="icl">${s.label}</div>
          <div class="icopts">
            ${ordered.map(o => `<button class="icopt${o.n === curName ? ' on' : ''}" data-slot="${s.k}" data-name="${o.n}" title="${o.label}">
              <svg viewBox="0 -960 960 960"><path d="${o.d}"/></svg><span>${o.label}</span>
            </button>`).join('')}
          </div>
        </div>`;
      }).join('')}
    </div>`;
}
/* 静态 svg（顶栏/底栏/三格/按钮）统一按 data-icn 重画 */
function applyStaticIcons(){
  $$('svg[data-icn]').forEach(svg => {
    const slot = svg.getAttribute('data-icn');
    const d = iconPath(slot);
    if (!d) return;
    svg.setAttribute('viewBox', '0 -960 960 960');
    svg.setAttribute('fill', 'currentColor');
    let pth = svg.querySelector('path');
    if (!pth) { pth = document.createElementNS('http://www.w3.org/2000/svg', 'path'); svg.appendChild(pth); }
    pth.setAttribute('d', d);
    svg.querySelectorAll('circle').forEach(c => c.remove());
  });
}



/* 三张浮层卡（记录 / 设置 / 提醒记录）同一时间只允许开一张 —— 打开任意一张先把另两张收掉 */
function addCardOn() { const s = $('#addSheet'); return !!(s && s.classList.contains('on')); }
function closeOtherCards(keep) {
  if (keep !== 'add' && addCardOn()) closeAdd();
  if (keep !== 'set' && setCardOn()) closeSetCard();
  if (keep !== 'nlog' && nlogOn()) closeNotifyLog();
}

