let setFromView = 'today';          // 打开设置卡时停在哪个页面（「完成」就回到它）
let setCardH = 0;                   // 设置首页那张卡的高度：进子页后卡不许变大变小，内容多就在卡里滚

function setRowHTML(page, icon, label, val, slot) {
  const d = (slot && iconPath(slot)) || SET_ICONS[icon] || '';   // 库里取不到就退回内置，绝不画空
  return `<button class="setrow" data-page="${page}">
    <span class="ico"><svg viewBox="0 -960 960 960" aria-hidden="true"><path d="${d}"/></svg></span>
    <span>${label}</span>
    <em>${val}</em><i>›</i>
  </button>`;
}

/* 卡里的内容：8 行 + 版本行（值全部取本机真实数据） */
function renderSetCard() {
  const box = $('#setBody');
  if (!box || !S.day) return;
  const d = S.day, p = d.profile || {};
  const ver = $('#setVer');
  if (ver) ver.textContent = APP_VERSION;

  const st = Store.load();
  const ds = Object.keys(st.body || {}).sort();
  const last = ds[ds.length - 1];
  const b = last ? st.body[last] : null;
  const w = last ? st.weights[last] : null;
  const bodyTxt = !last
    ? '还没有秤的数据'
    : ((w ? w + ' kg' : '') + (b && b.bf ? ' · 体脂 ' + b.bf + '%' : '') || '—');

  box.innerHTML = `
    <div class="setlabel">功能</div>
    <div class="setrows">
      ${setRowHTML('body', 'personOpen', '身体与目标', `${p.height_cm || 165}cm · ${p.weight_kg || 60}kg`, 'set.body')}
      ${setRowHTML('nutri', 'goal', '饮食目标', `${d.targets.kcal_budget} 千卡 / 天`, 'set.goal')}
      ${setRowHTML('bodydata', 'insights', '身体数据', bodyTxt, 'set.weight')}
      ${setRowHTML('ai', 'ai', 'AI 识别', d.has_key ? '已配置' : '未配置', 'set.ai')}
      ${setRowHTML('theme', 'brush', '个性化', THEME_NAMES[d.theme] || '荧光绿', 'set.theme')}
      ${setRowHTML('notify', 'bellAct', '通知', d.sync_toast ? '开' : '关', 'set.notify')}
    </div>
    <div class="setlabel">其他</div>
    <div class="setrows">
      ${setRowHTML('data', 'db', '数据备份', setting('gitee_token') ? '自动同步中' : '未开启', 'set.backup')}
      ${setRowHTML('about', 'sysupd', '关于与更新', APP_VERSION, 'set.about')}
    </div>
    <div class="setrows last">
      <div class="setrow ver">
        <span>版本更新</span>
        <em>${APP_VERSION}</em>
        <button class="setpill" id="hardReload">强制更新</button>
      </div>
    </div>
`;

  const hr = $('#hardReload');
  if (hr) hr.onclick = () => hardReloadApp();
  $$('#setBody .setrow[data-page]').forEach(b2 => b2.onclick = () => openSetSub(b2.dataset.page));
}

function setCardOn() {
  const s = $('#setSheet');
  return !!(s && s.classList.contains('on'));
}

/* 卡里那 8 个子页的标题（点行进子页时显示在卡头，不再跳整页） */
const SET_SUB_TITLE = {
  body: '身体与目标', nutri: '饮食目标', bodydata: '身体数据', ai: 'AI 识别',
  theme: '个性化', notify: '通知', data: '数据备份', about: '关于与更新'
};

/* 卡头：首页 = 设置 + 版本徽标；子页 = ‹ + 子页标题 */
function setCardHeader() {
  const hd = $('#setSheet .sh-hd');
  if (!hd) return;
  const t = hd.querySelector('h2'), v = $('#setVer'), back = $('#setBack');
  if (mePage) {
    if (t) t.textContent = SET_SUB_TITLE[mePage] || '设置';
    if (v) v.hidden = true;
    if (back) back.hidden = false;
  } else {
    if (t) t.textContent = '设置';
    if (v) { v.hidden = false; v.textContent = APP_VERSION; }
    if (back) back.hidden = true;
  }
}

/* 卡里的内容：首页行式列表 / 子页（就地在卡里换内容，不跳页） */
function refreshSetBody() {
  const sheet = $('#setSheet');
  if (sheet) sheet.style.height = '';           // 先松绑，首页才能量到"内容撑开"的真实高度
  if (mePage) renderMe(); else renderSetCard();
  setCardHeader();
  if (!sheet) return;
  if (!mePage) {
    setCardH = sheet.offsetHeight;   // 首页高度 = 这张卡的标准尺寸（offsetHeight 不受入场 scale(.98) 影响）
  } else if (setCardH) {
    sheet.style.height = setCardH + 'px';       // 子页：尺寸不变，装不下就在卡里上下滑
  }
}

/* 设置卡那张卡的标准高度：提醒记录卡也要用同一个值（两张卡同一尺寸） */
function ensureSetCardH() {
  if (setCardH) return setCardH;
  const s = $('#setSheet');
  if (!s || !S.day || mePage) return 0;
  if (!s.querySelector('.setrow[data-page]')) renderSetCard();
  setCardH = s.offsetHeight;
  return setCardH;
}

/* 量一次首页卡高（进子页前必须先有这个值） */
function measureRootH() {
  const sheet = $('#setSheet');
  if (!sheet || mePage) return;
  sheet.style.height = '';
  setCardH = sheet.offsetHeight;
}

/* 子页 → 回卡首页 */
function setBackToRoot() {
  mePage = null;
  refreshSetBody();          // 松绑 → 回列表 → 重新量高
  const b = $('#setBody'); if (b) b.scrollTop = 0;
}

function openSetCard() {
  const sheet = $('#setSheet'), mask = $('#setMask');
  if (!sheet) return;
  closeOtherCards('set');           // 原则：三张卡同时只允许开一张
  if (!setCardOn()) setFromView = (S.view && S.view !== 'me') ? S.view : (setFromView || 'today');
  refreshSetBody();
  document.body.classList.add('set-open');
  raiseSheet(sheet);
  if (mask) mask.classList.add('on');
  sheet.classList.add('on');
}

function closeSetCard() {
  const sheet = $('#setSheet'), mask = $('#setMask');
  if (!sheet) return;
  mePage = null;                 // 下次打开从首页开始
  sheet.style.height = '';       // 清掉子页锁的高度
  document.body.classList.remove('set-open');
  if (mask) mask.classList.remove('on');
  sheet.classList.remove('on');
  sheet.classList.remove('dragging');
  sheet.style.transform = '';
  sheet.style.opacity = '';
}

/* 子页返回：回到设置卡（并且回到打开卡时所在的那个页面） */
function backToSetCard() {
  mePage = null;
  if (S.view === 'me') switchView(setFromView && setFromView !== 'me' ? setFromView : 'today');
  else renderMe();
  openSetCard();
}

/* 点卡里的某一行 → 卡原地换内容（不跳整页，也不关这张卡） */
function openSetSub(page) {
  if (!page) return;
  if (!setCardH) measureRootH();
  mePage = page;
  if (page === 'bodydata') { bodySelDate = null; bodyTrendPage = 0; }   // 每次进来从「最近一次」看起
  if (!setCardOn()) openSetCard(); else refreshSetBody();
  const b = $('#setBody'); if (b) b.scrollTop = 0;
  if (page === 'bodydata') {
    pullBodyJson(true).then(j => { if (j) { try { refreshBodyViews(); } catch (e) {} } }).catch(() => {});
  }
}

function renderMe() {
  const d = S.day;
  if (!d) return;
  const p = d.profile || {};
  const acts = d.activity_labels || {};
  const opt = Object.entries(acts).map(([k, v]) =>
    `<option value="${k}" ${p.activity === k ? 'selected' : ''}>${esc(v)}</option>`).join('');

  let h = '';

  if (!mePage) {
    // 设置首页不再是整页：内容是那张玻璃卡（见 renderSetCard / openSetCard），页面保持空
    h = '';
  } else if (mePage === 'body') {
    h = meBackBar('身体与目标') + `
      <div class="card">
        <div class="split">
          <div class="field">
            <label>性别</label>
            <select id="fSex">
              <option value="" ${!p.sex ? 'selected' : ''} disabled>请选择</option>
              <option value="female" ${p.sex === 'female' ? 'selected' : ''}>女</option>
              <option value="male" ${p.sex === 'male' ? 'selected' : ''}>男</option>
            </select>
          </div>
          <div class="field">
            <label>出生年份</label>
            <input id="fYear" type="number" inputmode="numeric" value="${p.birth_year || 1995}">
          </div>
          <div class="field">
            <label>身高（cm）</label>
            <input id="fHeight" type="number" inputmode="decimal" value="${p.height_cm || 165}">
          </div>
          <div class="field">
            <label>体重（kg）</label>
            <input id="fWeight" type="number" inputmode="decimal" step="0.1" value="${p.weight_kg || 60}">
          </div>
        </div>
        <div class="field">
          <label>日常活动量</label>
          <select id="fAct">${opt}</select>
          <div class="hint">没有手表数据时用来估算日常消耗。有手表的话会被覆盖。</div>
        </div>
        <button class="btn primary" id="saveProfile">保存</button>
      </div>`;
  } else if (mePage === 'ai') {
    h = meBackBar('AI 识别') + `
      <div class="card">
        <div class="hint" style="margin:0 0 14px">用于拍照识别食物、读营养成分表。Key 只存在这台设备，不上传。</div>
        <div class="field">
          <label>DashScope API Key</label>
          <input id="fKey" type="password" placeholder="${d.has_key ? '已保存，如需更换请重新填写' : 'sk-...'}" autocomplete="off">
          <div class="hint">获取地址：bailian.console.aliyun.com</div>
        </div>
        <div class="btnrow">
          <button class="btn sm" id="saveKey">保存</button>
          <button class="btn sm" id="testKey">测试连接</button>
        </div>
        ${d.has_key ? '<button class="linkbtn" id="peekKey" style="margin-top:10px">查看已保存的 Key</button>' : ''}
        ${d.ai_model ? `<div style="font-size:11px;color:var(--muted2);margin-top:10px">当前模型：${esc(d.ai_model)}</div>` : ''}
      </div>`;
  } else if (mePage === 'data') {
    h = meBackBar('数据备份') + `
      <div class="card">
        <div class="cardhd"><h3>自动同步</h3><button class="linkbtn" id="stopGh">关闭同步</button></div>
        <div class="hint" style="margin:0 0 12px">
          填一个 Gitee 私人令牌，之后每次记账都会自动传到 <code>calorie-ledger-data</code> 仓库的 <code>data.json</code>（国内直连，稳定）。<br>
          换设备时在那边填同一个 Token，点「开启同步」：会先读云端，有云端数据就用云端覆盖这台设备，云端没有才上传本机。
        </div>
        <div class="field">
          <label>Gitee 私人令牌</label>
          <input id="fGhToken" type="password" placeholder="${setting('gitee_token') ? '已填写，需要更换再输入' : 'Gitee 私人令牌'}" autocomplete="off">
          <div class="hint">只勾 <b>projects</b> 权限即可（gitee.com → 设置 → 私人令牌）</div>
        </div>
        <div class="btnrow">
          <button class="btn primary sm" id="saveGhToken">开启同步</button>
          <button class="btn sm" id="syncNow">立即同步</button>
          <button class="btn sm btntwo" id="cloudForcePush">本机<br class="brk">覆盖云端</button>
          <button class="btn sm btntwo" id="cloudForcePull">云端<br class="brk">覆盖本机</button>
        </div>
        <div class="hint" id="cloudState" style="margin-top:10px"></div>
        ${localStorage.getItem('pending_push') ? '<div class="hint" style="margin-top:6px;color:#ffab3d">有改动还没传上去（网络问题）· 会自动重试，不会丢</div>' : ''}
      </div>
      <div class="card">
        <h3>手动备份 / 回滚（iCloud / AirDrop）</h3>
        <div class="hint" style="margin:0 0 14px">
          自动同步只保留最新一份；万一误删、误改，用这里存的快照恢复。<br>
          卸载 / 重新添加主屏幕 App 会清空数据，卸载前先备份。<br>
          iPhone 备份后，在 iPad 选同一个文件也能恢复。
        </div>
        <button class="btn primary" id="exportJson">备份文件</button>
        <button class="btn sm" id="importJson" style="margin-top:10px">从文件恢复</button>
        <input type="file" id="importFile" accept="application/json,.json" hidden>
        <div class="hint" style="margin-top:12px" id="backupAt"></div>
        <div class="btnrow" style="margin-top:14px">
          <button class="btn ghost sm" id="exportCsv">导出 CSV</button>
        </div>
      </div>
      <div class="card">
        <h3>网络自检</h3>
        <div class="hint" style="margin:0 0 12px">检查令牌、Gitee 连通性和真实读写。出问题时先点这里。</div>
        <button class="btn sm" id="netCheck" style="width:100%">开始自检</button>
        <pre id="netCheckOut" style="display:none;margin:12px 0 0;padding:10px 12px;border-radius:12px;background:rgba(255,255,255,.04);color:var(--muted);font-size:11.5px;line-height:1.7;white-space:pre-wrap;word-break:break-all"></pre>
      </div>
`;
  } else if (mePage === 'nutri') {
    const a = (d.targets.auto) || {};
    // 根据最近的身体数据给一个模式建议
    const rec = (() => {
      const st = Store.load();
      const ds = Object.keys(st.body || {}).filter(dt => st.weights[dt]).sort();
      const last = ds[ds.length - 1];
      if (!last) return null;
      const w = st.weights[last];
      const b = st.body[last] || {};
      const hcm = Number(st.profile.height_cm) || 0;
      const bmi = b.bmi || (hcm ? Math.round((w / Math.pow(hcm / 100, 2)) * 10) / 10 : null);
      const bf = b.bf || null;
      const male = (st.profile.sex !== 'female');
      const cutBf = male ? 20 : 28, bulkBf = male ? 10 : 18;
      let mode = 'maintain', why = '';
      if ((bmi && bmi >= 24) || (bf && bf > cutBf)) {
        mode = 'cut';
        why = bmi && bmi >= 24 ? `BMI ${bmi}，已经超过 24` : `体脂 ${bf}%，偏高`;
      } else if ((bmi && bmi < 18.5) || (bf && bf < bulkBf)) {
        mode = 'bulk';
        why = bmi && bmi < 18.5 ? `BMI ${bmi}，偏轻` : `体脂 ${bf}%，偏低`;
      } else {
        mode = 'maintain';
        why = bmi ? `BMI ${bmi}、体脂 ${bf ? bf + '%' : '正常'}，都在健康区间` : '身体数据在健康区间';
      }
      // 近 14 天趋势补一句
      let trendTxt = '';
      const recent = ds.slice(-14);
      if (recent.length >= 2) {
        const dw = Math.round((st.weights[recent[recent.length - 1]] - st.weights[recent[0]]) * 10) / 10;
        if (Math.abs(dw) >= 0.3) trendTxt = `近 ${recent.length} 次称重 ${dw > 0 ? '涨' : '降'}了 ${Math.abs(dw)} kg`;
      }
      return { mode, why, trendTxt, w, bmi, bf, date: last };
    })();
    const recName = rec ? DIET_MODES[rec.mode].n : '';
    // 实测数据（跟趋势页那张卡同一套算法）：用来校验"建议的方向"和"你实际在走的方向"
    const rt = computeRealTdee(Store.load());
    const realT = rt.real;
    const bal = realT ? Math.round(realT.avg_intake - realT.tdee) : null;      // 负=缺口
    const dir = bal == null ? null : (bal < -150 ? 'deficit' : (bal > 150 ? 'surplus' : 'balance'));
    const conflict = !!(dir && rec && ((rec.mode === 'bulk' && dir === 'deficit') || (rec.mode === 'cut' && dir === 'surplus')));
    const kgW = bal ? Math.abs(bal) * 7 / 7700 : 0;
    h = meBackBar('饮食目标') + `
      ${rec ? `
      <div class="rec-card">
        <div class="rec-top">
          <span class="rec-label">模式建议</span>
          <span class="rec-pill rec-${rec.mode}">${recName}</span>
        </div>
        <div class="rec-why">${rec.why}${rec.trendTxt ? ' · ' + rec.trendTxt : ''}</div>
        <div class="rec-nums">
          <span>${rec.w} <em>kg</em></span>
          <span>BMI ${rec.bmi || '—'}</span>
          <span>体脂 ${rec.bf ? rec.bf + '%' : '—'}</span>
          <span class="rec-date">${rec.date.slice(5)}</span>
        </div>
        <div class="rec-note">${realT
          ? `实测每天烧 ${realT.tdee} 千卡（用你 ${realT.span_days} 天的数据，${realT.coverage}% 的天数有饮食记录）；公式估算是 ${d.expenditure} 千卡`
          : '还没有足够的实测数据 —— 下面的方向是按公式估的'}</div>
        ${conflict ? `<div class="rec-warn">⚠️ 你现在实际是每天 ${Math.abs(bal)} 千卡${dir === 'deficit' ? '缺口' : '盈余'}（约 ${kgW.toFixed(2)} kg/周），和上面「${recName}」的方向相反。先定一个方向，别两头对着干</div>` : ''}
      </div>` : ''}
      <div class="card">
        <label style="display:block;font-size:12px;color:var(--muted);margin-bottom:8px">目标模式</label>
        <div class="modes" id="dietModes">
          ${Object.entries(DIET_MODES).map(([k, m]) => `
            <button data-mode="${k}" class="${(setting('diet_mode', 'maintain') === k) ? 'on' : ''}">
              <b>${m.n}</b>
            </button>`).join('')}
        </div>
        <div class="hint" id="modeHint" style="margin:10px 0 16px">${modeHintHTML(setting('diet_mode', 'maintain'))}</div>
        <div class="field">
          <label>目标缺口 / 盈余（千卡 / 天）</label>
          <input id="nDef" type="number" inputmode="numeric" value="${-d.targets.deficit}">
          <div class="hint"><b>负数 = 缺口</b>（如 -300），<b>正数 = 盈余</b>（如 300）。填 0 就等于维持。</div>
          <div class="warnline" id="nDefWarn" hidden></div>
        </div>
        <div class="field">
          <label>每日可吃（千卡）</label>
          <input id="nKcal" type="number" inputmode="numeric" value="${d.targets.kcal_budget}">
          <div class="hint" id="nKcalHint">= 全天消耗 ${d.expenditure} ${d.targets.deficit >= 0 ? '− 缺口 ' + Math.abs(d.targets.deficit) : '+ 盈余 ' + Math.abs(d.targets.deficit)}<br><span style="color:var(--muted2)">全天消耗 = 基础代谢 ${(d.expenditure_detail && d.expenditure_detail.resting) ? Math.round(d.expenditure_detail.resting) : '—'} + 手表活动 ${(d.expenditure_detail && d.expenditure_detail.active) ? Math.round(d.expenditure_detail.active) : '—'}</span></div>
        </div>
        <div class="field">
          <label>蛋白质（g）</label>
          <input id="nProt" type="number" inputmode="numeric" value="${d.targets.protein_g}">
          <div class="hint">建议 ${a.protein_g ?? d.targets.protein_g}（体重 × 系数）</div>
        </div>
        <div class="field">
          <label>碳水（g）</label>
          <input id="nCarb" type="number" inputmode="numeric" value="${d.targets.carb_g}">
          <div class="hint">建议 ${a.carb_g ?? d.targets.carb_g}</div>
        </div>
        <div class="field">
          <label>脂肪（g）</label>
          <input id="nFat" type="number" inputmode="numeric" value="${d.targets.fat_g}">
          <div class="hint">建议 ${a.fat_g ?? d.targets.fat_g}</div>
        </div>
        <div class="btnrow">
          <button class="btn primary" id="saveNutri" style="flex:2">保存</button>
          <button class="btn sm" id="resetNutri">恢复建议</button>
        </div>
      </div>`;
  } else if (mePage === 'theme') {
    const cur = d.theme || 'lime';
    h = meBackBar('个性化') + `
      <div class="card">
        <h3>主题色</h3>
        <div class="hint" style="margin:0 0 14px">只影响高亮色（圆环、按钮、数字强调），不影响数据。</div>
        <div class="themepick">
          ${Object.entries(THEMES).map(([k, v]) => `
            <button class="swatch" data-theme="${k}" style="--c:${v}">
              <span class="dot" style="background:${v}"></span>
              <span>${THEME_NAMES[k]}</span>
              ${cur === k ? '<b>✓</b>' : ''}
            </button>`).join('')}
        </div>
      </div>
      ${iconPickerCard()}`;
  } else if (mePage === 'notify') {
    const cfg = notifyCfg();
    const swOne = k => `<label class="sw"><input type="checkbox" data-nfy="${k}" ${cfg[k] ? 'checked' : ''}><i></i></label>`;
    h = meBackBar('通知') + `
      <div class="card">
        <h3>通知渠道</h3>
        <div class="switchrow">
          <div class="stitle">App 内提醒</div>
          <label class="sw"><input type="checkbox" id="swInApp" ${setting('notify_inapp', true) === false ? '' : 'checked'}><i></i></label>
        </div>
        <div class="switchrow" style="margin-top:16px">
          <div class="stitle">锁屏通知</div>
          <label class="sw"><input type="checkbox" id="swPush" ${pushWanted() ? 'checked' : ''} ${pushSupported() ? '' : 'disabled'}><i></i></label>
        </div>
      </div>
      <div class="card">
        <h3>通知我当…</h3>
        ${Object.entries(NOTIFY_ITEMS).map(([k, v], i) => `
          <div class="switchrow" style="margin-top:${i === 0 ? 6 : 16}px">
            <div class="stitle">${v.t}</div>
            ${swOne(k)}
          </div>`).join('')}
        <div class="hint" style="margin-top:14px">「早上提醒上秤」= 早上那一条（⚖️ 上秤时间）：今天还没称才发，已经称过就不打扰；晚上那条只管补记 / 小结，不会重复提醒称重。</div>
      </div>
`;
  } else if (mePage === 'bodydata') {
    const st = Store.load();
    const body = st.body || {}, wts = st.weights || {};
    const dates = Array.from(new Set([...Object.keys(body), ...Object.keys(wts)])).sort().reverse();
    const last = dates[0];
    // 和趋势页一样的逻辑：进来就当「点了本页最后一个点」，不用先点一下才有数字
    const wtAsc = dates.filter(dt => wts[dt]).sort();
    const PAGE_N = 7;
    const trendLastPage = Math.max(0, Math.ceil(wtAsc.length / PAGE_N) - 1);
    const pageIdx0 = Math.min(Math.max(bodyTrendPage, 0), trendLastPage);
    const endI0 = Math.min(wtAsc.length, wtAsc.length - pageIdx0 * PAGE_N);
    const startI0 = Math.max(0, endI0 - PAGE_N);
    const pageLastDate = wtAsc.length ? wtAsc[Math.max(startI0, endI0 - 1)] : null;
    const effDate = (bodySelDate && (body[bodySelDate] || wts[bodySelDate])) ? bodySelDate : pageLastDate;
    const isExplicit = !!bodySelDate;
    const showDate = effDate || last;
    const b = showDate ? (body[showDate] || {}) : {};
    const w = showDate ? wts[showDate] : null;
    const bmi = b.bmi || (w && st.profile.height_cm ? Math.round((w / Math.pow(st.profile.height_cm / 100, 2)) * 10) / 10 : null);

    // 历史：一行一天，日期 + 体重 + 小标签
    const rows = dates.slice(0, 30).map(dt => {
      const bb = body[dt] || {}, ww = wts[dt];
      const tags = [];
      if (bb.bf) tags.push(`${bb.bf}%`);
      if (bb.bmi) tags.push(`BMI ${bb.bmi}`);
      if (bb.ffm) tags.push(`去脂 ${bb.ffm}`);
      return `<div class="hrow">
        <div class="d">${dt.slice(5)}</div>
        <div class="w">${ww ? ww : '—'}<small>${ww ? ' kg' : ''}</small></div>
        <div class="tags">${tags.map(t => `<span>${t}</span>`).join('')}</div>
      </div>`;
    }).join('');

    const wtPts = dates.filter(dt => wts[dt]).sort().map(dt => ({ date: dt, kg: wts[dt] }));
    const nPt = wtPts.length;
    const latestKg = nPt ? wtPts[nPt - 1].kg : null;
    const prevKg = nPt >= 2 ? wtPts[nPt - 2].kg : null;
    const deltaKg = latestKg != null && prevKg != null ? Math.round((latestKg - prevKg) * 10) / 10 : null;
    const kgs = wtPts.map(p => p.kg);
    const minKg = kgs.length ? Math.min(...kgs) : null;
    const maxKg = kgs.length ? Math.max(...kgs) : null;

    h = meBackBar('身体数据') + `
      <div class="card">
        <h3 class="bh">${showDate && showDate !== last ? '所选那天' : '最近一次'}${showDate ? ` <span class="datechip">${showDate.slice(5)}</span>` : ''}</h3>
        ${showDate && showDate !== todayISO() && showDate === last ? `
          <div class="hint" style="margin:8px 0 0">今天还没收到称重数据（最新 ${showDate.slice(5)}）· 站上体脂秤后跑一次「健康采集」</div>` : ''}
        ${showDate ? `
          <div class="bstats">
            <div><div class="k">体重 <em>kg</em></div><div class="v">${w || '—'}</div></div>
            <div><div class="k">体脂率 <em>%</em></div><div class="v">${b.bf || '—'}</div></div>
            <div><div class="k">BMI</div><div class="v">${bmi || '—'}</div></div>
            <div><div class="k">去脂体重 <em>kg</em></div><div class="v">${b.ffm || '—'}</div></div>
          </div>
        ` : `<div class="hint" style="margin:0">还没有数据。站上体脂秤，再点一次「健康采集」。</div>`}
      </div>
      ${nPt >= 1 ? (() => {
        const PAGE = 7;
        const pagesTot = Math.max(1, Math.ceil(nPt / PAGE));
        if (bodyTrendPage > pagesTot - 1) bodyTrendPage = pagesTot - 1;
        if (bodyTrendPage < 0) bodyTrendPage = 0;
        const endIdx = Math.max(Math.min(nPt, nPt - bodyTrendPage * PAGE), PAGE);
        const startIdx = Math.max(0, endIdx - PAGE);
        const pagePts = wtPts.slice(startIdx, endIdx);
        const prevPts = wtPts.slice(Math.max(0, startIdx - PAGE), startIdx);
        const nextPts = wtPts.slice(endIdx, endIdx + PAGE);
        const pageStart = pagePts.length ? pagePts[0].date : (wtPts[0] || {}).date;
        const pageEnd = pagePts.length ? pagePts[pagePts.length - 1].date : pageStart;
        const pv = pagePts.length ? pagePts[pagePts.length - 1].kg : null;
        const pvPrev = pagePts.length >= 2 ? pagePts[pagePts.length - 2].kg : null;
        const pvDelta = pv != null && pvPrev != null ? Math.round((pv - pvPrev) * 10) / 10 : null;
        const pvMin = pagePts.length ? Math.min(...pagePts.map(p => p.kg)) : null;
        const pvMax = pagePts.length ? Math.max(...pagePts.map(p => p.kg)) : null;
        // 点了图上某一天 → 这三组数字跟着那一天走（不点 = 本页最后一个点）
        const selIdx = effDate ? wtPts.findIndex(p => p.date === effDate) : -1;
        const selPt = selIdx >= 0 ? wtPts[selIdx] : null;
        const selPrevPt = selIdx > 0 ? wtPts[selIdx - 1] : null;
        const selDelta = (selPt && selPrevPt) ? Math.round((selPt.kg - selPrevPt.kg) * 10) / 10 : null;
        const selGap = (selPt && selPrevPt) ? Math.round((parseISO(selPt.date) - parseISO(selPrevPt.date)) / 86400000) : null;
        const s1 = selPt ? { l: isExplicit ? '所选' : '最新', v: selPt.kg, u: 'kg' } : { l: '本页最新', v: pv, u: 'kg' };
        const s2v = selPt ? selDelta : pvDelta;
        const s3 = selPt
          ? { l: '距上次', v: selGap != null ? selGap : '—', u: selGap != null ? '天' : '' }
          : { l: '本页区间', v: pvMin != null ? pvMin + '–' + pvMax : '—', u: pvMin != null ? 'kg' : '' };
        return `<div class="card">
          <h3 class="bh">体重趋势
            ${(bodyTrendPage > 0 || isExplicit) ? `<button class="pgbtn" id="btLatest" style="width:auto;height:20px;padding:0 8px;border-radius:10px;font-size:11px;line-height:18px;font-weight:500">回到最新</button>` : ''}
            <span class="pgdate" style="margin-left:auto">${pageStart.slice(5)}–${pageEnd.slice(5)}</span>
          </h3>
          <div class="tsumrow">
            <div class="trendsum">
              <div><span>${s1.l}</span><b class="${selPt ? 'sel' : ''}">${(s1.v != null && s1.v !== '—') ? `${s1.v}<small>${s1.u}</small>` : '—'}</b></div>
              <div><span>较上次</span><b class="${s2v > 0 ? 'up' : (s2v < 0 ? 'down' : '')}">${s2v == null ? '—' : `${(s2v > 0 ? '+' : '') + s2v}<small>kg</small>`}</b></div>
              <div><span>${s3.l}</span><b>${s3.v !== '—' ? `${s3.v}<small>${s3.u}</small>` : '—'}</b></div>
            </div>
            <div class="bminmax"><span>最高 ${pvMax != null ? pvMax : '—'}</span><span>最低 ${pvMin != null ? pvMin : '—'}</span></div>
          </div>
          ${(() => {
            const mk = (pts) => {
              if (pts.length >= 2) {
                return lineChart(pts, pts[0].date, pts[pts.length - 1].date,
                  (effDate && pts.some(p => p.date === effDate)) ? effDate : null, { range: false });
              }
              return `<div class="hint" style="margin:24px 0">这边没有更多记录</div>`;
            };
            return `<div class="chartpager" id="btPager" data-has-prev="${prevPts.length ? 1 : 0}" data-has-next="${nextPts.length ? 1 : 0}">
              <div class="cpslide">${mk(prevPts)}</div>
              <div class="cpslide">${mk(pagePts)}</div>
              <div class="cpslide">${mk(nextPts)}</div>
            </div>`;
          })()}
        </div>`;
      })() : ''}
      ${rows ? `<div class="card"><h3 class="bh">历史记录 <span class="tag" style="color:var(--muted2);background:rgba(255,255,255,.06)">${dates.length} 天</span></h3><div class="hlist">${rows}</div></div>` : ''}
`;
  } else if (mePage === 'about') {
    h = meBackBar('关于与更新') + `
      <div class="about-fill">
      <div class="card">
        <h3>最近更新 <span class="tag" style="color:var(--muted);background:rgba(255,255,255,.06)">${APP_VERSION}</span></h3>
        ${RELEASES.map(r => `
          <div class="rel-date">${r.d}${r.v && r.v !== r.d ? ' · ' + r.v : ''}</div>
          <ul class="rel-list">${r.items.map(t => `<li>${t}</li>`).join('')}</ul>
        `).join('')}
      </div>
      <div class="card tight">
        <h3>这套算法在算什么</h3>
        <div class="hint" style="margin:0;line-height:1.6;font-size:11px">
          <b style="color:var(--text)">基础代谢</b>：Mifflin-St Jeor 公式（体重、身高、年龄、性别）。<br>
          <b style="color:var(--text)">全天消耗</b>：手表给了活动能量 → 基础代谢 + 活动能量；给的是总消耗 → 直接用；都没 → 基础代谢 × 活动系数。<br>
          <b style="color:var(--text)">目标缺口 / 盈余</b>：优先用你在「饮食目标」里填的值（负数=缺口，正数=盈余）；留空则按目标速度 × 7700 ÷ 7 估算，并封顶在当天消耗的 22%。<br>
          <b style="color:var(--text)">还能吃</b>：全天消耗 − 目标缺口 − 已吃。<br>
          <b style="color:var(--text)">实际缺口</b>：全天消耗 − 已吃。正数缺口，负数盈余。<br>
          <b style="color:var(--text)">实测消耗</b>（趋势页）：体重回归斜率 × 7700。<br>
          <span style="color:var(--muted2);font-size:11px">单日有 ±20% 误差，看 7 天平均。</span>
        </div>
      </div>
      </div>`;
  }

  if (mePage) $('#setBody').innerHTML = h;   // 子页就在卡里换内容
  else $('#meBody').innerHTML = h;
  if (S.view === 'me') fitAboutFill();
  if (S.view === 'me') fitMeScroll();
  wireMe();
  if (!mePage) renderSetCard();     // 设置卡里的数字跟着一起刷新
  setCardHeader();
}

/* 关于页：让两张卡正好铺满，页面本身不滚，只有上面那张卡内部滚 */
/* 设置首页：内容装得下就不要上下滑动（手机屏幕也一样） */
function fitMeScroll() {
  const sc = $('#scroller'), body = $('#meBody');
  if (!sc || !body) return;
  if (mePage) { sc.style.overflowY = ''; return; }   // 子页面保持正常滚动（里面有输入框，不能锁）
  const tab = document.querySelector('.tabbar');
  const tabTop = tab ? tab.getBoundingClientRect().top : window.innerHeight - 60;
  let bottom = 0;
  for (const el of body.children) {
    const r = el.getBoundingClientRect();
    if (r.height) bottom = Math.max(bottom, r.bottom);
  }
  sc.style.overflowY = (bottom > 0 && bottom <= tabTop - 8) ? 'hidden' : '';
}

function fitAboutFill() {
  const doc = document.documentElement;
  const fill = document.querySelector('.about-fill');
  if (!fill) { doc.classList.remove('noscroll'); return; }
  const tab = document.querySelector('.tabbar');
  const tabTop = tab ? tab.getBoundingClientRect().top : window.innerHeight - 60;
  const top = fill.getBoundingClientRect().top;
  fill.style.height = Math.max(240, Math.round(tabTop - top - 12)) + 'px';
  // 这一页整页不滚，滚动只发生在上面那张卡里
  doc.classList.add('noscroll');
}

function wireMe() {
  const dbg = $('#dbgLine');
  if (dbg) {
    const tb = document.querySelector('.topbar');
    const tbH = tb ? Math.round(tb.getBoundingClientRect().height) : 0;
    const tbPad = tb ? getComputedStyle(tb).paddingTop : '';
    const st0 = Store.load();
    const histN = (st0.foodHist || []).length, logN = (st0.logs || []).length, delN = (st0.foodHistDel || []).length;
    const delList = (st0.foodHistDel || []).slice(0, 3).join('、');
    dbg.textContent = `视口 ${Math.round(window.innerWidth)}×${Math.round(window.innerHeight)} · 顶栏 ${tbH}px（上边距 ${tbPad}）· ${APP_VERSION}`
      + `\n历史 ${histN} 条 · 记账 ${logN} 条 · 已删 ${delN} 条${delList ? '（' + delList + '…）' : ''}`;
  }
  const back = $('#meBack');
  if (back) back.onclick = () => setBackToRoot();
  $$('.srow').forEach(b => b.onclick = () => {
    mePage = b.dataset.page;
    if (mePage === 'bodydata') { bodySelDate = null; bodyTrendPage = 0; }   // 每次进来从「最近一次」看起
    renderMe();
    // v8.24：进「身体数据」时顺手拉一次最新的体重/体脂（走镜像，不占 Gitee 额度），拿到就重画
    if (mePage === 'bodydata') {
      pullBodyJson(true).then(j => { if (j) { try { refreshBodyViews(); } catch (e) {} } }).catch(() => {});
    }
  });

  const icReset = $('#icReset');
  if (icReset) icReset.onclick = () => {
    try { localStorage.removeItem('icon_override'); } catch (e) {}
    applyStaticIcons(); renderMe(); toast('已恢复全部默认', 1600);
  };

  $$('.icopt').forEach(b => b.onclick = () => {
    const slot = b.dataset.slot, name = b.dataset.name;
    const ov = iconOverride();
    if (name) ov[slot] = name; else delete ov[slot];
    try { localStorage.setItem('icon_override', JSON.stringify(ov)); } catch (e) {}
    applyStaticIcons();
    renderMe();                        // 本页勾选状态 + 其它地方下次渲染都跟着变
    toast(name ? '已换成 ' + name : '已恢复默认', 1600);
  });

  $$('.swatch').forEach(b => b.onclick = async () => {
    const t = b.dataset.theme;
    applyTheme(t);
    if (S.day) S.day.theme = t;   // 先让勾选立刻跟上
    renderMe();
    await api('/api/settings', { theme: t });
    await loadDay();
    toast('已切换主题');
  });

  const nd = $('#nDef'), nk = $('#nKcal');
  if (nd && nk) {
    const exp = (S.day && S.day.expenditure) || 0;
    const bmr = Math.round((S.day && S.day.expenditure_detail && S.day.expenditure_detail.resting) || 0);
    const paintWarn = () => {
      const box = $('#nDefWarn');
      if (!box) return null;
      const adv = deficitAdvice(exp, -Number(nd.value || 0), bmr);
      if (!adv) { box.hidden = true; box.textContent = ''; box.className = 'warnline'; return null; }
      box.hidden = false;
      box.className = 'warnline' + (adv.lv === 'hard' ? ' hard' : '');
      box.textContent = adv.t;
      return adv;
    };
    const paintKcalHint = () => {
      const box = $('#nKcalHint');
      if (!box) return;
      const d = -Number(nd.value || 0);
      const tail = box.querySelector('span') ? box.querySelector('span').outerHTML : '';
      box.innerHTML = `= 全天消耗 ${exp} ${d >= 0 ? '− 缺口 ' + abs0(d) : '+ 盈余 ' + abs0(d)}<br>${tail}`;
    };
    const abs0 = (n) => Math.abs(Math.round(n));
    nd.oninput = () => { nk.value = Math.max(600, Math.round(exp + (Number(nd.value) || 0))); paintWarn(); paintKcalHint(); };
    nk.oninput = () => { nd.value = Math.round((Number(nk.value) || 0) - exp); paintWarn(); };
    paintWarn();
  }
  initSegLens($('#dietModes'));   // 目标模式三格也挂玻璃滑块
  $$('#dietModes button').forEach(b => b.onclick = async () => {
    const k = b.dataset.mode;
    const m = DIET_MODES[k];
    if (!m) return;
    const cur = setting('diet_mode', 'maintain');
    if (cur === k) return;
    const ov = Object.assign({}, setting('target_override', {}));
    delete ov.protein; delete ov.carb; delete ov.fat;
    ov.deficit = m.deficit;                             // 模式同时给一个建议缺口/盈余
    await api('/api/settings', { diet_mode: k, fat_ratio: m.fat, target_override: ov });
    await api('/api/profile', { protein_per_kg: m.p });
    const dir = m.deficit > 0 ? `缺口 ${m.deficit}` : (m.deficit < 0 ? `盈余 ${-m.deficit}` : '不缺口不盈余');
    toast(`已切到「${m.n}」：${dir}，蛋白质 ${m.p} g/kg`, 3200);
    // 只切这一排的选中状态 + 刷新数字，绝不整页重绘：
    // 整页重绘会把这一排连滑块一起重建，滑块就会"跳"（A5 那条规则说的就是这个）
    $$('#dietModes button').forEach(x => x.classList.toggle('on', x.dataset.mode === k));
    const mh = $('#modeHint');                       // 原地改这行建议，不重画整排（重画会让滑块跳）
    if (mh) mh.innerHTML = modeHintHTML(k);
    await loadDay();
    paintNutriValues();
  });

  function paintNutriValues() {
    const d = S.day;
    if (!d || !d.targets) return;
    const set = (sel, v) => { const el = $(sel); if (el && document.activeElement !== el) el.value = v; };
    set('#nDef', -d.targets.deficit);
    set('#nKcal', d.targets.kcal_budget);
    set('#nProt', d.targets.protein_g);
    set('#nCarb', d.targets.carb_g);
    set('#nFat', d.targets.fat_g);
    const hint = $('#nKcalHint');
    if (hint) {
      const def = -Number(($('#nDef') || {}).value || 0);
      const exp = d.expenditure || 0;
      const tail = hint.querySelector('span') ? hint.querySelector('span').outerHTML : '';
      hint.innerHTML = `= 全天消耗 ${exp} ${def >= 0 ? '− 缺口 ' + Math.abs(Math.round(def)) : '+ 盈余 ' + Math.abs(Math.round(def))}<br>${tail}`;
    }
  }

  const sn = $('#saveNutri');
  if (sn) sn.onclick = async () => {
    try {
      const a = (S.day && S.day.targets && S.day.targets.auto) || {};
      // 只有和“建议值”不同的才存成手动值；全都一样就等于恢复自动
      const pick = (sel, autoVal) => {
        const v = Number(($(sel) || {}).value);
        if (!isFinite(v) || v <= 0) return undefined;
        if (autoVal && Math.abs(v - autoVal) < 1) return undefined;
        return v;
      };
      const defRaw = Number(($('#nDef') || {}).value);
      const autoDef = Number(a.deficit || 0);
      const defValue = (isFinite(defRaw) && defRaw !== 0 && Math.abs(-defRaw - autoDef) >= 1) ? -defRaw : undefined;
      const ov = {
        deficit: defValue,
        // 填了缺口/盈余就不用再存「每日可吃」，否则两者会打架
        kcal: defValue !== undefined ? undefined : pick('#nKcal', a.kcal_budget),
        protein: pick('#nProt', a.protein_g),
        carb: pick('#nCarb', a.carb_g),
        fat: pick('#nFat', a.fat_g),
      };
      Object.keys(ov).forEach(k => ov[k] === undefined && delete ov[k]);
      await api('/api/settings', { target_override: ov });
      const adv = (function () {
        const e = (S.day && S.day.expenditure) || 0;
        const b = Math.round((S.day && S.day.expenditure_detail && S.day.expenditure_detail.resting) || 0);
        return deficitAdvice(e, -defRaw, b);
      })();
      if (adv) toast(adv.t, adv.lv === 'hard' ? 5200 : 4200);
      else toast(Object.keys(ov).length ? '已保存饮食目标' : '已恢复为建议值');
      await loadDay();
      renderMe();
    } catch (e) { toast(e.message); }
  };
  const rn = $('#resetNutri');
  if (rn) rn.onclick = async () => {
    if (!await confirmFrosted('恢复建议会把你自己填的目标缺口和营养值清掉，改回自动计算。确定吗？')) return;
    await api('/api/settings', { target_override: {} });
    toast('已恢复建议值');
    await loadDay();
    renderMe();
  };

  // 「通知」页里那几段可直接复制的文字
  $$('[data-copy]').forEach(b => b.onclick = async () => {
    const txt = b.dataset.copy || '';
    try {
      await navigator.clipboard.writeText(txt);
      toast('已复制');
    } catch (e) {
      const ta = document.createElement('textarea');
      ta.value = txt; ta.style.position = 'fixed'; ta.style.opacity = '0';
      document.body.appendChild(ta); ta.select();
      try { document.execCommand('copy'); toast('已复制'); } catch (_) { toast('复制失败，长按文字手动复制'); }
      ta.remove();
    }
  });

  const spIn = $('#swInApp');
  if (spIn) spIn.onchange = () => {
    setSetting('notify_inapp', spIn.checked);
    syncPushConfig();
    toast(spIn.checked ? 'App 内提醒已打开' : 'App 内提醒已静音', 1600);
  };

  const spPush = $('#swPush');
  if (spPush) spPush.onchange = async () => {
    if (spPush.checked) {
      setSetting('push_wanted', true);
      await enablePush();          // 失败也不把开关弹回去，只在下面那行写“正在登记”
    } else {
      setSetting('push_wanted', false);
      await disablePush();
    }
    renderMe();
  };

  $$('[data-nfy]').forEach(b => b.onchange = () => {
    const cfg = notifyCfg();
    cfg[b.dataset.nfy] = b.checked;
    setSetting('notify_flags', cfg);
    syncPushConfig();
    toast(b.checked ? '已打开' : '已关闭', 1400);
  });

  const sw = $('#swToast');
  if (sw) sw.onchange = async () => {
    await api('/api/settings', { sync_toast: sw.checked });
    toast(sw.checked ? '同步提示已打开' : '同步提示已关闭');
  };

  const sp = $('#saveProfile');
  if (sp) sp.onclick = async () => {
    const sex = $('#fSex').value;
    if (sex !== 'male' && sex !== 'female') { toast('先选一下性别（基础代谢差 166 千卡）', 3000); return; }
    try {
      await api('/api/profile', {
        sex: $('#fSex').value,
        birth_year: Number($('#fYear').value),
        height_cm: Number($('#fHeight').value),
        weight_kg: Number($('#fWeight').value),
        activity: $('#fAct').value,
        // 目标速度 / 蛋白系数这两个输入框已经从这里删掉（它们和饮食目标页重复、还会被模式按钮静默覆盖）。
        // 这里原样带回旧值，不许清零，否则自动建议会突然变化。
        goal_rate: Store.load().profile.goal_rate,
        protein_per_kg: Store.load().profile.protein_per_kg,
      });
      const sv = Store.load().profile;
      toast(`已保存：${sv.sex === 'male' ? '男' : '女'} · ${sv.height_cm}cm · ${sv.weight_kg}kg`, 2800);
      await loadDay();
      renderMe();
    } catch (e) { toast(e.message); }
  };


  const hr = $('#hardReload');
  if (hr) hr.onclick = () => hardReloadApp();

  const ec = $('#exportCsv'); if (ec) ec.onclick = () => { downloadCsv(); toast('已导出 CSV'); };
  const ghInp = $('#fGhToken'), ghSave = $('#saveGhToken'), ghNow = $('#syncNow'), ghState = $('#cloudState');
  if (ghState) {
    const t = setting('cloud_synced_at', ''), e = (typeof cloudLastError === 'function' ? cloudLastError() : '');
    ghState.textContent = t ? ('上次同步：' + t) : (cloudToken() ? '还没同步过' : '未开启');
    if (e) ghState.textContent += ' · ' + e;
  }
  const setCloudState = txt => { if (ghState) ghState.textContent = txt; };
  const busyBtn = async (btn, label, fn) => {
    if (btn) { btn.disabled = true; btn.dataset.k = btn.textContent; btn.textContent = label; }
    try { return await fn(); } finally {
      if (btn) { btn.disabled = false; btn.textContent = btn.dataset.k || btn.textContent; }
    }
  };

  if (ghSave) ghSave.onclick = async () => {
    const v = (($('#fGhToken') || {}).value || '').trim();
    if (!v) return toast('先填 token');
    const first = !cloudToken();
    // 先只在内存里放 Token：如果先写盘，Store.save 会把 updatedAt 刷成"现在"，
    // 云端就会误判成本机更新，从而把 iPad 的空数据推上去。
    Store.load().settings.gitee_token = v;
    delete Store.load().settings.gh_token;
    cloudSha = null;
    setCloudState('正在读取云端…');
    const r = await busyBtn(ghSave, '读取中…', async () => {
      // 第一次在这台设备填 Token：强制以云端为准（云端没有才上传本机）
      const pull = await cloudPull(first);
      if (pull === 'pulled') return 'pulled';
      if (pull === true) return 'pushed';       // 云端还没有文件，cloudPull 里已经上传
      if (pull === 'behind') {
        if (first) return 'error';              // 理论上不会发生：force 已经拉过了
        const ok = await cloudPush();           // 已开启过的设备，本机较新才上传
        return ok ? 'pushed' : 'error';
      }
      return 'error';                            // 读不到云端就绝不推，避免覆盖
    });
    // 比较结束再落盘；这一步不再触发自动上传
    setCloudTokenSilently(v);
    if (r === 'pulled') {
      applyTheme(Store.load().settings.theme || 'lime');
      await loadDay();
      renderMe();
      const st = $('#cloudState');
      if (st) st.textContent = '上次同步：' + (setting('cloud_synced_at', '') || '刚刚');
      toast('✅ 已读取云端，数据是较新的那份', 3200);
    } else if (r === 'pushed') {
      setCloudState('上次同步：' + (setting('cloud_synced_at', '') || '刚刚'));
      toast(first ? '✅ 同步已开启，本机数据已上传' : '✅ 已上传本机数据', 3000);
    } else {
      const err = (typeof cloudLastError === 'function' ? cloudLastError() : '') || '同步失败';
      toast('❌ ' + err, 4000);
      setCloudState('失败：' + err);
    }
  };

  const nc = $('#netCheck');
  if (nc) nc.onclick = async () => {
    const t = (setting('gitee_token', '') || '').trim();
    const out = [];
    out.push('令牌：' + (t ? '已填（' + t.slice(0, 4) + '…' + t.slice(-4) + '）' : '❌ 空'));
    // 1) 匿名读（不需要令牌）
    try {
      const r = await fetch('https://gitee.com/api/v5/repos/karen228/calorie-ledger-data/contents/body.json?t=' + Date.now(), { cache: 'no-store' });
      out.push('匿名读：HTTP ' + r.status);
    } catch (e) { out.push('匿名读：❌ ' + (e.message || e)); }
    // 2) 带令牌读 data.json
    try {
      const r = await fetch('https://gitee.com/api/v5/repos/karen228/calorie-ledger-data/contents/data.json?access_token=' + encodeURIComponent(t) + '&t=' + Date.now(), { cache: 'no-store' });
      const txt = await r.text();
      out.push('带令牌读：HTTP ' + r.status + (r.ok ? '（' + txt.length + ' 字节）' : '（' + txt.slice(0, 40) + '）'));
    } catch (e) { out.push('带令牌读：❌ ' + (e.message || e)); }
    const box2 = $('#netCheckOut');
    if (box2) { box2.style.display = 'block'; box2.textContent = out.join('\n'); }
    else await alertFrosted('网络自检\n' + out.join('\n'));
  };

  const ghStop = $('#stopGh');
  if (ghStop) ghStop.onclick = () => {
    setSetting('gitee_token', '');
    setSetting('gh_token', '');
    setSetting('cloud_seen', '');
    cloudSha = null;
    toast('已关闭云端同步，数据仍在本机', 2600);
    renderMe();
  };

  // 体重趋势：原生横向分页（左/当前/右三页），松手自动吸附
  const btLatest = $('#btLatest');
  if (btLatest) btLatest.onclick = () => { bodyTrendPage = 0; bodySelDate = null; renderMe(); };
  const pager = $('#btPager');
  if (pager) {
    const slides = pager.querySelectorAll('.cpslide');
    const mid = () => Math.round(pager.clientWidth * 1);
    pager.scrollLeft = mid();                    // 同步设一次，避免先闪一下第 1 页
    requestAnimationFrame(() => { pager.scrollLeft = mid(); });
    let settleTimer = null, pagerLock = false;
    window.__pagerLock = false;
    pager.addEventListener('scroll', () => {
      if (pagerLock) return;
      clearTimeout(settleTimer);
      // 等惯性滚动停下来（140ms 内没有新的滚动事件）再判定，避免连环跳页
      settleTimer = setTimeout(() => {
        const w = pager.clientWidth || 1;
        const idx = Math.round(pager.scrollLeft / w);
        if (idx === 1) return;
        const hasPrev = pager.getAttribute('data-has-prev') === '1';
        const hasNext = pager.getAttribute('data-has-next') === '1';
        const changing = idx < 1 ? hasPrev : hasNext;
        if (!changing) {
          // 已经到头：柔和滑回中间，不换页
          pager.scrollTo({ left: w, behavior: 'smooth' });
          return;
        }
        // 有下一页：直接换页（不淡出、不闪）
        pagerLock = true;
        bodyTrendPage = Math.max(0, bodyTrendPage + (idx < 1 ? 1 : -1));
        bodySelDate = null;
        renderMe();
        requestAnimationFrame(() => { pagerLock = false; });
      }, 140);
    });
    slides.forEach(sl => {
      sl.querySelectorAll('circle[data-d]').forEach(c => {
        c.style.cursor = 'pointer';
        c.onclick = (ev) => {
          ev.stopPropagation();
          bodySelDate = c.getAttribute('data-d');
          renderMe();
        };
      });
    });
  }
  const btWrap = null;
  if (btWrap) {
    $$('#btWrap circle[data-d]').forEach(c => {
      c.style.cursor = 'pointer';
      c.onclick = () => { bodySelDate = c.getAttribute('data-d'); renderMe(); };
    });
    const svgEl = btWrap.querySelector('svg');
    let sx = 0, sy = 0, dragging = false, dx = 0;
    btWrap.addEventListener('touchstart', (e) => {
      const t0 = e.touches[0]; sx = t0.clientX; sy = t0.clientY; dragging = false; dx = 0;
      if (svgEl) svgEl.style.transition = 'none';
    }, { passive: true });
    btWrap.addEventListener('touchmove', (e) => {
      const t0 = e.touches[0];
      dx = t0.clientX - sx;
      const dy = t0.clientY - sy;
      if (!dragging && Math.abs(dx) > 6 && Math.abs(dx) > Math.abs(dy)) dragging = true;
      if (dragging && svgEl) {
        const lim = (btWrap.clientWidth || 320) * 0.38;
        const tx = Math.max(-lim, Math.min(lim, dx * 0.85));
        svgEl.style.transform = 'translateX(' + tx.toFixed(1) + 'px)';
        e.preventDefault();
      }
    }, { passive: false });
    btWrap.addEventListener('touchend', () => {
      if (svgEl) {
        svgEl.style.transition = 'transform .22s cubic-bezier(.32,.72,0,1)';
        svgEl.style.transform = '';
      }
      if (!dragging) return;               // 没拖动 → 交给点击
      const w = btWrap.clientWidth || 320;
      const shift = Math.round(dx / w * 7) || (dx > 0 ? 1 : -1);
      bodyTrendEnd = addDays(bodyTrendEnd, -shift);   // 往右拖 = 看更早
      bodySelDate = null;
      renderMe();
    });
  }

  const cfp = $('#cloudForcePull');
  if (cfp) cfp.onclick = async () => {
    if (!cloudToken()) return toast('先填 token 并保存');
    if (!await confirmFrosted('用云端那份数据覆盖这台设备？本机还没上传的改动会丢。')) return;
    const r = await busyBtn(cfp, '拉取中…', async () => await cloudPull(true));
    if (r === 'pulled') { await loadDay(); renderMe(); toast('✅ 已用云端覆盖本机', 2600); }
    else toast('❌ 拉取失败：' + ((typeof cloudLastError === 'function' ? cloudLastError() : '') || '检查网络/token'), 4000);
  };

  const cfpush = $('#cloudForcePush');
  if (cfpush) cfpush.onclick = async () => {
    if (!cloudToken()) return toast('先填 token 并保存');
    if (!await confirmFrosted('用这台设备的记录覆盖云端？另一台设备上独有的记录会被清掉。')) return;
    cloudLast = '';
    const r = await busyBtn(cfpush, '上传中…', async () => await cloudPush());
    if (!r) {
      toast('❌ 上传失败：' + ((typeof cloudLastError === 'function' ? cloudLastError() : '') || '检查网络/令牌'), 5200);
      return;
    }
    // 回读校验：确认云端真的变了
    let verified = false, upAt = '';
    try {
      const t = await cloudVerify();
      verified = !!t.ok; upAt = t.updatedAt || '';
    } catch (e) {}
    if (verified) {
      setCloudState('上次同步：' + (setting('cloud_synced_at', '') || '刚刚'));
      toast('✅ 已用本机覆盖云端（云端时间 ' + (upAt.slice(5, 16).replace('T', ' ')) + '）', 3200);
    } else {
      toast('⚠️ 上传返回成功，但回读没看到变化 —— 可能是令牌权限或限流', 5200);
    }
  };

  if (ghNow) ghNow.onclick = async () => {
    if (!cloudToken()) return toast('先在下面填 token 并保存');
    setCloudState('正在同步…');
    const r = await busyBtn(ghNow, '同步中…', async () => {
      const pull = await cloudPull();
      if (pull === 'pulled') return 'pulled';
      const ok = await cloudPush();
      return ok ? 'pushed' : false;
    });
    if (r === 'pulled') {
      toast('✅ 已从云端拉取最新数据', 3000);
      await loadDay(); renderMe();
      setCloudState('上次同步：' + (setting('cloud_synced_at', '') || '刚刚'));
    } else if (r === 'pushed') {
      toast('✅ 已上传到云端', 2600);
      setCloudState('上次同步：' + (setting('cloud_synced_at', '') || '刚刚'));
    } else {
      const err = (typeof cloudLastError === 'function' ? cloudLastError() : '') || '同步失败';
      toast('❌ ' + err, 4000);
      setCloudState('失败：' + err);
    }
  };

  const ba = $('#backupAt');
  if (ba) {
    const t = Store.load().settings.lastBackupAt;
    ba.textContent = t ? '上次文件备份：' + t : '还没有文件备份过';
  }
  const ej = $('#exportJson');
  if (ej) ej.onclick = async () => {
    try {
      const r = await exportJson();
      if (r === 'cancel') return;
      const t = new Date().toLocaleString('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' });
      setSetting('lastBackupAt', t);
      if (ba) ba.textContent = '上次文件备份：' + t;
      toast(r === 'shared' ? '已存到「文件」/ iCloud Drive' : '已下载备份文件', 3000);
    } catch (e) { toast('备份失败：' + e.message, 4000); }
  };
  const ij = $('#importJson');
  if (ij) ij.onclick = async () => {
    if (!await confirmFrosted('恢复会用备份覆盖这台设备现在的全部数据，确定吗？')) return;
    $('#importFile').click();
  };
  const iff = $('#importFile');
  if (iff) iff.onchange = async e => {
    const f = e.target.files[0];
    if (!f) return;
    try {
      importJson(await f.text());
      toast('已恢复备份');
      applyTheme(Store.load().settings.theme || 'lime');
      await loadDay();
      renderMe();
    } catch (err) {
      toast('恢复失败：' + err.message, 4000);
    }
    e.target.value = '';
  };

  const pk = $('#peekKey');
  if (pk) pk.onclick = () => {
    const inp = $('#fKey');
    const key = String(Store.load().settings.dashscope_key || '');
    if (inp.type === 'text') {
      inp.type = 'password'; inp.value = ''; pk.textContent = '查看已保存的 Key';
    } else {
      inp.type = 'text'; inp.value = key; pk.textContent = '隐藏';
      setTimeout(() => { try { inp.focus(); inp.select(); } catch (e) {} }, 50);
    }
  };

  const sk = $('#saveKey');
  if (sk) sk.onclick = async () => {
    const v = $('#fKey').value.trim();
    if (!v) return toast('先填入 Key');
    try {
      await api('/api/settings', { dashscope_key: v });
      const sv = Store.load().profile;
      toast(`已保存：${sv.sex === 'male' ? '男' : '女'} · ${sv.height_cm}cm · ${sv.weight_kg}kg`, 2800);
      await loadDay();
      renderMe();
    } catch (e) { toast(e.message); }
  };
  const tk = $('#testKey');
  if (tk) tk.onclick = async () => {
    const v = $('#fKey').value.trim();
    if (v) await api('/api/settings', { dashscope_key: v });
    try {
      const r = await api('/api/settings/test', {});
      toast('连接正常：' + r.message);
    } catch (e) { toast(e.message, 5000); }
  };
}

/* 强制更新：清掉 Service Worker 和缓存，带随机参数重开（绕开 Pages 的 CDN 缓存）
   右上角那个按钮和设置页里的按钮都调它 */
async function hardReloadApp() {
  // 只带时间戳重新打开，**不再**注销 Service Worker、也不再清空缓存：
  // 注销 + 清缓存会让下一次打开完全依赖网络，网络一抖就停在"全是破折号"的死界面。
  // SW 本来就是"先走网络、失败才用缓存"，带 ?r= 就能绕过 HTTP 缓存拿到最新版。
  toast('正在更新…', 1200);
  setTimeout(() => {
    const u = location.pathname + '?r=' + Date.now();
    location.replace(u);
  }, 400);
}

/* ---------------- 体重 ---------------- */
function openWeight() {
  // 体脂秤那份（健康采集）每天会自动写进 weights，这里直接带出来，不用手敲
  const st = Store.load();
  const ws = st.weights || {};
  const dates = Object.keys(ws).sort();
  const latest = dates.length ? ws[dates[dates.length - 1]] : null;
  $('#weightInput').value = ws[S.date] || ws[S.today] || latest || st.profile.weight_kg || '';
  $('#weightMask').classList.add('on');
  $('#weightSheet').classList.add('on');
  setTimeout(() => $('#weightInput').focus(), 300);
}
function closeWeight() {
  $('#weightMask').classList.remove('on');
  $('#weightSheet').classList.remove('on');
}

async function saveWeight() {
  const v = Number($('#weightInput').value);
  if (!v || v < 20 || v > 300) return toast('填个体重数字');
  try {
    await api('/api/weight', { date: S.date, kg: v });
    closeWeight();
    toast('已记录');
    await loadDay();
    if (S.view === 'trends') loadTrends();
  } catch (e) { toast(e.message); }
}

/* ---------------- 导航 ---------------- */
function refreshTodayIfNeeded() {
  const t = todayISO();
  if (t === S.today) return false;
  S.today = t;
  if (S.date !== t) S.date = t;
  loadDay();
  return true;
}
function switchView(v) {
  if (v !== 'me') closeSetCard();   // 换页时把设置卡收起来（它是浮在页面上的）
  refreshTodayIfNeeded();
  if (v !== 'me') document.documentElement.classList.remove('noscroll');
  if (v !== 'me') { const sc0 = $('#scroller'); if (sc0) sc0.style.overflowY = ''; }
  if (window.scTop) window.scTop();
  S.view = v;
  $$('.view').forEach(el => el.classList.toggle('on', el.id === 'view-' + v));
  $$('.tab').forEach(b => b.classList.toggle('on', b.dataset.view === v));
  if (window.__dockLens) window.__dockLens.go(document.querySelector('.tab.on'));   // 液态滑块跟到新选中的 Tab
  document.body.classList.toggle('view-me', v === 'me');
  document.body.classList.toggle('view-trends', v === 'trends');
  if (window.scTop) window.scTop();
  if (v === 'trends') { renderTrends(); loadTrends(); initTrendSegLens(); const sg = $('#trendSeg'); if (sg && sg.__lensSync) setTimeout(sg.__lensSync, 30); }
  if (v === 'me') {
    mePage = null; renderMe();
    // v8.24：打开「设置」也顺手拉一次身体数据，列表行上的体重/体脂跟着更新
    pullBodyJson(true).then(j => { if (j) { try { refreshBodyViews(); } catch (e) {} } }).catch(() => {});
  }
}

/* ---------------- 自动同步帮助 ---------------- */

